window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s7-1552","number":1552,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما مناسبة قوله تعالى: ﴿لا يستكبرون عن عبادته﴾ بعد النهي عن الغفلة؟","answer":"يعلل الحث على الذكر بحال الملائكة: علو منزلتهم لم يحملهم على ترك العبادة، فالبشر أولى باجتناب الغفلة والاستكبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص512، تحت عنوان «بلاغة التعبير بصيغة المضارع في قوله لا يستكبرون»","url":""}]},{"id":"s7-1553","number":1553,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما دلالة تعدية الاستكبار بـ﴿عن﴾؟","answer":"تصور الاستكبار انصرافًا ومجاوزةً للعبادة؛ فنفت عن الملائكة أن يحملهم علوهم على البعد عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص512–513، تحت «دلالة المجاوزة بحرف الجر عن»","url":""}]},{"id":"s7-1554","number":1554,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما دلالة إضافة العبادة إلى ضميره في ﴿عبادته﴾؟","answer":"تخص العبادة بالله الذي ذُكر بوصف الرب، وتبرز شرفها لأنها عبادة له وحده لا لغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص513–514، تحت «فائدة إضافة العبادة إلى ضمير اسم الجلالة»","url":""}]},{"id":"s7-1555","number":1555,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما دلالة العطف في ﴿ويسبحونه وله يسجدون﴾؟","answer":"فصّل عبادتهم بعد نفي الاستكبار: ينزهونه بأقوالهم واعتقادهم، ويخضعون له بالسجود؛ فجمع التنزيه والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص514–515، تحت عنوان «أثر الواو في قوله وله يسجدون في المعنى»","url":""}]},{"id":"s7-1556","number":1556,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما دلالة تقديم ﴿له﴾ على ﴿يسجدون﴾؟","answer":"يفيد الاختصاص: لله وحده يسجدون، لا يشركون به في غاية الخضوع أحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص515–516، تحت «سر تقديم الجار والمجرور وله على الفعل يسجدون»","url":""}]},{"id":"s7-1557","number":1557,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما سرّ تقديم التسبيح على السجود؟","answer":"ذكر التسبيح يبين تنزيههم لله عن النقائص والشريك، ثم أفرد السجود بالذكر لمزيد شرفه وكونه غاية الخضوع. فالانتقال يجمع التنزيه وكمال العبادة، ويختم بأعظم صور الخضوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص516، تحت عنوان «إيثار استعمال السجود دون غيره من ألوان العبادة»","url":""}]},{"id":"s7-1558","number":1558,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما دلالة المضارع في ﴿يستكبرون... يسبحونه... يسجدون﴾؟","answer":"يدل على تجدد هذه الأحوال واستمرارها؛ فلا يقع منهم استكبار، ويتكرر تسبيحهم وسجودهم بلا فتور.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص511، تحت عنوان «بلاغة التعبير بصيغة المضارع في قوله لا يستكبرون»","url":""}]},{"id":"s7-1559","number":1559,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما دلالة علاقة ختام السورة بأولها في خطاب النبي الأكرم وتوجيهه وتثبيته؟","answer":"افتتحت السورة باتباع الوحي، وختمت بأثر الاتباع وغايته: تنزيه الله والخضوع له وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص516–517، تحت عنوان «علاقة ختام السورة بأولها في خطاب النبي الأكرم وتوجيهه وتثبيته»","url":""}]},{"id":"s7-1666","number":1666,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما دلالة إيثار استعمال السجود دون غيره من ألوان العبادة؟","answer":"جمع طرفاها بين تلقي الأمر وتحقيق العبودية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص516–517، تحت عنوان «إيثار استعمال السجود دون غيره من ألوان العبادة»","url":""}]},{"id":"s7-1667","number":1667,"surah":7,"verses":[18],"references":[{"surah":7,"verses":[18]}],"verseLabel":"الأعراف: 18","question":"ما سر تقديم التابعين في ﴿لَّمَن تَبِعَكَ مِنْهُمْ لَأَمْلَأَنَّ جَهَنَّمَ مِنكُمْ أَجْمَعِينَ﴾، وتقديم ملء جهنم في ص؟","answer":"تقدّم في ص قبل القصة الكلام على جهنم وعذابها فقدّم ما يتعلق بها، وفي الأعراف تأخّر ذكرها فأخّره. وفي الأعراف أفاض إبليس فيما سيحتال به لذرية آدم ليتبعوه: القعود لهم على الصراط، وإتيانهم من بين أيديهم ومن خلفهم وعن أيمانهم وعن شمائلهم، فناسب أن يُقدَّم من تبعه.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص69–70.","url":""}]},{"id":"s7-1668","number":1668,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما سر ذكر موسى باسمه في ﴿وَلَمَّا جَاءَ مُوسَىٰ لِمِيقَاتِنَا﴾، وذكر النبي ﷺ بوصف العبودية في ﴿أَسْرَىٰ بِعَبْدِهِ﴾؟","answer":"لما ذكر موسى عند المناجاة باسمه كانت عاقبة ذلك أن خرّ صعقًا، ولما ذكر محمدًا ﷺ بصفة العبودية عُرج به إلى السماوات العلى. فلا يحسن أن يُقال: «ولما جاء عبدنا موسى» فينسبه إلى نفسه ثم يصعقه، لأن الإضافة إليه سبحانه تشريف وحفظ.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص205.","url":""}]},{"id":"s7-1669","number":1669,"surah":7,"verses":[167,169],"references":[{"surah":7,"verses":[167,169]}],"verseLabel":"الأعراف: 167، 169","question":"ما سر تأكيد سرعة العقاب باللام في ﴿إِنَّ رَبَّكَ لَسَرِيعُ الْعِقَابِ﴾، مع ترك اللام في ﴿وَالدَّارُ الْآخِرَةُ خَيْرٌ﴾ وهي في الأنعام ﴿وَلَلدَّارُ الْآخِرَةُ﴾؟","answer":"السياق في آيات الأعراف في العقوبات الدنيوية لبني إسرائيل: أخذ الظالمين بعذاب بئيس، ومسخهم قردة، وبعث من يسومهم سوء العذاب. فأكّد سرعة العقاب لأنه عاجلهم في الدنيا، ولم يؤكد الآخرة. أما آيات الأنعام فالكلام فيها على الدار الآخرة نفسها، فأكّدها باللام.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص131–132.","url":""}]},{"id":"s7-1670","number":1670,"surah":7,"verses":[10],"references":[{"surah":7,"verses":[10]}],"verseLabel":"الأعراف: 10","question":"ما دلالة افتتاح قصة آدم هنا بـ﴿وَلَقَدْ مَكَّنَّاكُمْ فِي الْأَرْضِ وَجَعَلْنَا لَكُمْ فِيهَا مَعَايِشَ قَلِيلًا مَّا تَشْكُرُونَ﴾، وفي البقرة ﴿خَلَقَ لَكُم مَّا فِي الْأَرْضِ جَمِيعًا﴾؟","answer":"القصة في البقرة مبنية على تكريم آدم، أما في الأعراف فالتكريم فيها ثانوي. ولذلك كان ﴿خَلَقَ لَكُم مَّا فِي الْأَرْضِ جَمِيعًا﴾ أدلّ على التكريم من ﴿مَكَّنَّاكُمْ فِي الْأَرْضِ﴾، وختم آية الأعراف بـ﴿قَلِيلًا مَّا تَشْكُرُونَ﴾ فهي في مقام العتاب. ثم إن القصة وقعت في سياق العقوبات وإهلاك الأمم ﴿وَكَم مِّن قَرْيَةٍ أَهْلَكْنَاهَا﴾، فبُنيت على ما يناسب هذا السياق.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص294.","url":""}]},{"id":"s7-1671","number":1671,"surah":7,"verses":[11],"references":[{"surah":7,"verses":[11]}],"verseLabel":"الأعراف: 11","question":"ما سر الاكتفاء بـ﴿لَمْ يَكُن مِّنَ السَّاجِدِينَ﴾ في وصف معصية إبليس، وفي البقرة ﴿أَبَىٰ وَاسْتَكْبَرَ وَكَانَ مِنَ الْكَافِرِينَ﴾؟","answer":"جمع في البقرة لإبليس الإباء والاستكبار والكفر للدلالة على شناعة معصيته في حق آدم الذي أكرمه الله وعلّمه، لأن القصة هناك مبنية على التكريم، ولم يجمع بينها في غير هذا الموضع. أما في الأعراف فالتكريم ثانوي والسياق سياق عقوبات، فاكتفى بنفي كونه من الساجدين.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص294.","url":""}]},{"id":"s7-1672","number":1672,"surah":7,"verses":[17],"references":[{"surah":7,"verses":[17]}],"verseLabel":"الأعراف: 17","question":"ما سر الملاءمة بين قول إبليس ﴿وَلَا تَجِدُ أَكْثَرَهُمْ شَاكِرِينَ﴾ وقوله في مقدمة القصة ﴿قَلِيلًا مَّا تَشْكُرُونَ﴾؟","answer":"قطع إبليس عهدًا على نفسه أن يحول بين بني آدم والشكر، فوقعوا في شركه وكانوا كما أراد ﴿قَلِيلًا مَّا تَشْكُرُونَ﴾، فلاءم التعبير بين الآيتين أجمل ملاءمة. وصدق فيهم قوله ﴿وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُ﴾، فاستجابوا لوسوسته كما استجاب لها أبوهم من قبل.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص301.","url":""}]},{"id":"s7-1673","number":1673,"surah":7,"verses":[35],"references":[{"surah":7,"verses":[35]}],"verseLabel":"الأعراف: 35","question":"ما سر التعبير بـ﴿فَمَنِ اتَّقَىٰ وَأَصْلَحَ﴾ هنا، وفي الأنعام ﴿فَمَنْ آمَنَ وَأَصْلَحَ﴾؟","answer":"وردت التقوى ومشتقاتها في الأعراف إحدى عشرة مرة وفي الأنعام سبع مرات، وورد الإيمان ومشتقاته في الأنعام أربعًا وعشرين وفي الأعراف إحدى وعشرين. فوضع كل لفظ في السورة التي يتردد فيها أكثر، مراعاةً للسمة التعبيرية لكل سورة.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص182.","url":""}]},{"id":"s7-1674","number":1674,"surah":7,"verses":[55,56,205],"references":[{"surah":7,"verses":[55,56,205]}],"verseLabel":"الأعراف: 55، 56، 205","question":"ما سر ذكر الخوف في ﴿وَادْعُوهُ خَوْفًا وَطَمَعًا﴾ و﴿تَضَرُّعًا وَخِيفَةً﴾، مع تركه في الأنعام ﴿تَضَرُّعًا وَخُفْيَةً﴾؟","answer":"الدعاء والذكر في آيتي الأعراف في مقام العبادة، فالخوف المذكور فيهما خوف من الله خالص. أما آية الأنعام ففي مقام الخوف مما يحيط بالناس في ظلمات البر والبحر، فلو ذكر الخوف هناك لانصرف إلى تلك الأمور المخوفة لا إلى الخوف من الله.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص70–71.","url":""}]},{"id":"s7-1675","number":1675,"surah":7,"verses":[57],"references":[{"surah":7,"verses":[57]}],"verseLabel":"الأعراف: 57","question":"ما دلالة الجمع في ﴿وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ﴾؟","answer":"يستعمل القرآن «الرياح» بالجمع في الخير والرحمة، و«الريح» بالإفراد في الشر والعقوبات، كقوله ﴿رِيحٌ فِيهَا عَذَابٌ أَلِيمٌ﴾. فلما كان المقام هنا مقام البشارة بالرحمة جاء بالجمع. ولم يستعمل الريح المفردة في الخير إلا في موطن واحد من سورة يونس أعقبها فيه بالريح العاصف.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص13.","url":""}]},{"id":"s7-1676","number":1676,"surah":7,"verses":[78,91],"references":[{"surah":7,"verses":[78,91]}],"verseLabel":"الأعراف: 78، 91","question":"ما سر العطف بالفاء في ﴿فَأَخَذَتْهُمُ الرَّجْفَةُ﴾، وبالواو في هود ﴿وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ﴾؟","answer":"سياق الأعراف سياق تعجيل العقوبات لمستحقيها في الدنيا، فقد بدأت بـ﴿وَكَم مِّن قَرْيَةٍ أَهْلَكْنَاهَا فَجَاءَهَا بَأْسُنَا﴾، فذكر إنزال العقوبة بالفاء الدالة على التعقيب. أما سورة هود فسياقها في الإمهال والتمتيع ﴿يُمَتِّعْكُم مَّتَاعًا حَسَنًا إِلَىٰ أَجَلٍ مُّسَمًّى﴾، فجاء بالواو.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص84–86.","url":""}]},{"id":"s7-1677","number":1677,"surah":7,"verses":[85],"references":[{"surah":7,"verses":[85]}],"verseLabel":"الأعراف: 85","question":"ما سر التعبير بـ﴿فَأَوْفُوا الْكَيْلَ وَالْمِيزَانَ﴾، وفي هود ﴿أَوْفُوا الْمِكْيَالَ وَالْمِيزَانَ﴾؟","answer":"«الكيل» هو المصدر أي الحدث، و«المكيال» آلة الكيل وهو من الأموال. والقصة في هود يشيع فيها ذكر الأموال ﴿أَوْ أَن نَّفْعَلَ فِي أَمْوَالِنَا مَا نَشَاءُ﴾ و﴿وَرَزَقَنِي مِنْهُ رِزْقًا حَسَنًا﴾ فناسبها المكيال. أما القصة في الأعراف فيشيع فيها أمر الاعتقاد ومحاربة الفساد، كالقعود بكل صراط والصدّ عن سبيل الله، ومفتتح السورة في العقيدة، فناسبها ذكر المصدر «الكيل».","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص301–303.","url":""}]},{"id":"s7-1678","number":1678,"surah":7,"verses":[91],"references":[{"surah":7,"verses":[91]}],"verseLabel":"الأعراف: 91","question":"ما سر ذكر «الرجفة» وإفراد «الدار» في ﴿فَأَخَذَتْهُمُ الرَّجْفَةُ فَأَصْبَحُوا فِي دَارِهِمْ جَاثِمِينَ﴾، وفي هود «الصيحة» و﴿دِيَارِهِمْ﴾؟","answer":"ذكر في الأعراف من سيئات قوم شعيب أكثر مما في هود، ووصفهم بالكفر وهو أشد من الظلم، فجاء بالرجفة وهي الزلزلة وهي أشد من الصيحة. وأفرد الدار مع الرجفة وجمعها مع الصيحة، لأن الصيحة يبلغ مداها أبعد من الرجفة، ولما كان الظلم أعم كان أنسب بذكر الديار التي هي أعم من الدار.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص305–306.","url":""}]},{"id":"s7-1679","number":1679,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"ما سر الختم بـ﴿كَذَٰلِكَ يَطْبَعُ اللَّهُ عَلَىٰ قُلُوبِ الْكَافِرِينَ﴾، وفي يونس ﴿عَلَىٰ قُلُوبِ الْمُعْتَدِينَ﴾؟","answer":"ذكر الكافرين في الأعراف بمقابل قوله قبلها ﴿وَلَوْ أَنَّ أَهْلَ الْقُرَىٰ آمَنُوا وَاتَّقَوْا﴾ لأن الكفر مقابل الإيمان، ولما قاله شعيب ﴿فَكَيْفَ آسَىٰ عَلَىٰ قَوْمٍ كَافِرِينَ﴾. أما في يونس فتقدّمت قصة نوح وقوله ﴿فَأَجْمِعُوا أَمْرَكُمْ … ثُمَّ اقْضُوا إِلَيَّ﴾، أي للاعتداء عليه، فناسب ذكر المعتدين.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص59–60.","url":""}]},{"id":"s7-1680","number":1680,"surah":7,"verses":[101],"references":[{"surah":7,"verses":[101]}],"verseLabel":"الأعراف: 101","question":"ما سر إضافة الرسل إلى الأقوام في ﴿وَلَقَدْ جَاءَتْهُمْ رُسُلُهُم بِالْبَيِّنَاتِ﴾، وإضافتهم إلى الله في المائدة ﴿جَاءَتْهُمْ رُسُلُنَا﴾؟","answer":"آية المائدة فيما شرع الله من الأحكام التي جاءت بها رسله من عنده، فأضافهم إليه سبحانه. أما في الأعراف فالكلام على أهل القرى وموقفهم من رسلهم الذين جاؤوهم بما ينفعهم ﴿أَفَأَمِنَ أَهْلُ الْقُرَىٰ﴾، فلما كان الكلام على أهل القرى أضاف الرسل إليهم.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص40–41.","url":""}]},{"id":"s7-1681","number":1681,"surah":7,"verses":[103],"references":[{"surah":7,"verses":[103]}],"verseLabel":"الأعراف: 103","question":"ما سر تقديم ﴿بِآيَاتِنَا﴾ على ﴿إِلَىٰ فِرْعَوْنَ وَمَلَئِهِ﴾ هنا، وتأخيرها في يونس؟","answer":"ذكر في الأعراف أن موسى أظهر الآيات أمام فرعون وملئه ﴿فَأَلْقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعْبَانٌ مُّبِينٌ﴾، وأظهرها أمام السحرة ﴿فَإِذَا هِيَ تَلْقَفُ مَا يَأْفِكُونَ﴾. أما في يونس فلم يذكر أنه أظهر آية أمام فرعون ولا أمام السحرة. فلما كان الاهتمام بذكر الآيات في الأعراف قدّمها، وأخّرها في يونس.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص60–61.","url":""}]},{"id":"s7-1682","number":1682,"surah":7,"verses":[107],"references":[{"surah":7,"verses":[107]}],"verseLabel":"الأعراف: 107","question":"ما سر التعبير بـ«الثعبان» في ﴿فَأَلْقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعْبَانٌ مُّبِينٌ﴾ دون «الحية»؟","answer":"الثعبان هو الحية الضخمة الطويلة، أما الحية فتطلق على الصغير والكبير، فكل ثعبان حية وليس كل حية ثعبانًا. ولم يرد لفظ الثعبان إلا أمام فرعون وملئه خاصة، لأنه أراد أن يُرهب فرعون ويدعوه ذلك إلى الإيمان.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص45.","url":""}]},{"id":"s7-1683","number":1683,"surah":7,"verses":[136],"references":[{"surah":7,"verses":[136]}],"verseLabel":"الأعراف: 136","question":"ما سر التعبير بـ«اليمّ» في ﴿فَانتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَاهُمْ فِي الْيَمِّ﴾ دون «البحر»؟","answer":"يستعمل القرآن «اليمّ» في مقام الخوف والعقوبة والإغراق، ولم يستعمله في النجاة. أما «البحر» فيستعمله عامًا في النعم وغيرها، وفي مقام نجاة بني إسرائيل استعمل البحر لا اليمّ. فلما كان المقام هنا مقام انتقام من فرعون وقومه عبّر باليمّ.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص44.","url":""}]},{"id":"s7-1684","number":1684,"surah":7,"verses":[160],"references":[{"surah":7,"verses":[160]}],"verseLabel":"الأعراف: 160","question":"ما فائدة «كانوا» في ﴿وَمَا ظَلَمُونَا وَلَٰكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ﴾، وحذفها في آل عمران ﴿وَلَٰكِنْ أَنفُسَهُمْ يَظْلِمُونَ﴾؟","answer":"آيتا البقرة والأعراف في قوم قد مضوا وهم بنو إسرائيل، فناسبهم ذكر «كان» الدالة على المضي. أما آية آل عمران فليست في أقوام ماضين بل مثل ضربه الله لكل عصر ﴿مَثَلُ مَا يُنفِقُونَ﴾. ونقل السامرائي نحو هذا عن الكرماني في «البرهان».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص125–126.","url":""}]},{"id":"s7-1685","number":1685,"surah":7,"verses":[168],"references":[{"surah":7,"verses":[168]}],"verseLabel":"الأعراف: 168","question":"ما دلالة التعبير بالرجوع في ﴿وَبَلَوْنَاهُم بِالْحَسَنَاتِ وَالسَّيِّئَاتِ لَعَلَّهُمْ يَرْجِعُونَ﴾ دون الردّ؟","answer":"يستعمل القرآن الفعل «ردّ» في الغالب للأمور الثقيلة والمستكرهة، أما «رجع» فيستعمله في الرجوع إلى الله بالتوبة والإنابة، ولم يستعمل الردّ في مثل هذا المعنى. فمعنى ﴿يَرْجِعُونَ﴾ هنا: يرجعون إلى ربهم فيتوبون، كقوله ﴿وَأَخَذْنَاهُم بِالْعَذَابِ لَعَلَّهُمْ يَرْجِعُونَ﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص47، 56.","url":""}]},{"id":"s7-1686","number":1686,"surah":7,"verses":[178],"references":[{"surah":7,"verses":[178]}],"verseLabel":"الأعراف: 178","question":"ما سر إثبات الياء في ﴿مَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِي﴾، وحذفها في الإسراء والكهف ﴿فَهُوَ الْمُهْتَدِ﴾؟","answer":"يُراعي القرآن تردد اللفظ في السورة، فيزيد في موطن الزيادة ويحذف في موطن الاجتزاء. وقد تردد لفظ الهداية في الأعراف سبع عشرة مرة، أكثر مما تردد في سورتي الإسراء (ثماني مرات) والكهف (ست مرات) مجتمعتين، فلما زادت ألفاظ الهداية في الأعراف زاد لفظ «المهتدي» بإثبات الياء.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص87–88.","url":""}]},{"id":"s7-1687","number":1687,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما سر التعبير بـ﴿وَجَعَلَ مِنْهَا زَوْجَهَا﴾، وفي النساء ﴿وَخَلَقَ مِنْهَا زَوْجَهَا﴾؟","answer":"الجعل في الغالب حالة بعد الخلق، كقوله ﴿ثُمَّ يَجْعَلُهُ حُطَامًا﴾، والخلق ابتداء. وآية النساء في أصل الخلق، أما آية الأعراف فليست في آدم وحواء، بدليل قوله فيها ﴿فَلَمَّا آتَاهُمَا صَالِحًا جَعَلَا لَهُ شُرَكَاءَ﴾، فهي فيمن بعدهما من بني آدم، فناسبها الجعل.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص32–33.","url":""}]},{"id":"s7-1688","number":1688,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما سر التعبير بـ﴿ثُمَّ كِيدُونِ فَلَا تُنظِرُونِ﴾، وفي هود ﴿فَكِيدُونِي جَمِيعًا ثُمَّ لَا تُنظِرُونِ﴾؟","answer":"الفاء تفيد التعقيب و«ثمّ» التراخي، فطلب منهم في الأعراف عدم المهلة في الإنظار، وهو المناسب لسياق السورة التي ذكرت تعجيل العقوبات، بخلاف هود المبنية على الإمهال. ومن اللافت أنه حيثما اجتمعت «ثمّ» والفاء في الأعراف قُدّمت «ثمّ» على الفاء، كقوله ﴿ثُمَّ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا﴾، وفي هود بالعكس.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص84–86.","url":""}]},{"id":"s8-1","number":1,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"ما مناسبة افتتاح السورة بقوله: ﴿يسألونك عن الأنفال﴾ قبل أن تذكر غزوة بدر وأحداثها؟","answer":"افتتحت بالسؤال عن الأنفال لأنها قضية حاضرة في أذهان السائلين، ومثار جدال ونزاع بعد بدر؛ فدل تقديمها على شدة اهتمامهم بها، ثم جاء الجواب ليرد حكمها إلى الله ورسوله ويهيئهم للتسليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص536–537، تحت «دلالة براعة الاستهلال، باستعراض الجواب على السؤال»","url":""}]},{"id":"s8-2","number":2,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿يسألونك﴾، دون أن يقال: «يستفتونك» عن الأنفال؟","answer":"اختير السؤال لما فيه من استعجال المطلوب والتشوف إلى معرفته، بخلاف الاستفتاء الذي يغلب فيه طلب كشف أمر غامض.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص537، تحت «نكتة استعمال الفعل ﴿يسألونك﴾ دون غيره»","url":""}]},{"id":"s8-3","number":3,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا عُدّي السؤال بـ﴿عن﴾: ﴿يسألونك عن الأنفال﴾، ولم يقل: «يسألونك الأنفال»؟","answer":"عُدّي الفعل بـ﴿عن﴾ لأن سؤالهم كان عن حكم الأنفال ومآلها وقسمتها، لا سؤال طلبٍ للأنفال أنفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص538–539، تحت «سر التعبير بحرف الجر ﴿عن﴾ وفائدة وروده في السياق»","url":""}]},{"id":"s8-4","number":4,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا أُسند السؤال إلى النبي ﷺ بكاف الخطاب: ﴿يسألونك﴾، مع أن الحكم سيأتي من الله؟","answer":"وُجّه السؤال إلى الرسول ﷺ لأنه المبلّغ عن الله والمنفذ لحكمه في الأنفال، ثم جاء الجواب وحيًا من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص538، تحت «علة اتصال الفعل بكاف الخطاب في ﴿يسألونك﴾»","url":""}]},{"id":"s8-5","number":5,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا جاء الجواب بالأمر: ﴿قل﴾، ولم يأت الجواب مباشرة: «الأنفال لله والرسول»؟","answer":"افتتح الجواب بـ﴿قل﴾ لتوثيق الحكم وإظهار أنه وحي من الله، وأن الرسول ﷺ مبلغه بأمانة؛ فلم يكن الجواب رأيًا من عنده، بل حكمًا إلهيًا يفصل فيما سألوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص539، تحت «نكتة استهلال الجواب بفعل الأمر ﴿قل﴾»","url":""}]},{"id":"s8-6","number":6,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿قل﴾ وحذف المخاطبين، فلم يقل: «قل لهم»؟","answer":"لم يقيد القول بقوله «لهم» لأن حكم الأنفال لا يختص بالسائلين يوم بدر؛ بل يجري عليهم وعلى من يأتي بعدهم من المسلمين، فناسب عموم الحكم إطلاق الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص539–540، تحت «إطلاق القول وعدم تقييده بالمخاطبين»","url":""}]},{"id":"s8-7","number":7,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا أعاد لفظ ﴿الأنفال﴾ في الجواب، ولم يقل: «قل هي لله والرسول»؟","answer":"أعيد لفظ ﴿الأنفال﴾ للانتقال من الأنفال المعهودة التي سألوا عنها إلى حكم جنس الأنفال كله؛ فالجواب أعم من السؤال، وليس مقصورًا على غنائم بدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص540، تحت «لطيفة وضع المظهر موضع المضمر»","url":""}]},{"id":"s8-8","number":8,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا كانت ﴿الأنفال﴾ في السؤال للعهد بما غنموه، ثم جاء اللفظ نفسه في الجواب عامًا يشمل جنس الأنفال؟","answer":"الأنفال الأولى هي المعهودة التي سألوا عنها يوم بدر، والثانية في مقام بيان الحكم؛ فجاء اللفظ متناولًا لجنس الأنفال، وحكمُه لله والرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص540، تحت «لطيفة وضع المظهر موضع المضمر»","url":""}]},{"id":"s8-9","number":9,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿الأنفال لله والرسول﴾، ولم يجعل أمرها للغانمين الذين حصلوها؟","answer":"إضافة حكم الأنفال إلى الله والرسول تنزعها من أهواء الغانمين؛ فقسمتها مردها إلى أمر الله وتنفيذ رسوله، لا إلى مجرد إحراز المقاتلين لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص540–541، تحت «بلاغة الجواب»","url":""}]},{"id":"s8-10","number":10,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا اختير اسم الجلالة في ﴿لله﴾، ولم يقل: «للرب»؟","answer":"اختير اسم الجلالة لأنه مقام تشريع وحكم وطاعة، وفيه استحضار الألوهية المستوجبة للامتثال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص541، تحت «فائدة ذكر اللام، وإيثار لفظ الجلالة (الله)»","url":""}]},{"id":"s8-11","number":11,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا قال: ﴿الأنفال لله والرسول﴾، فاختار وصف الرسول دون النبي؟","answer":"اختير ﴿الرسول﴾ لأن المقام مقام تبليغ حكم الله وتنفيذه، وهذه جهة الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص542، تحت «نكتة إيثار لفظ ﴿الرسول﴾، والعدول عن لفظ (النبي)»","url":""}]},{"id":"s8-12","number":12,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا انتقل من خطاب النبي ﷺ في ﴿يسألونك﴾ إلى وصفه بالغائب في ﴿الأنفال لله والرسول﴾؟","answer":"عُدل من ضمير الخطاب إلى وصف ﴿الرسول﴾ لإبراز علة اختصاصه بالحكم: أنه رسول الله المنفذ لأمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص541–542، تحت «نكتة الالتفات من الخطاب إلى الغيبة»","url":""}]},{"id":"s8-13","number":13,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا فرّع على حكم الأنفال قوله: ﴿فاتقوا الله﴾؟","answer":"فُرّع الأمر بالتقوى على رد الأنفال إلى الله والرسول؛ ليحذروا الطمع والنزاع ومخالفة الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص543، تحت «دلالة الفاء في قوله: ﴿فاتقوا الله﴾»","url":""}]},{"id":"s8-14","number":14,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا ربط التقوى باسم الله: ﴿فاتقوا الله﴾، ولم يقل: «فاتقوا ربكم»؟","answer":"ذكر اسم الله يلائم ما سبق من قوله ﴿الأنفال لله﴾، ويستحضر حق الألوهية في الطاعة وترك التنازع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص543، تحت «دلالة ربط التقوى باسم الجلالة دون الربوبية»","url":""}]},{"id":"s8-15","number":15,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا جمع عقب سؤال الغنائم بين ﴿فاتقوا الله﴾ و﴿أصلحوا ذات بينكم﴾؟","answer":"الأمر بإصلاح ذات البين يؤكد مقتضى التقوى؛ فاتقاء مخالفة الله يستلزم ترك النزاع والخصومة في الأنفال والتسليم لقسمتها. وجمعهما يربط صلاح علاقتهم بالله بصلاح ما بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص543–544، تحت «دلالة الجمع بين التقوى والإصلاح»","url":""}]},{"id":"s8-16","number":16,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿أصلحوا ذات بينكم﴾، دون أن يقال ببساطة: «أصلحوا بينكم»؟","answer":"﴿ذات بينكم﴾ هي حقيقة الحال والرابطة القائمة بينكم؛ فالأمر يتناول إصلاح الصلة نفسها وحفظ المودة والوحدة، وهو أبلغ من مجرد تسكين خصومة عارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص544–545، تحت «بلاغة تركيب ﴿ذات بينكم﴾»","url":""}]},{"id":"s8-17","number":17,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"ما مناسبة مجيء الأمر بالطاعة بعد التقوى والإصلاح: ﴿وأطيعوا الله ورسوله﴾؟","answer":"جاء الأمر بالطاعة جامعًا لما تقدمه: قبول حكم الأنفال، والتقوى، وإصلاح ذات البين؛ فكلها امتثال لله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص545، تحت «دلالة الواو في قوله: ﴿وأطيعوا الله ورسوله﴾»","url":""}]},{"id":"s8-18","number":18,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا قال أولًا: ﴿الأنفال لله والرسول﴾، ثم قال: ﴿وأطيعوا الله ورسوله﴾ بإضافة الرسول إلى ضمير الله؟","answer":"جاء ﴿الرسول﴾ في حكم الأنفال لإبراز ما فوضه الله إليه من تصريفها بحكم رسالته. وفي الأمر بالطاعة أضيف الرسول إلى ضمير الله؛ ليبين أنه يبلغ عن الله، وأن طاعته جزء من طاعة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص546، تحت «نكتة تعريف لفظ (الرسول) وإضافته في الجملتين»","url":""}]},{"id":"s8-19","number":19,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا انتقل من ﴿يسألونك﴾ إلى مخاطبة الجماعة بالأوامر: ﴿فاتقوا الله وأصلحوا ذات بينكم وأطيعوا الله ورسوله﴾؟","answer":"لأن هذه الأوامر تختبر إيمان السائلين وتبين مقتضاه العملي؛ فالإيمان يجمع اتقاء المخالفة، وإصلاح العلاقة بالناس، وطاعة الله ورسوله. فانتقل من نقل سؤالهم إلى تكليفهم بما يحقق كمال إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص545، تحت «نكتة توجيه الخطاب إلى الجماعة»","url":""}]},{"id":"s8-20","number":20,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"ما دلالة جواب الشرط ودلالته في قوله: ﴿إن كنتم مؤمنين﴾؟","answer":"التعليق بـ﴿إن كنتم مؤمنين﴾ حث على تحقيق مقتضى الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص548، تحت عنوان «جواب الشرط ودلالته، في قوله: ﴿إن كنتم مؤمنين﴾»","url":""}]},{"id":"s8-266","number":266,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"كيف يفيد التحريض المدلول عليه بحرف (إن)، والعدول عن (إذا)؟","answer":"الإيمان الصادق يحمل على الطاعة وترك التنازع، وليس المقصود نفي أصل إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص546، تحت عنوان «التحريض المدلول عليه بحرف (إن)، والعدول عن (إذا)»","url":""}]},{"id":"s8-21","number":21,"surah":8,"verses":[2],"references":[{"surah":8,"verses":[2]}],"verseLabel":"الأنفال: 2","question":"ما وجه البلاغة في الحصر بـ﴿إنما﴾ في مستهل الآية الكريمة؟","answer":"القصر يبين أن أصحاب هذه الصفات هم المؤمنون الكاملون في هذا المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص553–554، تحت عنوان «بلاغة الحصر بـ﴿إنما﴾ في مستهل الآية الكريمة»","url":""}]},{"id":"s8-267","number":267,"surah":8,"verses":[2],"references":[{"surah":8,"verses":[2]}],"verseLabel":"الأنفال: 2","question":"ما وجه البلاغة في الحصر بـ«إنما» في قوله تعالى: ﴿إِنَّمَا الْمُؤْمِنُونَ الَّذِينَ إِذَا ذُكِرَ اللَّهُ وَجِلَتْ قُلُوبُهُمْ﴾، وما دلالته؟","answer":"الآيات تذكر أصولًا جامعة وآثارًا ظاهرة للإيمان، لا جميع شعبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص553–554، تحت عنوان «بلاغة أسلوب القصر ودلالته»","url":""}]},{"id":"s8-22","number":22,"surah":8,"verses":[2],"references":[{"surah":8,"verses":[2]}],"verseLabel":"الأنفال: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿إذا ذكر الله وجلت قلوبهم﴾، فجعل الوجل في القلوب لا في النفوس؟","answer":"أُسند الوجل إلى القلوب لأنها محل الشعور الباطن، فدل على خوف عميق نابع من أصل النفس لا مجرد أثر ظاهر في الجوارح.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص557–558، تحت «سر إسناد الوجل إلى القلوب ﴿وجلت﴾»","url":""}]},{"id":"s8-23","number":23,"surah":8,"verses":[2],"references":[{"surah":8,"verses":[2]}],"verseLabel":"الأنفال: 2","question":"لماذا اختير ﴿وجلت﴾ لا «خافت»؟","answer":"اختير الوجل لأنه خوف باطني مصحوب باضطراب وتحرك في القلب، فهو أدق من مطلق الخوف في تصوير تأثر المؤمن بذكر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص557، تحت «إيثار الفعل ﴿وجلت﴾، والعدول عن مرادفه»","url":""}]},{"id":"s8-24","number":24,"surah":8,"verses":[2],"references":[{"surah":8,"verses":[2]}],"verseLabel":"الأنفال: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذا تليت عليهم آياته زادتهم إيمانًا﴾، فنسب الزيادة إلى الآيات؟","answer":"أُسندت الزيادة إلى الآيات لأنها سببها المباشر عند التلاوة؛ بما تكشفه من معان ودلائل تجدد التصديق واليقين والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص560، تحت «إسناد الزيادة إلى الآيات وعدم إسنادها إلى المؤمنين»","url":""}]},{"id":"s8-25","number":25,"surah":8,"verses":[2],"references":[{"surah":8,"verses":[2]}],"verseLabel":"الأنفال: 2","question":"ما وجه زيادة الإيمان بسماع الآيات، مع أن المؤمن كان مؤمنًا قبل تلاوتها؟","answer":"الإيمان يقبل الزيادة من جهة قوة التصديق والطمأنينة وكثرة آثاره العملية؛ فكلما تجددت دلالات الآيات ازداد المؤمن يقينًا واستجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص559–560، تحت «سر إيثار استعمال الفعل (زادت) دون غيره»","url":""}]},{"id":"s8-26","number":26,"surah":8,"verses":[2],"references":[{"surah":8,"verses":[2]}],"verseLabel":"الأنفال: 2","question":"لماذا قدّم الجار والمجرور: ﴿وعلى ربهم يتوكلون﴾، ولم يقل: «ويتوكلون على ربهم»؟","answer":"قُدّم ﴿على ربهم﴾ للاختصاص؛ أي يعتمدون على ربهم وحده، لا على الأسباب استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص560–561، تحت «فائدة تقديم الجار والمجرور»","url":""}]},{"id":"s8-27","number":27,"surah":8,"verses":[2],"references":[{"surah":8,"verses":[2]}],"verseLabel":"الأنفال: 2","question":"لماذا اختير اسم الرب في ﴿على ربهم يتوكلون﴾ بعد ذكر اسم الله في الوجل؟","answer":"اختير ﴿ربهم﴾ لاستحضار رعايته وتدبيره وتربيته لهم، وهي معان تبعث على تفويض الأمر إليه والتوكل عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص561، تحت «إيثار استعمال اسم (الرب) دون اسم الجلالة (الله)»","url":""}]},{"id":"s8-28","number":28,"surah":8,"verses":[3],"references":[{"surah":8,"verses":[3]}],"verseLabel":"الأنفال: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿يقيمون الصلاة﴾، دون أن يقال: «يصلون»؟","answer":"إقامة الصلاة أداؤها مستقيمة تامة بأركانها وشروطها وخشوعها ودوامها، فهي أبلغ من مجرد وقوع الصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص569، تحت عنوان «دلالة الفعل ﴿يقيمون﴾، دون الفعل (يصلون)»","url":""}]},{"id":"s8-29","number":29,"surah":8,"verses":[3],"references":[{"surah":8,"verses":[3]}],"verseLabel":"الأنفال: 3","question":"لماذا قدّم ﴿مما رزقناهم﴾ على ﴿ينفقون﴾؟","answer":"قُدّم ﴿مما رزقناهم﴾ لإبراز أن المنفَق بعض عطاء الله لهم، وفيه تذكير بالمنعم قبل ذكر فعل الإنفاق.","sources":[{"label":"في تفسير النظير اللفظي ﴿ومما رزقناهم ينفقون﴾ [البقرة:3]: موسوعة التفسير البلاغي، ج1، ص122–123، تحت «فائدة تقديم الجار والمجرور»","url":""}]},{"id":"s8-30","number":30,"surah":8,"verses":[3],"references":[{"surah":8,"verses":[3]}],"verseLabel":"الأنفال: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿مما رزقناهم﴾ بـ«من» التبعيضية، ولم يأمرهم بإنفاق كل الرزق؟","answer":"دلّت ﴿من﴾ على التبعيض؛ رحمة بالمكلف وإبقاء لما تقوم به مصالحه، فالإنفاق المشروع ليس استغراق المال كله.","sources":[{"label":"في تفسير النظير اللفظي ﴿ومما رزقناهم ينفقون﴾ [البقرة:3]: موسوعة التفسير البلاغي، ج1، ص122–123، تحت «فائدة تقديم الجار والمجرور»","url":""}]},{"id":"s8-31","number":31,"surah":8,"verses":[3],"references":[{"surah":8,"verses":[3]}],"verseLabel":"الأنفال: 3","question":"لماذا وصف المال المنفق بأنه رزق: ﴿ومما رزقناهم ينفقون﴾، ولم يقل: ومما كسبوا؟","answer":"الرزق يبرز جهة العطاء من الله، أما الكسب فيبرز سعي الإنسان وجهده، وقد يأتي الرزق من غير كسب. فالتعبير يذكرهم بأن ما ينفقونه من عطاء الله لهم، وإن حصل بعضه بسعيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص569–570، تحت «الرزق والكسب»","url":""}]},{"id":"s8-32","number":32,"surah":8,"verses":[4],"references":[{"surah":8,"verses":[4]}],"verseLabel":"الأنفال: 4","question":"لماذا أعاد الإشارة إليهم بقوله: ﴿أولئك هم المؤمنون حقًا﴾ بعد قوله: ﴿إنما المؤمنون﴾؟","answer":"الإشارة بـ﴿أولئك﴾ تجمع أصحاب الصفات السابقة وتميزهم، ثم تقرر لهم حقيقة الإيمان وكماله جزاءً على اجتماعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص573–574، تحت «دلالة اسم الإشارة ﴿أولئك﴾ وموقعها الإعرابي»","url":""}]},{"id":"s8-33","number":33,"surah":8,"verses":[4],"references":[{"surah":8,"verses":[4]}],"verseLabel":"الأنفال: 4","question":"لماذا توسط ضمير الفصل ﴿هم﴾ في ﴿أولئك هم المؤمنون﴾؟","answer":"ضمير الفصل ﴿هم﴾ يقوي الحكم ويفيد قصر كمال الإيمان عليهم في هذا المقام، وينفيه عمن تخلفت عنه تلك الصفات.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص574–575، تحت «أثر الضمير المنفصل، وفائدته في السياق»","url":""}]},{"id":"s8-34","number":34,"surah":8,"verses":[4],"references":[{"surah":8,"verses":[4]}],"verseLabel":"الأنفال: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿حقًا﴾ بعد هذا التوكيد كله؟","answer":"﴿حقًا﴾ تؤكد أن إيمانهم ثابت متحقق، لا دعوى باللسان ولا وصفًا مجازيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص576، تحت «فائدة قوله: ﴿حقًا﴾ وتوجيه الوقف عليها»","url":""}]},{"id":"s8-35","number":35,"surah":8,"verses":[4],"references":[{"surah":8,"verses":[4]}],"verseLabel":"الأنفال: 4","question":"لماذا جاءت ﴿درجات﴾ جمعًا، بينما الإيمان الموصوف واحد؟","answer":"تتفاوت مراتب الجزاء بحسب تفاوت أحوال القلوب ودرجات الإيمان والتوكل؛ فناسب ذلك جمع الدرجات. وتنكيرها يزيد تعظيمها في ذاتها وفي تفاوت ما بينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص577–578، تحت عنوان «علة تنكير لفظ ﴿درجات﴾»","url":""}]},{"id":"s8-36","number":36,"surah":8,"verses":[4],"references":[{"surah":8,"verses":[4]}],"verseLabel":"الأنفال: 4","question":"ما وجه البلاغة في ختم الآية بقوله: ﴿ورزق كريم﴾؟","answer":"من وجوه الترتيب أن الدرجات تقابل أعمال القلوب، والمغفرة تقابل الصلاة، والرزق الكريم يقابل الإنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص580، تحت عنوان «بلاغة ختم الآية بقوله: ﴿ورزق كريم﴾»","url":""}]},{"id":"s8-268","number":268,"surah":8,"verses":[4],"references":[{"surah":8,"verses":[4]}],"verseLabel":"الأنفال: 4","question":"ما نكتة عطف المغفرة على الدرجات؟","answer":"ي ختمه بالرزق الكريم أيضًا دفع لتوهم أن تفاوت الدرجات يعني نقص نعيم من كان دون غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص577، تحت عنوان «نكتة عطف المغفرة على الدرجات»","url":""}]},{"id":"s8-37","number":37,"surah":8,"verses":[4],"references":[{"surah":8,"verses":[4]}],"verseLabel":"الأنفال: 4","question":"لماذا وصف الرزق نفسه بأنه ﴿كريم﴾؟","answer":"الكرم يدل هنا على كمال الرزق ونفاسته وخلوه من النقص والتكدير؛ فهو حاصل على وجه الإكرام والتعظيم. ويحتمل الوصف أيضًا إظهار كرم رازقه سبحانه، بإسناد الوصف إلى الرزق الذي تجلى فيه هذا الإنعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص579، تحت «بلاغة المجاز العقلي بإسناد الفعل والوصف إلى غير صاحبه»","url":""}]},{"id":"s8-38","number":38,"surah":8,"verses":[5],"references":[{"surah":8,"verses":[5]}],"verseLabel":"الأنفال: 5","question":"ما دلالة بيان التشبيه التمثيلي، في قوله: ﴿كما أخرجك ربك﴾؟","answer":"التشبيه يربط كراهة بعضهم حكم الأنفال بكراهتهم الخروج للقتال أول الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص583–584، تحت عنوان «بيان التشبيه التمثيلي، في قوله: ﴿كما أخرجك ربك﴾»","url":""}]},{"id":"s8-269","number":269,"surah":8,"verses":[5],"references":[{"surah":8,"verses":[5]}],"verseLabel":"الأنفال: 5","question":"ما دلالة اتصال التشبيه بما قبله، في قوله: ﴿كما أخرجك﴾؟","answer":"في الحالين كان أمر الله حقًا وكانت العاقبة خيرًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص583–584، تحت عنوان «دلالة اتصال التشبيه بما قبله، في قوله: ﴿كما أخرجك﴾»","url":""}]},{"id":"s8-39","number":39,"surah":8,"verses":[5],"references":[{"surah":8,"verses":[5]}],"verseLabel":"الأنفال: 5","question":"لماذا أسند الخروج إلى الرب: ﴿أخرجك ربك﴾؟","answer":"إسناد الإخراج إلى ﴿ربك﴾ يشعر بالتدبير والرعاية؛ فالخروج لم يكن مصادفة، بل بتوجيه الرب الذي تولى نصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص584–585، تحت «دلالة التعبير بصيغة ﴿أخرجك﴾»","url":""}]},{"id":"s8-40","number":40,"surah":8,"verses":[5],"references":[{"surah":8,"verses":[5]}],"verseLabel":"الأنفال: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿من بيتك﴾، دون أن يقال: «من المدينة»؟","answer":"يحتمل ﴿بيتك﴾ مسكنه حقيقة، ويحتمل المدينة لأنها دار هجرته وسكناه. والتعبير بالبيت يصور مفارقة موطن الأنس والسكن إلى موطن القتال؛ وفيه تذكير بما تحقق بعد ذلك الخروج من النصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص586، تحت «دلالة قوله: ﴿بيتك﴾، وفائدة إضافته إلى ضمير المخاطب»","url":""}]},{"id":"s8-41","number":41,"surah":8,"verses":[5],"references":[{"surah":8,"verses":[5]}],"verseLabel":"الأنفال: 5","question":"لماذا قُيّد الإخراج بـ﴿بالحق﴾؟","answer":"قُيّد الخروج بـ﴿بالحق﴾ لبيان أنه جرى بأمر الله ولغاية عادلة، وإن كره فريق ما آل إليه أول الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص586، تحت «معنى الباء في قوله: ﴿بالحق﴾، وأثره في المعنى»","url":""}]},{"id":"s8-42","number":42,"surah":8,"verses":[5],"references":[{"surah":8,"verses":[5]}],"verseLabel":"الأنفال: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿فريقًا من المؤمنين﴾، ولم يعمم الكراهة على المؤمنين؟","answer":"قيل ﴿فريقًا﴾ إنصافًا؛ فالكراهة لم تعم المؤمنين، وإنما صدرت من طائفة منهم بسبب ضعف الاستعداد للقتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص587–588، تحت عنوان «فائدة التعبير بقوله: ﴿فريقًا﴾»","url":""}]},{"id":"s8-43","number":43,"surah":8,"verses":[6],"references":[{"surah":8,"verses":[6]}],"verseLabel":"الأنفال: 6","question":"لماذا عبّر بالمضارع: ﴿يجادلونك﴾، مع أن الجدال وقع وانتهى؟","answer":"المضارع يحكي الحال الماضية ويستحضرها، فكأن السامع يشاهد جدالهم وقت وقوعه؛ وفي ذلك زيادة تعجيب من الموقف، بخلاف مجرد الإخبار بالفعل الماضي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص595، تحت «نكتة استعمال صيغة المضارع ﴿يجادلونك﴾»","url":""}]},{"id":"s8-44","number":44,"surah":8,"verses":[6],"references":[{"surah":8,"verses":[6]}],"verseLabel":"الأنفال: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿يجادلونك في الحق﴾، وكيف يجادل المؤمن في حق تبين له؟","answer":"الحق هو الخروج للقاء ذي الشوكة بعد أن ظهر لهم وجهه، وكان جدالهم ناشئًا من كراهة القتال وقلة الاستعداد، لا من إنكار الحق بعد معرفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص595–596، تحت عنوان «فائدة قوله: ﴿في الحق﴾»","url":""}]},{"id":"s8-45","number":45,"surah":8,"verses":[6],"references":[{"surah":8,"verses":[6]}],"verseLabel":"الأنفال: 6","question":"لماذا شبّههم بمن ﴿يساقون إلى الموت﴾، ولم يقل: كأنهم ذاهبون إليه؟","answer":"اختير ﴿يساقون﴾ لتصوير شدة كراهتهم واضطرارهم إلى ما يخافون، كمن يدفع إلى الموت دفعًا لا يملك معه رجوعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص599، تحت «نكتة التعبير بـ﴿يساقون﴾ دون مرادفاته»","url":""}]},{"id":"s8-46","number":46,"surah":8,"verses":[6],"references":[{"surah":8,"verses":[6]}],"verseLabel":"الأنفال: 6","question":"لماذا بُني ﴿يساقون﴾ للمجهول؟","answer":"بني الفعل للمفعول لأن السائق معلوم لا يحتاج إلى تعيين؛ فالاهتمام بحال من يساق إلى الموت وما يستولي عليه من خوف، حتى تشغله هول وجهته عن الالتفات إلى من يسوقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص599، تحت «دلالة التعبير بصيغة المضارع المبني للمفعول»","url":""}]},{"id":"s8-47","number":47,"surah":8,"verses":[6],"references":[{"surah":8,"verses":[6]}],"verseLabel":"الأنفال: 6","question":"لماذا ختم التشبيه بقوله: ﴿وهم ينظرون﴾، وحذف ما ينظرون إليه؟","answer":"﴿وهم ينظرون﴾ يزيد الصورة رهبة؛ فهم يعاينون أسباب الموت أمامهم، وحُذف المفعول لتذهب النفس في تصور ما يرونه من الهول كل مذهب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص600–601، تحت عنوان «حذف متعلق الفعل ﴿ينظرون﴾»","url":""}]},{"id":"s8-48","number":48,"surah":8,"verses":[7],"references":[{"surah":8,"verses":[7]}],"verseLabel":"الأنفال: 7","question":"ما الذي يحدده التعبير بـ﴿إحدى الطائفتين﴾ في وعد الله لهم؟","answer":"يحدد أن الوعد كان بالظفر بواحدة من الطائفتين: العير أو النفير، لا بهما جميعًا. ولذلك لم يكن تعلق رغبتهم بالعير تحديدًا ملزمًا لما وعدهم الله به.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص606، تحت «معنى ﴿إحدى الطائفتين﴾، وعلة تخصيصها بالإضافة»","url":""}]},{"id":"s8-49","number":49,"surah":8,"verses":[7],"references":[{"surah":8,"verses":[7]}],"verseLabel":"الأنفال: 7","question":"لماذا عبّر عن العير بـ﴿غير ذات الشوكة﴾؟","answer":"عُبر عن العير بـ﴿غير ذات الشوكة﴾؛ لأن الشوكة كناية عن القوة والسلاح، فدل التعبير على سهولة أخذها وقلة منعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص608–609، تحت عنوان «سر التعبير بقوله: ﴿غير ذات الشوكة﴾»","url":""}]},{"id":"s8-50","number":50,"surah":8,"verses":[7],"references":[{"surah":8,"verses":[7]}],"verseLabel":"الأنفال: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿تكون لكم﴾، دون أن يقال: «تأخذونها»؟","answer":"﴿تكون لكم﴾ أوسع من «تأخذونها»؛ إذ تفيد صيرورتها خالصة لهم وتمكنهم منها، لا مجرد فعل الأخذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص609، تحت عنوان «فائدة الفعل ﴿تكون﴾ في: ﴿تكون لكم﴾»","url":""}]},{"id":"s8-51","number":51,"surah":8,"verses":[7],"references":[{"surah":8,"verses":[7]}],"verseLabel":"الأنفال: 7","question":"لماذا قابل إرادة المؤمنين السهولة بقوله: ﴿ويريد الله أن يحق الحق﴾؟","answer":"قوبلت إرادتهم العاجلة للعير السهلة بإرادة الله إظهار الحق؛ لبيان أن اختياره لهم أعظم عاقبة من اختيارهم لأنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص609، تحت «سر العدول عن (ود) إلى (يريد)»","url":""}]},{"id":"s8-52","number":52,"surah":8,"verses":[7],"references":[{"surah":8,"verses":[7]}],"verseLabel":"الأنفال: 7","question":"ما وجه البلاغة في جناس الاشتقاق في: ﴿يحق الحق﴾؟","answer":"إحقاق الحق إظهاره وإثباته وتغليبه في الواقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص610–611، تحت عنوان «بلاغة جناس الاشتقاق في: ﴿يحق الحق﴾»","url":""}]},{"id":"s8-270","number":270,"surah":8,"verses":[7],"references":[{"surah":8,"verses":[7]}],"verseLabel":"الأنفال: 7","question":"ما دلالة الدلالة الصوتية في كلمتي: ﴿يحق الحق﴾؟","answer":"الحق ثابت في ذاته، لكنه يحتاج إلى إظهار سلطانه وإبطال ما ينازعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص610–611، تحت عنوان «الدلالة الصوتية في كلمتي: ﴿يحق الحق﴾»","url":""}]},{"id":"s8-53","number":53,"surah":8,"verses":[7],"references":[{"surah":8,"verses":[7]}],"verseLabel":"الأنفال: 7","question":"ما الصورة في قوله: ﴿ويقطع دابر الكافرين﴾؟","answer":"قطع الدابر كناية عن الاستئصال؛ إذ يبدأ المستأصل بأول الشيء ويتتبعه حتى يبلغ آخره، فلا يبقي منه شيئًا. فصور التعبير إزالة قوتهم ومكرهم ببلوغ القطع إلى آخرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص612–613، تحت «بلاغة المجاز في: ﴿ويقطع دابر الكافرين﴾»","url":""}]},{"id":"s8-54","number":54,"surah":8,"verses":[8],"references":[{"surah":8,"verses":[8]}],"verseLabel":"الأنفال: 8","question":"لماذا تكرر ﴿ليحق الحق﴾ بعد ذكره في الآية السابقة؟","answer":"الأول متعلق بإرادة الله اختيار المواجهة ذات الشوكة، والثاني تعليل لما جرى من النصر؛ فتكراره يثبت أن الغاية إظهار الحق لا مجرد إحراز الغنيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص614–615، تحت «نكتة إيراد قوله: ﴿ليحق الحق﴾ بعد: ﴿أن يحق الحق﴾»","url":""}]},{"id":"s8-55","number":55,"surah":8,"verses":[8],"references":[{"surah":8,"verses":[8]}],"verseLabel":"الأنفال: 8","question":"لماذا قابل ﴿يحق الحق﴾ بـ﴿يبطل الباطل﴾، ولم يقل: يهزم الكافرين؟","answer":"المقابلة بين إحقاق الحق وإبطال الباطل تصرح برفض الله للباطل، وتؤكد إثبات الحق بنفي ضده؛ فليس المقصود مجرد هزيمة قوم، بل إظهار الحق وإزالة ما يناقضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص616، تحت «دلالة عطف: ﴿ويبطل الباطل﴾ على ما قبلها»","url":""}]},{"id":"s8-56","number":56,"surah":8,"verses":[8],"references":[{"surah":8,"verses":[8]}],"verseLabel":"الأنفال: 8","question":"لماذا وصف المعاندين هنا بـ﴿المجرمون﴾ لا «الكافرون»؟","answer":"وصفهم بالمجرمين يبرز أن عنادهم فعل مكتسب وجناية تستحق الإبطال والعقوبة، لا مجرد وصف اعتقادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص617، تحت «إيثار استعمال كلمة ﴿المجرمون﴾ دون غيرها»","url":""}]},{"id":"s8-57","number":57,"surah":8,"verses":[9],"references":[{"surah":8,"verses":[9]}],"verseLabel":"الأنفال: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿إذ تستغيثون ربكم﴾، دون أن يقال: «إذ تدعون الله»؟","answer":"الاستغاثة طلب الغوث عند الشدة، فهي تصور اضطرار المؤمنين وخطر الموقف، وذكر ﴿ربكم﴾ يستحضر رعايته ونصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص623–624، تحت عنوان «نكتة التعبير باسم الربوبية في ﴿إذ تستغيثون ربكم﴾»","url":""}]},{"id":"s8-58","number":58,"surah":8,"verses":[9],"references":[{"surah":8,"verses":[9]}],"verseLabel":"الأنفال: 9","question":"لماذا جاء جواب الاستغاثة سريعًا بالفاء: ﴿فاستجاب لكم﴾؟","answer":"الفاء تفيد سرعة ترتب الاستجابة على الاستغاثة، فتوحي بقرب الإغاثة وعناية الله بالمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص624–625، تحت «دلالة (الفاء) في ﴿فاستجاب لكم﴾»","url":""}]},{"id":"s8-59","number":59,"surah":8,"verses":[9],"references":[{"surah":8,"verses":[9]}],"verseLabel":"الأنفال: 9","question":"لماذا عبّر بـ﴿ممدكم﴾، لا «مرسل إليكم»؟","answer":"الإمداد إلحاق مدد يقوي الموجود ويتتابع عليه، فهو أنسب بحال جيش يحتاج إلى ما يعززه من مجرد الإرسال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص619–620، تحت «شرح المفردات: ﴿ممدكم﴾»","url":""}]},{"id":"s8-60","number":60,"surah":8,"verses":[9],"references":[{"surah":8,"verses":[9]}],"verseLabel":"الأنفال: 9","question":"ما الذي تضيفه البشارة بعدد معين: ﴿بألف من الملائكة﴾ إلى طمأنينة المؤمنين؟","answer":"تذكرهم هذه البشارة المحددة بقدرة الله على حماية رسوله والمؤمنين، وبعنايته بهم في ذلك الموقف. وتنكير ﴿ألف﴾ للتعظيم يزيد وقع المدد في نفوسهم، فيقوى رجاؤهم ويطمئنون إلى وعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص626–627، تحت «معاني الحروف وأثر القراءات في قوله: ﴿بألف من الملائكة﴾»","url":""}]},{"id":"s8-61","number":61,"surah":8,"verses":[9],"references":[{"surah":8,"verses":[9]}],"verseLabel":"الأنفال: 9","question":"لماذا وصف الملائكة بـ﴿مردفين﴾؟","answer":"﴿مردفين﴾ تدل على مجيء الملائكة متتابعين يردف بعضهم بعضًا، أو مردَفين بغيرهم، وفي الحالين تصوير لتوالي المدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص627–628، تحت «توجيه القراءات في لفظ: ﴿مردفين﴾»","url":""}]},{"id":"s8-62","number":62,"surah":8,"verses":[9],"references":[{"surah":8,"verses":[9]}],"verseLabel":"الأنفال: 9","question":"لماذا جاء المدد في الأنفال بـ﴿ألف من الملائكة مردفين﴾، وفي آل عمران بثلاثة آلاف ثم خمسة آلاف؟","answer":"تدرجت البشارة بحسب ما بلغ المسلمين من كثرة عدوهم ومدده: بدأ الوعد بألف، ثم بثلاثة آلاف، ثم بخمسة آلاف مع ازدياد التخوف. فاختلاف الأعداد حكاية لبشارات متدرجة تزيد الطمأنينة، ولا تعارض بين الأخبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص698، تحت «الحكمة من تدرج ذكر المدد بين سورتي الأنفال وآل عمران»","url":""}]},{"id":"s8-63","number":63,"surah":8,"verses":[9],"references":[{"surah":8,"verses":[9]}],"verseLabel":"الأنفال: 9","question":"ما دلالة القراءات في لفظ ﴿مردفين﴾؟","answer":"تدل القراءات على تتابع الملائكة بعضهم إثر بعض، أو على إردافهم بغيرهم من المدد؛ وفي الحالين تبرز صورة توالي النصر الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص627–628، تحت «توجيه القراءات في لفظ: ﴿مردفين﴾»","url":""}]},{"id":"s8-271","number":271,"surah":8,"verses":[9],"references":[{"surah":8,"verses":[9]}],"verseLabel":"الأنفال: 9","question":"ما سر الكناية عن الشدة بالتسويم؟","answer":"التسويم إظهار العلامة والتهيؤ للحرب، فكني به عن شدة الملائكة وقوتهم وهيئتهم المهيبة في القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص698–699، تحت «سر الكناية عن الشدة بالتسويم»","url":""}]},{"id":"s8-64","number":64,"surah":8,"verses":[10],"references":[{"surah":8,"verses":[10]}],"verseLabel":"الأنفال: 10","question":"ما دلالة تعيين مرجع الضمير في قوله: ﴿وما جعله﴾؟","answer":"لذلك عقب بقوله: ﴿وما النصر إلا من عند الله﴾، فالأسباب لا تستقل بالنصر عن مسببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص633، تحت عنوان «تعيين مرجع الضمير في قوله: ﴿وما جعله﴾»","url":""}]},{"id":"s8-272","number":272,"surah":8,"verses":[10],"references":[{"surah":8,"verses":[10]}],"verseLabel":"الأنفال: 10","question":"ما وجه البلاغة في القصر بالاستثناء بعد النفي؟","answer":"المراد أن خبر الإمداد، أو الإمداد نفسه، جعل بشارة وتثبيتًا لقلوبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص634، تحت عنوان «بلاغة القصر بالاستثناء بعد النفي»","url":""}]},{"id":"s8-273","number":273,"surah":8,"verses":[10],"references":[{"surah":8,"verses":[10]}],"verseLabel":"الأنفال: 10","question":"أين يظهر الاحتراس في قوله تعالى: ﴿وَمَا النَّصْرُ إِلَّا مِنْ عِنْدِ اللَّهِ﴾، وما أثره؟","answer":"لا ينسبوا النصر إلى العدد والعدة استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص639، تحت عنوان «بلاغة الاحتراس»","url":""}]},{"id":"s8-65","number":65,"surah":8,"verses":[10],"references":[{"surah":8,"verses":[10]}],"verseLabel":"الأنفال: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿ولتطمئن به قلوبكم﴾، مع أن البشرى موجهة إليهم جميعًا؟","answer":"أُسند الاطمئنان إلى القلوب لأنها محل الخوف والسكينة، فدل على أمن داخلي يعم الجماعة من أصل شعورها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص631، تحت عنوان «شرح المفردات: ﴿ولتطمئن﴾»","url":""}]},{"id":"s8-67","number":67,"surah":8,"verses":[10],"references":[{"surah":8,"verses":[10]}],"verseLabel":"الأنفال: 10","question":"لماذا اعترض بقوله: ﴿وما النصر إلا من عند الله﴾ وسط الحديث عن الملائكة؟","answer":"اعترض بنفي النصر إلا من عند الله لئلا يتعلق القلب بالملائكة أو العدد، فهما بشرى وسبب، أما موجد النصر فهو الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص638–639، تحت عنوان «بلاغة القصر في الآية»","url":""}]},{"id":"s8-68","number":68,"surah":8,"verses":[10],"references":[{"surah":8,"verses":[10]}],"verseLabel":"الأنفال: 10","question":"لماذا أعيد اسم الله في ﴿وما النصر إلا من عند الله﴾ بعد قوله: ﴿وما جعله الله إلا بشرى﴾؟","answer":"إظهار اسم الله بدل الضمير يعظم شأن النصر ومن يصدر عنه، ويقوي اليقين بأن النصر من عنده وحده؛ فهو سبحانه صاحب صفات الجلال والكمال، فلا يتعلق القلب بالأسباب استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص638–639، تحت «نكتة الإظهار في محل الإضمار»","url":""}]},{"id":"s8-69","number":69,"surah":8,"verses":[10],"references":[{"surah":8,"verses":[10]}],"verseLabel":"الأنفال: 10","question":"ما مناسبة الختم بـ﴿إن الله عزيز حكيم﴾؟","answer":"﴿عزيز﴾ لا يغلبه غالب وهو القادر على النصر، و﴿حكيم﴾ يضع النصر وأسبابه في مواضعها؛ فالختام جامع للقدرة والتدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص641، تحت «نكتة ختم الآية باسمي الله: (العزيز الحكيم)»","url":""}]},{"id":"s8-70","number":70,"surah":8,"verses":[10],"references":[{"surah":8,"verses":[10]}],"verseLabel":"الأنفال: 10","question":"ما سرّ التعبير في قوله تعالى في آل عمران: ﴿بشرى لكم﴾، وحذف ﴿لكم﴾ في الأنفال فقال: ﴿إلا بشرى﴾؟","answer":"من وجوه الفرق أن ﴿لكم﴾ سبقت في الأنفال في ﴿فاستجاب لكم﴾، فحذف تكرارها لفظًا ومعنى. أما في آل عمران فذكرها يزيد تعيين أصحاب البشرى في مقام يواجهون فيه كثرة عدوهم؛ ويذكر المصدر أيضًا فرق الإيجاز والإطناب بين السياقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص637، تحت «نكتة ترك تقييد البشرى بالجار والمجرور (لكم)»","url":""}]},{"id":"s8-72","number":72,"surah":8,"verses":[10],"references":[{"surah":8,"verses":[10]}],"verseLabel":"الأنفال: 10","question":"لماذا ختم آية الأنفال بـ﴿إن الله عزيز حكيم﴾، وختم نظيرتها في آل عمران بـ﴿العزيز الحكيم﴾؟","answer":"جاء ختام الأنفال جملة مستقلة مؤكدة بـ﴿إن﴾؛ لأن سياقها تقدمته وعود متعددة بالنصر وإحقاق الحق وقطع دابر الكافرين، فناسبه تأكيد أبلغ. وفي آل عمران جاء ﴿العزيز الحكيم﴾ وصفين تابعين لاسم الله، إذ لم تتقدم تلك الوعود المتعددة في السياق نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص640، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s8-73","number":73,"surah":8,"verses":[11],"references":[{"surah":8,"verses":[11]}],"verseLabel":"الأنفال: 11","question":"ما دلالة الاستعارة في الآية؟","answer":"صور إلقاء النعاس عليهم بصورة غشاء يحيط بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص646، تحت عنوان «بلاغة الاستعارة في الآية»","url":""}]},{"id":"s8-274","number":274,"surah":8,"verses":[11],"references":[{"surah":8,"verses":[11]}],"verseLabel":"الأنفال: 11","question":"ما دلالة توجيه القراءات في الآية؟","answer":"شبه النعاس بالغطاء، أو شبه إلقاءه بوضع الغشاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص648، تحت عنوان «توجيه القراءات في الآية»","url":""}]},{"id":"s8-74","number":74,"surah":8,"verses":[11],"references":[{"surah":8,"verses":[11]}],"verseLabel":"الأنفال: 11","question":"لماذا وصف النعاس بأنه ﴿أمنة منه﴾؟","answer":"النعاس ﴿أمنة منه﴾ لأنه علامة زوال الخوف في موطن الحرب، ومنحة من الله سكّن بها نفوسهم وقواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص643، تحت عنوان «شرح المفردات: ﴿أمنة﴾»","url":""}]},{"id":"s8-75","number":75,"surah":8,"verses":[11],"references":[{"surah":8,"verses":[11]}],"verseLabel":"الأنفال: 11","question":"لماذا قدم ﴿عليكم﴾ في قوله: ﴿وينزل عليكم من السماء ماء﴾؟","answer":"قدم للاهتمام بمن نزل عليهم الماء، وللتشويق إلى النعمة المنزلة عليهم. وتقديمه على ﴿من السماء﴾ يبين أن الامتنان بوصول الماء إليهم في حاجتهم أهم هنا من مجرد بيان جهة نزوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص649–650، تحت «نكتة تقديم الجار والمجرور»","url":""}]},{"id":"s8-76","number":76,"surah":8,"verses":[11],"references":[{"surah":8,"verses":[11]}],"verseLabel":"الأنفال: 11","question":"لماذا جمع للماء أربع وظائف: التطهير، وإذهاب الرجز، وربط القلوب، وتثبيت الأقدام؟","answer":"جمع الماء مصالح الظاهر والباطن: طهارة الأبدان، وإزالة وسوسة الشيطان، وتقوية القلوب، وتماسك الرمل تحت الأقدام.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص655، تحت عنوان «بلاغة الكناية في قوله: ﴿ويثبت به الأقدام﴾»","url":""}]},{"id":"s8-77","number":77,"surah":8,"verses":[11],"references":[{"surah":8,"verses":[11]}],"verseLabel":"الأنفال: 11","question":"لماذا عبّر عن وسوسة الشيطان بـ﴿رجز الشيطان﴾؟","answer":"أضيف الرجز إلى الشيطان لأنه وسوسته وتخويفه وتكديره الذي أراد به إضعافهم، فطهرهم الله منه بالماء واليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص651–652، تحت «بلاغة المجاز المرسل»","url":""}]},{"id":"s8-78","number":78,"surah":8,"verses":[11],"references":[{"surah":8,"verses":[11]}],"verseLabel":"الأنفال: 11","question":"ما الصورة في ﴿وليربط على قلوبكم﴾؟","answer":"في ﴿يربط على قلوبكم﴾ استعارة لتثبيت القلوب ومنعها من الاضطراب، كأن عليها رباطًا يشدها فلا تتفلت من الخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص653–654، تحت عنوان «دلالة حرف الجر (على) في قوله: ﴿على قلوبكم﴾»","url":""}]},{"id":"s8-79","number":79,"surah":8,"verses":[11],"references":[{"surah":8,"verses":[11]}],"verseLabel":"الأنفال: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿ويثبت به الأقدام﴾، فجعل الماء مثبتًا للأقدام؟","answer":"كان المطر يلبد الرمل فيثبت عليه المشي، فجعل الماء سببًا حسيًا لثبات الأقدام، مع ما أورثه من ثبات معنوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص654–655، تحت عنوان «بلاغة الكناية في قوله: ﴿ويثبت به الأقدام﴾»","url":""}]},{"id":"s8-80","number":80,"surah":8,"verses":[12],"references":[{"surah":8,"verses":[12]}],"verseLabel":"الأنفال: 12","question":"ما سرّ التعبير في قوله تعالى للملائكة: ﴿أني معكم﴾ قبل أمرهم بتثبيت المؤمنين؟","answer":"بدأ بإعلام الملائكة بمعيته؛ تثبيتًا لهم وبيانًا أن ما يفعلونه مؤيد بعون الله وتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص662–663، تحت عنوان «دلالة المعية في قوله: ﴿أني معكم﴾»","url":""}]},{"id":"s8-81","number":81,"surah":8,"verses":[12],"references":[{"surah":8,"verses":[12]}],"verseLabel":"الأنفال: 12","question":"لماذا عبّر عن تقوية المؤمنين بقوله للملائكة: ﴿فثبتوا الذين آمنوا﴾؟","answer":"التثبيت يصور إزالة اضطرابهم وخوفهم، وتقوية عزائمهم، كأن قلوبهم ربطت فلا يخالطها رعب. فجاء التعبير مركزًا على الأثر المطلوب في نفوس المؤمنين عند لقاء عدوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص663، تحت «براعة المجاز في قوله: ﴿فثبتوا الذين آمنوا﴾»","url":""}]},{"id":"s8-82","number":82,"surah":8,"verses":[12],"references":[{"surah":8,"verses":[12]}],"verseLabel":"الأنفال: 12","question":"لماذا قال: ﴿سألقي في قلوب الذين كفروا الرعب﴾ بضمير المفرد، ولم يقل: سنلقي؟","answer":"أفرد الضمير مع أن المقام مقام تعظيم لئلا يتوهم أن الملائكة المخاطبين هم سبب إلقاء الرعب استقلالًا. فإسناده إلى الله وحده يطمئن المؤمنين إلى أن تخذيل عدوهم من عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص664–665، تحت «نكتة التعبير بـ﴿سألقي﴾ دون (سنلقي)»","url":""}]},{"id":"s8-83","number":83,"surah":8,"verses":[12],"references":[{"surah":8,"verses":[12]}],"verseLabel":"الأنفال: 12","question":"لماذا اختير ﴿الرعب﴾ في قوله: ﴿سألقي في قلوب الذين كفروا الرعب﴾، دون مطلق الخوف؟","answer":"الرعب خوف شديد يستولي على النفس، فهو أخص من مطلق الخوف. واختياره يصور ما يلقيه الله في قلوب عدوهم من فزع بالغ يخذلهم ويضعف قدرتهم على المواجهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص668، تحت «الرعب والخوف»","url":""}]},{"id":"s8-84","number":84,"surah":8,"verses":[12],"references":[{"surah":8,"verses":[12]}],"verseLabel":"الأنفال: 12","question":"ما نكتة التنصيص على ما ﴿فوق الأعناق﴾ و﴿بنان﴾؟","answer":"وق الأعناق موضع الإجهاز وقطع الرؤوس، والبنان أطراف الأعضاء التي بها حمل السلاح والدفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص666–667، تحت عنوان «نكتة التنصيص على ما ﴿فوق الأعناق﴾ و﴿بنان﴾»","url":""}]},{"id":"s8-275","number":275,"surah":8,"verses":[12],"references":[{"surah":8,"verses":[12]}],"verseLabel":"الأنفال: 12","question":"ما دلالة الفوقية بين الإيجاز والكناية؟","answer":"ضربهما يعطل الحياة أو القدرة على القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص666–667، تحت عنوان «دلالة الفوقية بين الإيجاز والكناية»","url":""}]},{"id":"s8-85","number":85,"surah":8,"verses":[13],"references":[{"surah":8,"verses":[13]}],"verseLabel":"الأنفال: 13","question":"لماذا عُبر عن عداوتهم بـ﴿شاقوا الله ورسوله﴾؟","answer":"المشاقة اتخاذ شق مقابل لشق آخر؛ فصورت مخالفتهم لله ورسوله كوقوفهم في جانب معادٍ منفصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص673، تحت «بلاغة الاستعارة في الآية»","url":""}]},{"id":"s8-86","number":86,"surah":8,"verses":[13],"references":[{"surah":8,"verses":[13]}],"verseLabel":"الأنفال: 13","question":"لماذا أعاد الشرط نفسه: ﴿ومن يشاقق الله ورسوله﴾ بعد تقرير فعلهم؟","answer":"أُعيد الشرط لتعميم الحكم بعد وصف الواقعة؛ فما نزل بهم ليس خاصًا بهم، بل سنة في كل من يشاقق الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص675–676، تحت «دلالة (من) في قوله: ﴿ومن يشاقق﴾»","url":""}]},{"id":"s8-87","number":87,"surah":8,"verses":[13],"references":[{"surah":8,"verses":[13]}],"verseLabel":"الأنفال: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿شديد العقاب﴾ لا «شديد العذاب»؟","answer":"العقاب جزاء على الجرم ومؤاخذة به، وهو أنسب لسياق المشاقة والإجرام من لفظ العذاب الأعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص679، تحت عنوان «سر التعبير بالعقاب في قوله: ﴿فإن الله شديد العقاب﴾»","url":""}]},{"id":"s8-88","number":88,"surah":8,"verses":[13],"references":[{"surah":8,"verses":[13]}],"verseLabel":"الأنفال: 13","question":"ما مناسبة إظهار اسم الله في جواب الشرط؟","answer":"أعيد اسم الله حتى لا يتوهم رجوع الضمير إلى أقرب مذكور، وهو الرسول ﷺ، فشدة العقاب هنا لله. كما أن الإظهار يجعل الجملة مستقلة تجري مجرى المثل، مؤكدة هذا الوعيد العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص679، تحت «نكتة الإظهار في محل الإضمار»","url":""}]},{"id":"s8-89","number":89,"surah":8,"verses":[14],"references":[{"surah":8,"verses":[14]}],"verseLabel":"الأنفال: 14","question":"لماذا أُشير إلى العقاب بقوله: ﴿ذلكم فذوقوه﴾؟","answer":"اسم الإشارة يحضر العقاب المشاهد يوم بدر ويعظمه، ثم فرعت عليه صيغة الذوق التي تواجههم بما نزل بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص684، تحت عنوان «نكتة تعريف المسند إليه بالإشارة في قوله: ﴿ذلكم فذوقوه﴾»","url":""}]},{"id":"s8-90","number":90,"surah":8,"verses":[14],"references":[{"surah":8,"verses":[14]}],"verseLabel":"الأنفال: 14","question":"لماذا استعير الذوق للعذاب؟","answer":"عبر بالذوق عن مباشرة العذاب والإحساس به؛ فنقل المعاناة إلى صورة حسية قريبة من الإدراك. وفيه أيضًا أن عذاب الدنيا الذي باشرونه كذوق يسير بالقياس إلى عذاب الآخرة الذي ينتظرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص686، تحت «براعة المجاز في قوله: ﴿ذلكم فذوقوه﴾»","url":""}]},{"id":"s8-91","number":91,"surah":8,"verses":[14],"references":[{"surah":8,"verses":[14]}],"verseLabel":"الأنفال: 14","question":"لماذا انتقل من الخطاب في ﴿فذوقوه﴾ إلى الغيبة في ﴿وأن للكافرين عذاب النار﴾؟","answer":"واجههم أولًا بعذاب الدنيا الواقع: ﴿فذوقوه﴾، ثم عمم الحكم باسم ﴿الكافرين﴾ في عذاب الآخرة؛ فانتقل من الحاضرين إلى جنسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص687، تحت «نكتة الإظهار في محل الإضمار»","url":""}]},{"id":"s8-92","number":92,"surah":8,"verses":[15],"references":[{"surah":8,"verses":[15]}],"verseLabel":"الأنفال: 15","question":"لماذا ناداهم بوصف الإيمان قبل النهي عن الفرار؟","answer":"النداء بوصف الإيمان يستنهض مقتضاه في الثبات والطاعة، ويشعر بأن الفرار لا يليق بمن تحقق بهذا الوصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص693، تحت «دلالة النداء باسم الإيمان»","url":""}]},{"id":"s8-93","number":93,"surah":8,"verses":[15],"references":[{"surah":8,"verses":[15]}],"verseLabel":"الأنفال: 15","question":"ما سرّ التعبير في قوله تعالى: ﴿إذا لقيتم الذين كفروا زحفًا﴾، فجعل «زحفًا» حالًا؟","answer":"﴿زحفًا﴾ حال تصور الجيشين متقاربين يزحف بعضهما إلى بعض في جماعة، وهو الموطن الذي يحرم فيه التولي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص695–696، تحت عنوان «نكتة التعبير بالمصدر حالًا (زحفًا)»","url":""}]},{"id":"s8-94","number":94,"surah":8,"verses":[15],"references":[{"surah":8,"verses":[15]}],"verseLabel":"الأنفال: 15","question":"ما وجه البلاغة في الكناية في قوله: ﴿فلا تولوهم الأدبار﴾؟","answer":"﴿لا تولوهم الأدبار﴾ كناية مصورة عن الفرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص696–697، تحت عنوان «بلاغة الكناية في قوله: ﴿فلا تولوهم الأدبار﴾»","url":""}]},{"id":"s8-276","number":276,"surah":8,"verses":[15],"references":[{"surah":8,"verses":[15]}],"verseLabel":"الأنفال: 15","question":"ما نكتة التعبير بالأدبار دون الظهور؟","answer":"إذ تعرض هيئة المنهزم الذي يجعل ظهره لعدوه، وهي أبلغ في التقبيح من «لا تهربوا».","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص696–697، تحت عنوان «نكتة التعبير بالأدبار دون الظهور»","url":""}]},{"id":"s8-95","number":95,"surah":8,"verses":[16],"references":[{"surah":8,"verses":[16]}],"verseLabel":"الأنفال: 16","question":"ما معنى ﴿متحرفًا﴾ و﴿متحيزًا﴾ في السياق؟","answer":"التحرف خطة داخل القتال، والتحيز انتقال إلى جماعة يستمد بها المقاتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص690، تحت عنوان «شرح المفردات: ﴿متحرفًا﴾ و﴿متحيزًا﴾»","url":""}]},{"id":"s8-277","number":277,"surah":8,"verses":[16],"references":[{"surah":8,"verses":[16]}],"verseLabel":"الأنفال: 16","question":"ما دلالة اللام في قوله: ﴿إلا متحرفًا لقتال﴾؟","answer":"كلاهما حركة لمصلحة القتال لا فرارًا منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص698، تحت عنوان «دلالة اللام في قوله: ﴿إلا متحرفًا لقتال﴾»","url":""}]},{"id":"s8-96","number":96,"surah":8,"verses":[16],"references":[{"surah":8,"verses":[16]}],"verseLabel":"الأنفال: 16","question":"ما دلالة الباء في ﴿بغضب﴾؟","answer":"التبوء يفيد شدة لزوم الغضب له، كأنه اتخذ مكانًا لا يخرج منه. وتزيد الباء معنى الملابسة والمصاحبة؛ فلا يكون جزاء الفرار خوفًا عابرًا، بل غضبًا يلازمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص698–699، تحت عنوان «دلالة الباء في ﴿بغضب﴾»","url":""}]},{"id":"s8-97","number":97,"surah":8,"verses":[16],"references":[{"surah":8,"verses":[16]}],"verseLabel":"الأنفال: 16","question":"كيف سمّى جهنم ﴿مأواه﴾ ثم قال: ﴿وبئس المصير﴾، والمأوى موضع راحة عادة؟","answer":"الأصل أن المأوى مكان يلجأ إليه المرء ليستريح ويستقر، فإطلاقه على جهنم تهكم بمن استحقها؛ إذ صار موضع لجوئه عذابًا. ثم صرح بذم هذه العاقبة في ﴿وبئس المصير﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص699، تحت «بلاغة الاستعارة التهكمية»","url":""}]},{"id":"s8-98","number":98,"surah":8,"verses":[17],"references":[{"surah":8,"verses":[17]}],"verseLabel":"الأنفال: 17","question":"ما دلالة الغرض من أسلوب المجاز في قوله: ﴿ولكن الله قتلهم﴾؟","answer":"المباشرة منهم، والتقدير والتأثير الحاسم من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص707، تحت عنوان «الغرض من أسلوب المجاز في قوله: ﴿ولكن الله قتلهم﴾»","url":""}]},{"id":"s8-278","number":278,"surah":8,"verses":[17],"references":[{"surah":8,"verses":[17]}],"verseLabel":"الأنفال: 17","question":"ما دلالة نفي القتل وعدم كونه واقعًا؟","answer":"نُفي استقلال المؤمنين بالقتل وأثبت لله لأنه هو الذي أقدرهم وأمدهم وألقى الرعب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص705، تحت عنوان «دلالة نفي القتل وعدم كونه واقعًا»","url":""}]},{"id":"s8-99","number":99,"surah":8,"verses":[17],"references":[{"surah":8,"verses":[17]}],"verseLabel":"الأنفال: 17","question":"لماذا انتقل من الجمع في القتل إلى خطاب النبي منفردًا في الرمي؟","answer":"جُمع خطاب القتل لاشتراك المؤمنين فيه، وأُفرد الرمي لاختصاص النبي ﷺ بمباشرته يوم بدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص708، تحت عنوان «دلالة عطف جملة: ﴿وما رميت﴾ على ما قبلها»","url":""}]},{"id":"s8-100","number":100,"surah":8,"verses":[17],"references":[{"surah":8,"verses":[17]}],"verseLabel":"الأنفال: 17","question":"لماذا كرر: ﴿وما رميت إذ رميت﴾، فأثبت الرمي ونفاه في جملة واحدة؟","answer":"أثبت الرمي للنبي ﷺ من جهة المباشرة، ونفى عنه بلوغ أثره الخارق، ثم أثبته لله من جهة الإيصال والتأثير؛ فلا تناقض لاختلاف الجهتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص712، تحت عنوان «دلالة الفعل ﴿رميت﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s8-101","number":101,"surah":8,"verses":[17],"references":[{"surah":8,"verses":[17]}],"verseLabel":"الأنفال: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿وليبلي المؤمنين منه بلاء حسنًا﴾، وسمّى النصر بلاء؟","answer":"البلاء في أصل معناه الاختبار، ويكون بالخير كما يكون بالشر؛ فسُمّي النصر والغنيمة بلاءً حسنًا لأنهما نعمة واختبار يظهر به شكر المؤمنين وحسن طاعتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص702، تحت عنوان «شرح المفردات: ﴿بلاء﴾»","url":""}]},{"id":"s8-102","number":102,"surah":8,"verses":[17],"references":[{"surah":8,"verses":[17]}],"verseLabel":"الأنفال: 17","question":"ما مناسبة الختم بـ﴿إن الله سميع عليم﴾؟","answer":"ناسب ﴿سميع عليم﴾ ما في الموقف من دعاء المؤمنين وأقوالهم ونياتهم؛ فهو سميع لاستغاثتهم، عليم بإيمانهم واستعدادهم للابتلاء الحسن.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص715، تحت «دلالة الختم بهاتين الصفتين الجليلتين ﴿سميع عليم﴾»","url":""}]},{"id":"s8-103","number":103,"surah":8,"verses":[18],"references":[{"surah":8,"verses":[18]}],"verseLabel":"الأنفال: 18","question":"لماذا افتتحت الآية باسم الإشارة: ﴿ذلكم﴾؟","answer":"يشير ﴿ذلكم﴾ إلى ما تقدم من القتل والرمي والنصر والبلاء الحسن، فيجمعه ويحضره أمام المخاطبين تمهيدًا لبيان أنه من تدبير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص718، تحت «دلالة التعبير باسم الإشارة في ﴿ذلكم﴾»","url":""}]},{"id":"s8-104","number":104,"surah":8,"verses":[18],"references":[{"surah":8,"verses":[18]}],"verseLabel":"الأنفال: 18","question":"ما الذي يضيفه لفظ ﴿موهن﴾ في قوله: ﴿موهن كيد الكافرين﴾ إلى تصوير هزيمتهم؟","answer":"الوهن ضعف يصيب القوة النفسية والإرادة والعزيمة؛ فالتعبير يصور أثر الهزيمة في باطنهم، بعد ما كانوا عليه من قوة وسيطرة. لقد نصر الله المؤمنين مع قلة عددهم، فانكسرت بذلك شوكة عدوهم ووهن كيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص722–723، تحت «الوهن والضعف»","url":""}]},{"id":"s8-105","number":105,"surah":8,"verses":[18],"references":[{"surah":8,"verses":[18]}],"verseLabel":"الأنفال: 18","question":"لماذا قال: ﴿موهن كيد الكافرين﴾ بصيغة الاسم، ولم يقل: الذين كفروا؟","answer":"صيغة الاسم تصور تمكن الكفر في هؤلاء الذين استحقوا الهزيمة وتوهين الكيد، وتربط ما أصابهم بوصف راسخ فيهم؛ فناسبت بيان حالهم في هذا السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص721، تحت «سر التعبير بـ﴿الكافرين﴾، دون (الذين كفروا)»","url":""}]},{"id":"s8-106","number":106,"surah":8,"verses":[19],"references":[{"surah":8,"verses":[19]}],"verseLabel":"الأنفال: 19","question":"لماذا عبّر عن دعائهم بالحكم بـ﴿إن تستفتحوا﴾؟","answer":"الاستفتاح طلب الفتح، أي الحكم والفصل بالنصر؛ وقد دعا المشركون أن ينصر الله أهدى الطائفتين، فجاء اللفظ من جنس طلبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص726–727، تحت «سر اختيار ﴿إن تستفتحوا﴾ دون الدعاء»","url":""}]},{"id":"s8-107","number":107,"surah":8,"verses":[19],"references":[{"surah":8,"verses":[19]}],"verseLabel":"الأنفال: 19","question":"ما سرّ التعبير التهكمي في قوله تعالى للمشركين: ﴿فقد جاءكم الفتح﴾، مع أن ما جاءهم كان الهزيمة؟","answer":"في ﴿فقد جاءكم الفتح﴾ تهكم بالمشركين؛ فقد طلبوا الحكم فجاءهم الفصل الذي تمنوه، لكنه ظهر به بطلانهم وكانت نتيجته هزيمتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص727، تحت عنوان «بلاغة الاستعارة في مجيء الفتح»","url":""}]},{"id":"s8-108","number":108,"surah":8,"verses":[19],"references":[{"surah":8,"verses":[19]}],"verseLabel":"الأنفال: 19","question":"لماذا تكرر الشرط في ﴿وإن تنتهوا فهو خير لكم وإن تعودوا نعد﴾؟","answer":"الشرط الأول يفتح لهم باب الانتهاء وما فيه من خير، والثاني يحذرهم من العودة إلى القتال بعودة العقوبة؛ فلكل شرط جهة وجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص730–731، تحت عنوان «دلالة حذف المتعلق في فعل الشرط ﴿تعودوا﴾ وجوابه ﴿نعد﴾»","url":""}]},{"id":"s8-109","number":109,"surah":8,"verses":[19],"references":[{"surah":8,"verses":[19]}],"verseLabel":"الأنفال: 19","question":"ما سرّ التعبير بقوله ﴿شيئًا﴾؟","answer":"نُفي عن فئتهم كل إغناء بـ﴿لن﴾ و﴿شيئًا﴾، ثم أُلغي أثر كثرتها؛ فاجتمع تأكيد النفي والعموم لقطع اغترارهم بالعدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص731، تحت عنوان «سر التعبير بقوله ﴿شيئًا﴾»","url":""}]},{"id":"s8-110","number":110,"surah":8,"verses":[19],"references":[{"surah":8,"verses":[19]}],"verseLabel":"الأنفال: 19","question":"ما مناسبة الختم بـ﴿وأن الله مع المؤمنين﴾؟","answer":"معية الله للمؤمنين هي علة نصرهم وعدم إغناء فئة الكافرين؛ فهي معية تأييد وحفظ، وبها ترجح الفئة المؤمنة وإن قلت.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص733–734، تحت عنوان «دلالة الواو في جملة ﴿وأن﴾»","url":""}]},{"id":"s8-111","number":111,"surah":8,"verses":[20],"references":[{"surah":8,"verses":[20]}],"verseLabel":"الأنفال: 20","question":"لماذا تكرر الأمر بطاعة الله ورسوله بعد وروده في أول السورة؟","answer":"الأمر الأول بالطاعة ورد في سياق قسمة الأنفال، أما هنا ففي الانقياد لأمر الجهاد، وهو أشد على النفس؛ فناسب تجديد الأمر بالطاعة لتثبيت المؤمنين على امتثال هذا التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص740، تحت «سر تكرار الأمر بالطاعة في السياق الحكيم»","url":""}]},{"id":"s8-112","number":112,"surah":8,"verses":[20],"references":[{"surah":8,"verses":[20]}],"verseLabel":"الأنفال: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تولوا عنه﴾ فأفرد الضمير بعد ذكر الله والرسول؟","answer":"يعود الضمير في ﴿عنه﴾ إلى الرسول ﷺ؛ لأن التولي عنه عند تبليغه هو تولٍّ عن أمر الله، وقد أفرد لتعيين جهة السماع والتلقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص742–743، تحت «سر التعبير بالضمير المفرد ﴿عنه﴾»","url":""}]},{"id":"s8-113","number":113,"surah":8,"verses":[20],"references":[{"surah":8,"verses":[20]}],"verseLabel":"الأنفال: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿وأنتم تسمعون﴾، دون أن يقال: وأنتم تعلمون؟","answer":"لأن أوامر الله تبلغهم بقول الرسول ﷺ، والسمع أول طريق لتلقيها؛ فالنهي يشتد على من يعرض عن الطاعة وهو يسمع الأمر ويعرف ما يطلب منه، إذ لم يفقد وسيلة التلقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص744–745، تحت «سر اختيار السماع دون غيره»","url":""}]},{"id":"s8-114","number":114,"surah":8,"verses":[21],"references":[{"surah":8,"verses":[21]}],"verseLabel":"الأنفال: 21","question":"ما دلالة العطف بالواو في ﴿ولا تكونوا﴾؟","answer":"النهي يشبه حال من يدّعي السماع بلسانه ثم لا يقبل ولا يعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص746–747، تحت عنوان «دلالة العطف بالواو في ﴿ولا تكونوا﴾»","url":""}]},{"id":"s8-279","number":279,"surah":8,"verses":[21],"references":[{"surah":8,"verses":[21]}],"verseLabel":"الأنفال: 21","question":"ما دلالة الغرض من التشبيه بقوله ﴿كالذين﴾؟","answer":"الغرض التحذير من أن يكون سماع المؤمنين صوتًا بلا استجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص746–747، تحت عنوان «الغرض من التشبيه بقوله ﴿كالذين﴾»","url":""}]},{"id":"s8-115","number":115,"surah":8,"verses":[21],"references":[{"surah":8,"verses":[21]}],"verseLabel":"الأنفال: 21","question":"لماذا نفى السماع عنهم بعد إثبات قولهم: ﴿سمعنا﴾؟","answer":"أثبتوا لأنفسهم سماع الأذن بقولهم ﴿سمعنا﴾، ونُفي عنهم سماع التدبر والقبول؛ فلا تعارض لاختلاف حقيقة السماع في الموضعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص748–749، تحت «الغرض من التعبير بأسلوب طباق السلب»","url":""}]},{"id":"s8-116","number":116,"surah":8,"verses":[22],"references":[{"surah":8,"verses":[22]}],"verseLabel":"الأنفال: 22","question":"لماذا سمّى الكافرين ﴿شر الدواب﴾ مع أنهم بشر؟","answer":"سُمّوا شر الدواب لأنهم عطلوا السمع والنطق والعقل التي ميز بها الإنسان، فصار الحيوان الجاري على فطرته خيرًا ممن أبطل أدوات الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص753–754، تحت عنوان «سر التعبير بعبارة ﴿شر الدواب﴾»","url":""}]},{"id":"s8-117","number":117,"surah":8,"verses":[22],"references":[{"surah":8,"verses":[22]}],"verseLabel":"الأنفال: 22","question":"لماذا جمع بين ﴿الصم البكم﴾ ثم قال: ﴿الذين لا يعقلون﴾؟","answer":"الصمم يصور امتناعهم عن تلقي الحق، والبكم امتناعهم عن النطق به، ثم كشف ﴿لا يعقلون﴾ أصل الداء: تعطيل العقل الذي ينتفع بالمسموع ويهدي القول.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص754–755، تحت عنوان «سر وصفهم بعدم التعقل في قوله ﴿الذين لا يعقلون﴾»","url":""}]},{"id":"s8-118","number":118,"surah":8,"verses":[22],"references":[{"surah":8,"verses":[22]}],"verseLabel":"الأنفال: 22","question":"لماذا أضيف ﴿شر﴾ إلى ﴿الدواب﴾ في وصفهم؟","answer":"الإضافة تجعل المفاضلة في الشر شاملة جنس الدواب كله؛ فهؤلاء شر ما يدب على الأرض لتعطيلهم ما وهبوا من أدوات الإدراك، وفي هذا أقصى التقبيح لحالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص753، تحت «بلاغة التعبير بالمسند إليه معرفًا بالإضافة»","url":""}]},{"id":"s8-119","number":119,"surah":8,"verses":[23],"references":[{"surah":8,"verses":[23]}],"verseLabel":"الأنفال: 23","question":"ما سر التعبير بقوله ﴿لأسمعهم﴾؟","answer":"المثبت لهم سماع الصوت، والمنفي سماع القبول والفهم النافع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص762، تحت عنوان «بلاغة التعبير بقوله ﴿لأسمعهم﴾»","url":""}]},{"id":"s8-280","number":280,"surah":8,"verses":[23],"references":[{"surah":8,"verses":[23]}],"verseLabel":"الأنفال: 23","question":"ما دلالة الغرض من التعبير بالكناية في الآية؟","answer":"لو علم الله في استعدادهم خيرًا لوهبهم إسماعًا يثمر هداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص762، تحت عنوان «الغرض من التعبير بالكناية في الآية»","url":""}]},{"id":"s8-120","number":120,"surah":8,"verses":[23],"references":[{"surah":8,"verses":[23]}],"verseLabel":"الأنفال: 23","question":"لماذا كرر الإِسماع: ﴿ولو أسمعهم لتولوا﴾ بعد نفي الخير؟","answer":"الإسماع الأول مشروط بوجود الخير فيهم، فهو إسماع فهم للهدى وانتفاع به. والثاني يفترض إسماعهم مع بقاء فساد نفوسهم، فلا يتبعه قبول؛ فمجرد فهم الكلام لا يوجب العمل به ممن أصر على الإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص763–764، تحت «المفارقة في المعنى بين الفعلين: ﴿لأسمعهم﴾ و﴿أسمعهم﴾»","url":""}]},{"id":"s8-121","number":121,"surah":8,"verses":[23],"references":[{"surah":8,"verses":[23]}],"verseLabel":"الأنفال: 23","question":"ما دلالة الجمع بين التولي والإعراض؟","answer":"التولي قد يقع لسبب عارض، أما ﴿وهم معرضون﴾ فيثبت أن الإعراض صفة راسخة فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص765–766، تحت عنوان «دلالة الجمع بين التولي والإعراض»","url":""}]},{"id":"s8-281","number":281,"surah":8,"verses":[23],"references":[{"surah":8,"verses":[23]}],"verseLabel":"الأنفال: 23","question":"ما وجه البلاغة في قيد التولي بالجملة الحالية؟","answer":"جمع بين الفعل الظاهر والدافع الباطن الملازم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص765–766، تحت عنوان «بلاغة قيد التولي بالجملة الحالية»","url":""}]},{"id":"s8-122","number":122,"surah":8,"verses":[24],"references":[{"surah":8,"verses":[24]}],"verseLabel":"الأنفال: 24","question":"لماذا قيل: ﴿استجيبوا لله وللرسول﴾، دون «أجيبوا»؟","answer":"الاستجابة تدل على موافقة الإجابة لما أراده الداعي، فتحقق القبول لدعوته؛ أما الإجابة فقد تكون بالموافقة أو بالمخالفة. فناسبت الاستجابة الأمر بقبول دعوة الله ورسوله والعمل بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص772، تحت «دلالة التعبير بالفعل ﴿استجيبوا﴾»","url":""}]},{"id":"s8-123","number":123,"surah":8,"verses":[24],"references":[{"surah":8,"verses":[24]}],"verseLabel":"الأنفال: 24","question":"لماذا أفرد الضمير في ﴿إذا دعاكم﴾ بعد ذكر الله والرسول؟","answer":"دعوة الرسول ﷺ هنا متحدة مع دعوة الله من جهة وجوب الامتثال، وطاعته طاعة لله؛ فاكتفي بالضمير المفرد، وفيه تأكيد وحدة الدعوة التي يلزم المؤمنين الاستجابة لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص774، تحت «دلالة التعبير بضمير الواحد ﴿دعاكم﴾»","url":""}]},{"id":"s8-124","number":124,"surah":8,"verses":[24],"references":[{"surah":8,"verses":[24]}],"verseLabel":"الأنفال: 24","question":"لماذا وصف الوحي والتكليف بأنه ﴿لما يحييكم﴾؟","answer":"شُبه الوحي والإيمان بالحياة؛ لأنهما يخرجان العقل والقلب من موت الجهل والكفر، ويصلحان حياة الفرد والجماعة في الدنيا والآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص775–776، تحت «الغرض من التعبير بالاستعارة في قوله ﴿يحييكم﴾»","url":""}]},{"id":"s8-125","number":125,"surah":8,"verses":[24],"references":[{"surah":8,"verses":[24]}],"verseLabel":"الأنفال: 24","question":"ما نكتة إيراد ﴿يحول﴾ في السياق؟","answer":"هو مطلع على ما يعزم عليه، وقادر على أن يحول بينه وبين إنفاذ عزمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص777–778، تحت عنوان «نكتة إيراد ﴿يحول﴾ في السياق»","url":""}]},{"id":"s8-282","number":282,"surah":8,"verses":[24],"references":[{"surah":8,"verses":[24]}],"verseLabel":"الأنفال: 24","question":"ما سر التعبير بالاستعارة التمثيلية؟","answer":"تصور العبارة إحاطة علم الله بسرائر الإنسان ونفوذ قدرته في قلبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص777–778، تحت عنوان «بلاغة التعبير بالاستعارة التمثيلية»","url":""}]},{"id":"s8-283","number":283,"surah":8,"verses":[24],"references":[{"surah":8,"verses":[24]}],"verseLabel":"الأنفال: 24","question":"ما دلالة التعبير بالظرف ﴿بين﴾؟","answer":"ي ذلك حث على إخلاص الاستجابة والمبادرة إليها، مع تفويض الأمر إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص777–778، تحت عنوان «دلالة التعبير بالظرف ﴿بين﴾»","url":""}]},{"id":"s8-126","number":126,"surah":8,"verses":[24],"references":[{"surah":8,"verses":[24]}],"verseLabel":"الأنفال: 24","question":"ما وجه المقابلة بين ﴿المرء﴾ و﴿قلبه﴾ في الآية؟","answer":"تقابل العبارة بين الإنسان في أعماله وتصرفاته الجسمانية وبين ما يعزم عليه في قلبه؛ فتدل على أن قدرة الله تحيط بظاهره وباطنه، وقد تحول بين عزمه وبين تنفيذ ما أراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص778، تحت «دلالة التعبير بلفظ ﴿المرء﴾»","url":""}]},{"id":"s8-127","number":127,"surah":8,"verses":[24],"references":[{"surah":8,"verses":[24]}],"verseLabel":"الأنفال: 24","question":"لماذا ختم بـ﴿وأنه إليه تحشرون﴾؟","answer":"ذكر الحشر يؤكد وجوب المبادرة إلى الاستجابة؛ فإلى الله مرجعهم وحسابهم، ولا مهرب ممن يملك القلوب والمصير جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص779، تحت «دلالة عطف قوله ﴿وأنه إليه تحشرون﴾»","url":""}]},{"id":"s8-128","number":128,"surah":8,"verses":[25],"references":[{"surah":8,"verses":[25]}],"verseLabel":"الأنفال: 25","question":"ما سر التعبير بقوله ﴿لا تصيبن﴾؟","answer":"لا يقتصر شر الفتنة على من باشر الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص786–787، تحت عنوان «سر التعبير بقوله ﴿لا تصيبن﴾»","url":""}]},{"id":"s8-284","number":284,"surah":8,"verses":[25],"references":[{"surah":8,"verses":[25]}],"verseLabel":"الأنفال: 25","question":"ما دلالة عدم إصابة الظالمين بالفتنة وحدهم؟","answer":"الأمر باتقائها يحث على منع أسبابها والأخذ على أيدي الظالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص786–787، تحت عنوان «دلالة عدم إصابة الظالمين بالفتنة وحدهم»","url":""}]},{"id":"s8-129","number":129,"surah":8,"verses":[25],"references":[{"surah":8,"verses":[25]}],"verseLabel":"الأنفال: 25","question":"لماذا جيء بنون التوكيد في ﴿لا تصيبن﴾؟","answer":"تؤكد النون شدة التحذير من فتنة لا يقف شرها عند الظالمين. ومن توجيهات الأسلوب أن التحذير صيغ في صورة نهي الفتنة نفسها عن إصابتهم، وهو أبلغ في مطالبتهم باتقاء أسبابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص785–786، تحت عنوان «وجه المعنى على كون ﴿لا تصيبن﴾ جملة استئنافية»","url":""}]},{"id":"s8-130","number":130,"surah":8,"verses":[25],"references":[{"surah":8,"verses":[25]}],"verseLabel":"الأنفال: 25","question":"لماذا خُتمت بـ﴿واعلموا أن الله شديد العقاب﴾؟","answer":"ناسب ﴿شديد العقاب﴾ التحذير من فتنة عامة؛ ليعلموا أن ترك أسبابها والتهاون في دفع الظلم يعرضهم لعقاب شديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص788–789، تحت عنوان «سر التعبير بـ﴿شديد العقاب﴾ دون شديد العذاب»","url":""}]},{"id":"s8-131","number":131,"surah":8,"verses":[26],"references":[{"surah":8,"verses":[26]}],"verseLabel":"الأنفال: 26","question":"لماذا أمرهم بتذكر حال الضعف: ﴿واذكروا إذ أنتم قليل﴾ عقب التحذير من الفتنة؟","answer":"ذكّرهم بحال الضعف والخوف ثم بما أولاهم من الإيواء والنصر والرزق؛ ليعرفوا قدر النعمة، ويقابلوا إحسان الله بالشكر والطاعة، لا بالخيانة ومخالفة أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص793، تحت عنوان «غرض الأمر»","url":""}]},{"id":"s8-132","number":132,"surah":8,"verses":[26],"references":[{"surah":8,"verses":[26]}],"verseLabel":"الأنفال: 26","question":"ما سرّ التعبير في قوله تعالى: ﴿مستضعفون في الأرض﴾، دون أن يقال: ضعفاء؟","answer":"﴿مستضعفون﴾ تدل على أن غيرهم كان يتعمد إضعافهم وقهرهم، لا أنهم ضعفاء في ذواتهم؛ ولذلك هي أدق من «ضعفاء».","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص796، تحت «دلالة السين والتاء»","url":""}]},{"id":"s8-133","number":133,"surah":8,"verses":[26],"references":[{"surah":8,"verses":[26]}],"verseLabel":"الأنفال: 26","question":"لماذا عبّر بـ﴿يتخطفكم الناس﴾؟","answer":"التخطف أخذ سريع فيه غلبة واستلاب؛ فاستعير لما كانوا يخافونه من استئصال عدوهم لهم. وهو يصور شدة ضعفهم وخوفهم من أن يفاجئهم الأعداء قبل أن يقدروا على الامتناع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص798–799، تحت عنوان «نكتة استعمال أن المصدرية بدل المصدر الصريح»","url":""}]},{"id":"s8-134","number":134,"surah":8,"verses":[26],"references":[{"surah":8,"verses":[26]}],"verseLabel":"الأنفال: 26","question":"لماذا حُذف متعلق الإيواء في ﴿فآواكم﴾، فلم يقل: إلى المدينة؟","answer":"حُذف متعلق الإيواء لتتسع المنة لكل ما آواهم الله إليه من المدينة والأمن وجماعة الأنصار، ولأن المقصود نفس الانتقال من الخوف إلى المأمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص800، تحت «علة حذف المتعلقات وذكرها»","url":""}]},{"id":"s8-135","number":135,"surah":8,"verses":[26],"references":[{"surah":8,"verses":[26]}],"verseLabel":"الأنفال: 26","question":"لماذا رتّب: ﴿فآواكم وأيدكم بنصره ورزقكم من الطيبات﴾؟","answer":"بدأ بالإيواء لأنه أمن المكان، ثم التأييد بالنصر لأنه أمن من العدو، ثم الرزق لأنه تمام استقرار الحياة؛ فترتيب النعم جارٍ من دفع الخوف إلى كمال العيش.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص801، تحت «بلاغة ترتيب الأفعال»","url":""}]},{"id":"s8-136","number":136,"surah":8,"verses":[27],"references":[{"surah":8,"verses":[27]}],"verseLabel":"الأنفال: 27","question":"لماذا سمّى مخالفة أمر الله ورسوله ﴿خيانة﴾؟","answer":"الخيانة نقض العهد في السر وإنقاص الحق؛ فمخالفة أمر الله ورسوله بعد الالتزام بالإيمان نقض للأمانة التي حملها المؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص14، تحت عنوان «دلالة التعبير بمفردة الخيانة»","url":""}]},{"id":"s8-137","number":137,"surah":8,"verses":[27],"references":[{"surah":8,"verses":[27]}],"verseLabel":"الأنفال: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿وتخونوا أماناتكم﴾، فعطف الخيانة على الخيانة؟","answer":"الخيانة الأولى تتعلق بحق الله ورسوله في الطاعة، والثانية بحقوق الأمانات المتعددة بين الناس؛ وعطفها يبين تلازم الحقين مع اختلاف متعلقهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص17، تحت «دلالة تكرار الألفاظ»","url":""}]},{"id":"s8-138","number":138,"surah":8,"verses":[27],"references":[{"surah":8,"verses":[27]}],"verseLabel":"الأنفال: 27","question":"لماذا جمع ﴿أماناتكم﴾ ولم يفردها؟","answer":"إضافة جمع الأمانات إلى جماعة المخاطبين تفيد توزيعها عليهم: لكل مؤمن ما اؤتمن عليه من الحقوق والتكاليف. وتجمعها الآية في عهد مشترك يجب حفظه؛ فخيانة أمانة الفرد إخلال بما يجب على جماعة المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص17–18، تحت «فائدة إضافة الجمع إلى مجموع المخاطبين»","url":""}]},{"id":"s8-139","number":139,"surah":8,"verses":[27],"references":[{"surah":8,"verses":[27]}],"verseLabel":"الأنفال: 27","question":"لماذا ختم بـ﴿وأنتم تعلمون﴾؟","answer":"جاءت الحال لتشنيع الخيانة مع علمهم بقبحها وما يترتب عليها؛ فهم أهل تمييز يدركون أن الخيانة لا تليق بالمؤمن. وليس المراد تقييد النهي بحالة العلم، بل تأكيد قبح الفعل ومسؤوليتهم عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص18–19، تحت «بلاغة الجملة الحالية»","url":""}]},{"id":"s8-140","number":140,"surah":8,"verses":[28],"references":[{"surah":8,"verses":[28]}],"verseLabel":"الأنفال: 28","question":"لماذا سمّى الأموال والأولاد ﴿فتنة﴾ مع أنهما نعمة؟","answer":"الفتنة هي الاختبار الذي يكشف موقف الإنسان؛ فالمال والولد نعمة في ذاتهما، وقد يصيران سببًا للانشغال عن الطاعة أو الوقوع في الخيانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص22، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s8-141","number":141,"surah":8,"verses":[28],"references":[{"surah":8,"verses":[28]},{"surah":9,"verses":[55]}],"verseLabel":"الأنفال: 28؛ التوبة: 55","question":"ما سرّ تقديم الأموال على الأولاد؟","answer":"في الأنفال: 28: قدمت الأموال لأن الخيانة تتعلق بها أكثر، ولأنها تقضي أغراضًا كثيرة وتتسع بها دواعي الافتتان، فناسب تقديمها سياق النهي عن الخيانة.\n\nفي التوبة: 55: قدمت الأموال لأن فتنتها أعم من فتنة الأولاد؛ فالرغبة فيها تشمل من له ولد ومن لا ولد له، وهي أيضًا وسيلة إلى كثير من رغبات الحياة. فناسب تقديم الأعم في التحذير من الإعجاب بما عند المنافقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص25، تحت عنوان «نكتة تقديم الأموال على الأولاد»","url":""}]},{"id":"s8-142","number":142,"surah":8,"verses":[28],"references":[{"surah":8,"verses":[28]}],"verseLabel":"الأنفال: 28","question":"لماذا قابل الفتنة بقوله: ﴿وأن الله عنده أجر عظيم﴾؟","answer":"قوبل نفع المال والولد العاجل بالأجر العظيم عند الله؛ ليختار المؤمن الباقي الأعظم، فلا تحمله محبتهما على الخيانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص26، تحت عنوان «فائدة العطف بالواو»","url":""}]},{"id":"s8-143","number":143,"surah":8,"verses":[29],"references":[{"surah":8,"verses":[29]}],"verseLabel":"الأنفال: 29","question":"لماذا كرر شرط التقوى بعد قوله في أول السورة: ﴿فاتقوا الله﴾؟","answer":"الأمر الأول بالتقوى جاء عقب النزاع في الأنفال، وهنا جُعلت التقوى شرطًا لمنحة الفرقان والتكفير والمغفرة؛ فتكرر لاختلاف المقام والثمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص32، تحت عنوان «غرض الأمر بالتقوى بجملة الشرط»","url":""}]},{"id":"s8-144","number":144,"surah":8,"verses":[29],"references":[{"surah":8,"verses":[29]}],"verseLabel":"الأنفال: 29","question":"لماذا سمّى البصيرة الفاصلة ﴿فرقانًا﴾؟","answer":"الفرقان ما يفرق به بين الحق والباطل والهدى والضلال؛ فسمّيت البصيرة والنصرة فرقانًا لما تمنحه التقوى من تمييز وفصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص34، تحت «سر اختيار الألفاظ»","url":""}]},{"id":"s8-145","number":145,"surah":8,"verses":[29],"references":[{"surah":8,"verses":[29]}],"verseLabel":"الأنفال: 29","question":"لماذا جمع بين تكفير السيئات والمغفرة؟","answer":"من وجوه الفرق أن التكفير ستر السيئات في الدنيا، والمغفرة عدم المؤاخذة بها في الآخرة؛ فجمع الوعدين إتمام للمنة على المتقين. ويذكر المصدر أيضًا توجيه التكفير إلى الصغائر والمغفرة إلى الكبائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص36، تحت عنوان «بلاغة ترتيب المعطوفات»","url":""}]},{"id":"s8-146","number":146,"surah":8,"verses":[29],"references":[{"surah":8,"verses":[29]}],"verseLabel":"الأنفال: 29","question":"ما مناسبة الختم بـ﴿والله ذو الفضل العظيم﴾؟","answer":"خُتم بذي الفضل العظيم لأن الفرقان والتكفير والمغفرة عطايا زائدة من فضل الله، لا ثمناً تستقل التقوى باستحقاقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص37، تحت عنوان «بلاغة التذييل بالفاصلة»","url":""}]},{"id":"s8-147","number":147,"surah":8,"verses":[30],"references":[{"surah":8,"verses":[30]}],"verseLabel":"الأنفال: 30","question":"لماذا عُبر عن مؤامرة قريش بالمضارع: ﴿وإذ يمكر بك﴾؟","answer":"المضارع ﴿يمكر﴾ يستحضر المؤامرة الماضية كأنها حاضرة، ويصور تتابع تدبيرهم وتنوع حيلهم حول النبي ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص43، تحت «نكتة التعبير بالفعل المضارع»","url":""}]},{"id":"s8-148","number":148,"surah":8,"verses":[30],"references":[{"surah":8,"verses":[30]}],"verseLabel":"الأنفال: 30","question":"لماذا رتبت خياراتهم: ﴿ليثبتوك أو يقتلوك أو يخرجوك﴾؟","answer":"رتبت بحسب أثرها في الرسول ﷺ ودعوته: قدم الحبس لأنه يمنعه من لقاء الناس وتبليغ الحق، وهو أشد عليه؛ ثم القتل الذي ينال به الشهادة، ثم الإخراج وهو أهون من سابقَيه. فالترتيب يراعي ما يريده أعداؤه من تعطيل رسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص46–47، تحت «بلاغة ترتيب الأفعال»","url":""}]},{"id":"s8-149","number":149,"surah":8,"verses":[30],"references":[{"surah":8,"verses":[30]}],"verseLabel":"الأنفال: 30","question":"لماذا كرر ﴿ويمكرون ويمكر الله﴾؟","answer":"قوبل مكرهم بتدبير الله الذي يرد كيدهم ويبطل غرضهم. ويذكر المصدر المشاكلة وجهًا في تسمية جزاء المكر مكرًا؛ فمكرهم عدوان خفي، وتدبير الله إبطال له ومجازاة عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص50، تحت «فن المشاكلة»","url":""}]},{"id":"s8-150","number":150,"surah":8,"verses":[30],"references":[{"surah":8,"verses":[30]}],"verseLabel":"الأنفال: 30","question":"لماذا خُتم بـ﴿والله خير الماكرين﴾؟","answer":"﴿خير الماكرين﴾ تقرر أن تدبير الله غالب محكم يحيط بحيلهم ويردها عليهم، فناسبت ختام مشهد المؤامرة وإفشالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص50–51، تحت «نكتة اختيار المفردات»","url":""}]},{"id":"s8-151","number":151,"surah":8,"verses":[31],"references":[{"surah":8,"verses":[31]}],"verseLabel":"الأنفال: 31","question":"ما دلالة تأكيدهم السماع بقولهم: ﴿قد سمعنا﴾؟","answer":"أكدوا تحقق السماع بـ﴿قد﴾ والفعل الماضي ليوهموا أنهم أحاطوا بما يسمعون، وأنهم لا يحتاجون إلى مزيد تلاوة أو تدبر. وقصدهم الاستهانة والإعراض؛ كأنهم يقولون: سمعنا ما تقول فلا حاجة إلى تكراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص59، تحت عنوان «نكتة التعبير بصيغة الماضي»","url":""}]},{"id":"s8-152","number":152,"surah":8,"verses":[31],"references":[{"surah":8,"verses":[31]}],"verseLabel":"الأنفال: 31","question":"لماذا عبّروا عن القرآن بـ﴿أساطير الأولين﴾؟","answer":"الأساطير ما سطر من أخبار الأولين التي لا حقيقة لها في زعمهم؛ فوصفوا القرآن بها طعنًا في الوحي وفرارًا من حجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص64، تحت عنوان «بلاغة النظم في التنبيه على غايات الخصم»","url":""}]},{"id":"s8-153","number":153,"surah":8,"verses":[31],"references":[{"surah":8,"verses":[31]}],"verseLabel":"الأنفال: 31","question":"ما دلالة قولهم: ﴿لو نشاء لقلنا مثل هذا﴾ ولم يأتوا بمثله؟","answer":"علقوا الإتيان بالمثل على مشيئتهم ليزعموا القدرة مع ترك الفعل، لكن عجزهم العملي فضح الدعوى؛ فلم يأتوا بمثله مع قيام التحدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص54، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s8-154","number":154,"surah":8,"verses":[32],"references":[{"surah":8,"verses":[32]}],"verseLabel":"الأنفال: 32","question":"ما دلالة قولهم: ﴿إن كان هذا هو الحق﴾ بضمير الفصل؟","answer":"ضمير الفصل ﴿هو﴾ يفيد القصر في دعواهم: إن كان هذا القرآن هو الحق وحده؛ وجاء كلامهم على سبيل المكابرة والتشكيك لا طلب اليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص71، تحت عنوان «معنى التعريف في لفظ ﴿الحق﴾»","url":""}]},{"id":"s8-155","number":155,"surah":8,"verses":[32],"references":[{"surah":8,"verses":[32]}],"verseLabel":"الأنفال: 32","question":"لماذا طلبوا نزول الحجارة بدل أن يسألوا الهداية إن كان حقًا؟","answer":"طلبوا العذاب بدل الهداية مبالغة في الجحود والثقة بباطلهم؛ فقدموا المكابرة والتحدي على طلب النجاة لو ظهر الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص71–72، تحت «بلاغة فعل الأمر»","url":""}]},{"id":"s8-156","number":156,"surah":8,"verses":[32],"references":[{"surah":8,"verses":[32]}],"verseLabel":"الأنفال: 32","question":"كيف يُوجَّه بلاغيًا المخصوص بالذكر في قوله تعالى: ﴿فأمطر علينا حجارة من السماء﴾؟","answer":"خصوا إمطار الحجارة لما فيه من ألم الأجسام وإذلال النفوس، ولما عرفوه من عذاب أصحاب الفيل. وزادوا ﴿من السماء﴾ تأكيدًا لطلب عقوبة خارقة من عند الله، تهكمًا وتحديًا للرسول ﷺ، لا رغبة في الاهتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص72، تحت عنوان «توجيه المخصوص بالذكر»","url":""}]},{"id":"s8-157","number":157,"surah":8,"verses":[33],"references":[{"surah":8,"verses":[33]}],"verseLabel":"الأنفال: 33","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كان الله ليعذبهم وأنت فيهم﴾ بصيغة الجحود المؤكد؟","answer":"صيغة ﴿ما كان الله ليعذبهم﴾ أبلغ في النفي من «لا يعذبهم»؛ فهي تنفي ملاءمة العذاب لسنة الله ورسوله ﷺ بين أظهرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص81، تحت عنوان «بلاغة أسلوب النفي»","url":""}]},{"id":"s8-158","number":158,"surah":8,"verses":[33],"references":[{"surah":8,"verses":[33]}],"verseLabel":"الأنفال: 33","question":"لماذا انتقل من وجود النبي إلى الاستغفار: ﴿وما كان الله معذبهم وهم يستغفرون﴾؟","answer":"كان وجود الرسول ﷺ أمانًا مؤقتًا في حياته بينهم، والاستغفار أمانًا متجددًا يبقى بابه للأمة؛ فانتقل من المانع الخاص إلى السبب العام المستمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص79، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s8-159","number":159,"surah":8,"verses":[33],"references":[{"surah":8,"verses":[33]}],"verseLabel":"الأنفال: 33","question":"لماذا جاءت الأولى ﴿ليعذبهم﴾ والثانية ﴿معذبهم﴾؟","answer":"الفعل ﴿ليعذبهم﴾ مع لام الجحود يناسب نفي وقوع العذاب في حال وجود الرسول، واسم الفاعل ﴿معذبهم﴾ يصور ثبات انتفاء وصف التعذيب حال استغفارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص84، تحت عنوان «سر اختلاف التعبير بين المتقابلات»","url":""}]},{"id":"s8-160","number":160,"surah":8,"verses":[34],"references":[{"surah":8,"verses":[34]}],"verseLabel":"الأنفال: 34","question":"لماذا استدرك بقوله: ﴿وما لهم ألا يعذبهم الله﴾ بعد نفي العذاب؟","answer":"نفي العذاب مقيد بوجود الرسول والاستغفار، أما استحقاقهم له فثابت بسبب صدهم؛ فالاستدراك يفرق بين تأخير العذاب وانتفاء موجبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص88، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s8-161","number":161,"surah":8,"verses":[34],"references":[{"surah":8,"verses":[34]}],"verseLabel":"الأنفال: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿وهم يصدون عن المسجد الحرام﴾ بالمضارع؟","answer":"المضارع ﴿يصدون﴾ يصور استمرارهم وتجدد منعهم الناس من المسجد الحرام، فكان الجرم قائمًا لا حادثة منقطعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص92، تحت «دلالة التعبير بلفظ ﴿يصدون﴾»","url":""}]},{"id":"s8-162","number":162,"surah":8,"verses":[34],"references":[{"surah":8,"verses":[34]}],"verseLabel":"الأنفال: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كانوا أولياءه﴾ ثم حصر الولاية في المتقين؟","answer":"نُفيت ولايتهم للبيت رغم دعواهم، ثم قُصرت ولايته على المتقين؛ لأن الولاية حقها الحفظ والتعظيم والطاعة، لا الصد والكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص98، تحت عنوان «سر التعبير بالمتقين دون المؤمنين أو المسلمين»","url":""}]},{"id":"s8-163","number":163,"surah":8,"verses":[35],"references":[{"surah":8,"verses":[35]}],"verseLabel":"الأنفال: 35","question":"لماذا سمّى صفيرهم وتصفيقهم عند البيت ﴿صلاة﴾؟","answer":"سُمّي مكاؤهم وتصديتهم صلاة على سبيل التهكم أو بحسب زعمهم؛ إذ جعلوا الصفير والتصفيق بدل العبادة، فاشتد ذم فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص105–106، تحت «الغرض من الاستعارة في لفظ ﴿صلاتهم﴾»","url":""}]},{"id":"s8-164","number":164,"surah":8,"verses":[35],"references":[{"surah":8,"verses":[35]}],"verseLabel":"الأنفال: 35","question":"لماذا نُكّر لفظا ﴿مكاء وتصدية﴾ في وصف صلاتهم؟","answer":"جاء التنكير لتحقير ما اتخذوه عبادة، وبيان استخفافهم بحرمة البيت؛ فما كان ينبغي أن يكون تعظيمًا وتذللًا صار صفيرًا وتصفيقًا ولهوًا واعتداء على المصلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص107، تحت «فائدة تنكير لفظي ﴿مكاء وتصدية﴾ في الآية»","url":""}]},{"id":"s8-165","number":165,"surah":8,"verses":[35],"references":[{"surah":8,"verses":[35]}],"verseLabel":"الأنفال: 35","question":"ما دلالة الفاء في قوله: ﴿فذوقوا العذاب﴾؟","answer":"تربط الفاء العذاب بكفرهم، فتفيد أن ما يذوقونه نتيجة عاجلة مترتبة على إصرارهم على الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص108، تحت عنوان «معنى الفاء في ﴿فذوقوا﴾»","url":""}]},{"id":"s8-285","number":285,"surah":8,"verses":[35],"references":[{"surah":8,"verses":[35]}],"verseLabel":"الأنفال: 35","question":"ما دلالة الأمر في قوله: ﴿فذوقوا﴾؟","answer":"الأمر للتهديد والتوبيخ، وفي لفظ الذوق تصوير لمباشرة العذاب وإحساسهم به إحساسًا لا مهرب منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص109، تحت عنوان «فائدة الأمر ودلالته في ﴿فذوقوا﴾»","url":""}]},{"id":"s8-286","number":286,"surah":8,"verses":[35],"references":[{"surah":8,"verses":[35]}],"verseLabel":"الأنفال: 35","question":"لماذا عبّر بالمضارع في قوله: ﴿تكفرون﴾؟","answer":"يصور المضارع تجدد كفرهم واستمرارهم عليه، فيناسب تجدد استحقاقهم للعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص110، تحت عنوان «سر التعبير بالمضارع في ﴿تكفرون﴾»","url":""}]},{"id":"s8-167","number":167,"surah":8,"verses":[36,37],"references":[{"surah":8,"verses":[36,37]}],"verseLabel":"الأنفال: 36–37","question":"لماذا جمع ﴿أموالهم﴾ وأضافها إليهم في قوله: ﴿ينفقون أموالهم﴾؟","answer":"الجمع يدل على كثرة ما بذلوه وتنوعه، من نقود وكراع وسلاح وغيرها. وإضافتها إليهم تبرز شدة تعلقهم بها، فيعظم تقبيح إنفاقهم ما يحبون في الصد عن سبيل الله، ثم خيبتهم فيما قصدوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص117، تحت «نكتة جمع لفظ الأموال وإضافتها إليهم»","url":""}]},{"id":"s8-168","number":168,"surah":8,"verses":[36,37],"references":[{"surah":8,"verses":[36,37]}],"verseLabel":"الأنفال: 36–37","question":"لماذا تحولت النفقة إلى ﴿حسرة عليهم﴾؟","answer":"تصير النفقة نفسها حسرة حين تذهب الأموال ولا تتحقق غايتهم، ثم يرونها سببًا لهزيمتهم وعقابهم؛ فتنقلب وسيلة القوة إلى ندم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص121، تحت عنوان «بلاغة الإخبار بالمصدر بلفظ ﴿حسرة﴾»","url":""}]},{"id":"s8-169","number":169,"surah":8,"verses":[36,37],"references":[{"surah":8,"verses":[36,37]}],"verseLabel":"الأنفال: 36–37","question":"لماذا قال: ﴿ثم يغلبون﴾ بعد قوله: ﴿ثم تكون عليهم حسرة﴾؟","answer":"لا تقف خيبتهم عند ذهاب المال من غير تحقيق الغرض، بل تعقبها الهزيمة. وتدل ﴿ثم﴾ على التراخي زمانًا أو رتبة؛ فالغلبة أشد عليهم من خسارة الأموال، وفي ترتيب الوعيد تصاعد في بيان سوء عاقبتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص122، تحت عنوان «معنى ثم العاطفة وأثرها في السياق»","url":""}]},{"id":"s8-170","number":170,"surah":8,"verses":[36,37],"references":[{"surah":8,"verses":[36,37]}],"verseLabel":"الأنفال: 36–37","question":"ما الصورة في قوله تعالى: ﴿ويجعل الخبيث بعضه على بعض فيركمه جميعًا﴾؟","answer":"يصوّر جمع أهل الكفر في ازدحام وتراكم، بعضهم فوق بعض، كحطب مركب يلقى في النار. وفيه إهانة لهم وإسقاط لكرامتهم، ويؤكد ﴿جميعًا﴾ أن المصير شامل لأفراد هذا الخبيث.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص131، تحت عنوان «نكتة التوكيد بلفظ ﴿جميعًا﴾»","url":""}]},{"id":"s8-171","number":171,"surah":8,"verses":[38],"references":[{"surah":8,"verses":[38]}],"verseLabel":"الأنفال: 38","question":"لماذا وُجه خطاب الكافرين بصيغة الغائب: ﴿قل للذين كفروا إن ينتهوا﴾؟","answer":"العدول إلى الغيبة يدل على أن المطلوب من الرسول ﷺ تبليغ مضمون الوعد والوعيد، فيجوز أن يؤديه بما يبين معناه، لا أن يكون مجرد ناقل للألفاظ بحروفها. وفي ذلك تشريف لمنزلته في البيان والتبليغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص139–140، تحت «نكتة إسناد القول للغائبين»","url":""}]},{"id":"s8-172","number":172,"surah":8,"verses":[38],"references":[{"surah":8,"verses":[38]}],"verseLabel":"الأنفال: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿يغفر لهم ما قد سلف﴾، ولم يعدد جرائمهم؟","answer":"الموصول ﴿ما﴾ يفيد عموم ما مضى من جرائمهم وآثامهم؛ فيظهر سعة المغفرة عند الانتهاء عن الكفر. ولو قيل: ذنوبهم، لاحتمل قصر المراد على الكبائر، أما هذا اللفظ فيجمع ما سلف كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص142، تحت «معنى ما في ﴿ما قد سلف﴾ في الآية»","url":""}]},{"id":"s8-173","number":173,"surah":8,"verses":[38],"references":[{"surah":8,"verses":[38]}],"verseLabel":"الأنفال: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿فقد مضت سنة الأولين﴾ بدل التصريح بالعذاب؟","answer":"﴿سنة الأولين﴾ تحيل إلى قانون معلوم من هلاك المكذبين، فتغني عن تفصيل الوعيد وتجعله مؤيدًا بشواهد التاريخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص146، تحت عنوان «سر إضافة السنة للأولين»","url":""}]},{"id":"s8-175","number":175,"surah":8,"verses":[39,40],"references":[{"surah":8,"verses":[39,40]}],"verseLabel":"الأنفال: 39–40","question":"لماذا أفرد ﴿الدين﴾ ووصفه بـ﴿كله﴾؟","answer":"أُفرد ﴿الدين﴾ لأنه الملة والطاعة بوصفهما حقيقة واحدة، وأكد بـ﴿كله﴾ لنفي أن يبقى شيء من سلطان العبادة لغير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص153، تحت عنوان «معنى أل الجنسية في لفظ ﴿الدين﴾ ودلالتها»","url":""}]},{"id":"s8-176","number":176,"surah":8,"verses":[39,40],"references":[{"surah":8,"verses":[39,40]}],"verseLabel":"الأنفال: 39–40","question":"لماذا ختم حال انتهائهم بـ﴿فإن الله بما يعملون بصير﴾؟","answer":"﴿بصير﴾ يناسب انتهاءهم الذي قد يخفى صدقه؛ فالله يرى أعمالهم وبواطنها، ويجازيهم على حقيقة ما يعملون.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص159، تحت «بلاغة اختيار اسم ﴿بصير﴾ لفاصلة الآية»","url":""}]},{"id":"s8-177","number":177,"surah":8,"verses":[39,40],"references":[{"surah":8,"verses":[39,40]}],"verseLabel":"الأنفال: 39–40","question":"ما مناسبة قوله تعالى عند توليهم: ﴿فاعلموا أن الله مولاكم﴾؟","answer":"عند توليهم ثُبّت المؤمنون بأن الله مولاهم؛ فهو متولي نصرهم وتدبيرهم، فلا يضرهم إعراض العدو ما دام الله ناصرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص160، تحت عنوان «بلاغة التعبير بالجملة الشرطية»","url":""}]},{"id":"s8-178","number":178,"surah":8,"verses":[41],"references":[{"surah":8,"verses":[41]}],"verseLabel":"الأنفال: 41","question":"ما سرّ التعبير في قوله تعالى: ﴿واعلموا أنما غنمتم من شيء﴾، فجمع «ما» و«من شيء»؟","answer":"﴿ما﴾ تعم كل ما غنم، و﴿من شيء﴾ تؤكد هذا العموم حتى أدنى شيء؛ فلا يخرج من حكم الخمس قليل ولا كثير.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص175، تحت عنوان «نكتة التعبير بلفظ ﴿شيء﴾»","url":""}]},{"id":"s8-179","number":179,"surah":8,"verses":[41],"references":[{"surah":8,"verses":[41]}],"verseLabel":"الأنفال: 41","question":"لماذا أعاد ﴿لله﴾ في الخمس مع أن المال كله لله؟","answer":"ذُكر ﴿لله﴾ افتتاحًا للتقسيم لإظهار أن الخمس محكوم بأمره ومصرفه، لا لأن لله سهمًا ينتفع به؛ فالمال كله له ملكًا وهذا تخصيص حكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص176، تحت عنوان «مناسبة إفراد اسم الله في المعاطيف»","url":""}]},{"id":"s8-180","number":180,"surah":8,"verses":[41],"references":[{"surah":8,"verses":[41]}],"verseLabel":"الأنفال: 41","question":"لماذا وصف يوم بدر بـ﴿يوم الفرقان يوم التقى الجمعان﴾؟","answer":"سمي بدر يوم الفرقان لأنه فصل بين الحق والباطل بالنصر، وفسره ﴿يوم التقى الجمعان﴾ بتعيين الواقعة التي ظهر فيها ذلك الفرق.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص187، تحت عنوان «مناسبة تخصيص الإنزال»","url":""}]},{"id":"s8-181","number":181,"surah":8,"verses":[41],"references":[{"surah":8,"verses":[41]}],"verseLabel":"الأنفال: 41","question":"ما مناسبة الختم بـ﴿والله على كل شيء قدير﴾؟","answer":"القدرة الإلهية هي التي دبرت اللقاء والنصر وقسمة الغنيمة على غير توقع البشر؛ فختم الآية يرد الأمر كله إلى قدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص190، تحت عنوان «مناسبة إيثار لفظ ﴿قدير﴾»","url":""}]},{"id":"s8-182","number":182,"surah":8,"verses":[42],"references":[{"surah":8,"verses":[42]}],"verseLabel":"الأنفال: 42","question":"ما فائدة تفصيل موضعي الجيشين بالعدوة الدنيا والعدوة القصوى؟","answer":"يعيد التفصيل تصوير مشهد بدر وما فيه من أسباب ترجّح كفة المشركين؛ فموضعهم كان أصلح للاستقرار، وموضع المسلمين أصعب سيرًا. وبذلك يظهر أن النصر مع ضعف الأسباب الظاهرة كان من تدبير الله ولطفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص196، تحت عنوان «براعة الإطناب في الآية قيد التفسير»","url":""}]},{"id":"s8-183","number":183,"surah":8,"verses":[42],"references":[{"surah":8,"verses":[42]}],"verseLabel":"الأنفال: 42","question":"ما فائدة ذكر موقع الركب في قوله: ﴿والركب أسفل منكم﴾ ضمن مشهد الجيشين؟","answer":"ذكر العير القريبة منهم يبين تعقد الموقف؛ فالمشركون جاءوا لحمايتها، والمسلمون كانوا يطلبونها، ثم صرفهم الله عنها إلى لقاء الجيش الذي يكرهونه. فكان جمع هذه الأطراف على ذلك الوجه من إحكام تدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص196، تحت «دلالة الواو في قوله ﴿والركب أسفل منكم﴾»","url":""}]},{"id":"s8-184","number":184,"surah":8,"verses":[42],"references":[{"surah":8,"verses":[42]}],"verseLabel":"الأنفال: 42","question":"ما دلالة الواو في قوله ﴿ولو﴾؟","answer":"لو كان اللقاء عن موعد سابق لاختلف الفريقان في زمانه أو مكانه لما في النفوس من رهبة وعدم استعداد؛ لكن الله جمعهم بغير تواعد ليقضي أمرًا مقدرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص197، تحت عنوان «دلالة الواو في قوله ﴿ولو﴾»","url":""}]},{"id":"s8-185","number":185,"surah":8,"verses":[42],"references":[{"surah":8,"verses":[42]}],"verseLabel":"الأنفال: 42","question":"لماذا تكرر ﴿ليهلك من هلك عن بينة ويحيا من حي عن بينة﴾؟","answer":"قوبل الهلاك بالحياة لتصوير أثر البينة: من اختار الكفر بعد ظهورها فكأنه هلك، ومن آمن بها فقد حيي؛ وتكرار الصلة يثبت قيام الحجة على الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص202، تحت عنوان «دلالة ﴿ليهلك﴾ و﴿ويحيا﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s8-186","number":186,"surah":8,"verses":[43,44],"references":[{"surah":8,"verses":[43,44]}],"verseLabel":"الأنفال: 43–44","question":"لماذا أراهم الله للنبي في المنام ﴿قليلًا﴾؟","answer":"أراه الله عدوه قليلًا في المنام، فأخبر أصحابه فثبتت قلوبهم وتشجعوا على اللقاء، بدل أن تحملهم رؤية الكثرة على الوهن والاختلاف. ونسبت الإراءة إلى الله لتأكيد صدق رؤيا النبي ﷺ وما تحقق بها من التثبيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص210، تحت عنوان «نكتة إسناد الفعل إلى الله تعالى في قوله ﴿يريكهم الله﴾»","url":""}]},{"id":"s8-187","number":187,"surah":8,"verses":[43,44],"references":[{"surah":8,"verses":[43,44]}],"verseLabel":"الأنفال: 43–44","question":"لماذا انتقل من خطاب المفرد في ﴿أراكهم﴾ إلى الجمع في ﴿لفشلتم ولتنازعتم﴾؟","answer":"أسندت الإراءة إلى النبي ﷺ وحده، ثم عُدل إلى جماعة المؤمنين عند ذكر الفشل والتنازع؛ تنزيهًا لمقام الرسول عن نسبة الوهن إليه، وتصويرًا لما قد يقع في أصحابه عند رؤيتهم كثرة العدو.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص212، تحت «بلاغة الالتفات في قوله ﴿ولو أراكهم كثيرًا لفشلتم﴾»","url":""}]},{"id":"s8-188","number":188,"surah":8,"verses":[43,44],"references":[{"surah":8,"verses":[43,44]}],"verseLabel":"الأنفال: 43–44","question":"لماذا قلّل كل فريق في عين الآخر عند اللقاء؟","answer":"قلل المؤمنين في أعين المشركين ليقدموا فلا ينسحبوا، وقلل المشركين في أعين المؤمنين ليثبتوا؛ وبذلك تم اللقاء الذي قضاه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص221، تحت عنوان «حكمة التقليل في رؤية العين للفريقين»","url":""}]},{"id":"s8-189","number":189,"surah":8,"verses":[43,44],"references":[{"surah":8,"verses":[43,44]}],"verseLabel":"الأنفال: 43–44","question":"لماذا ختم المشهد بـ﴿وإلى الله ترجع الأمور﴾؟","answer":"الخاتمة تكشف أن تدبير الرؤيا وتقليل الفريقين وإنفاذ اللقاء كلها أمور مردها إلى الله، فلا تستقل بها الأسباب الظاهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص224، تحت عنوان «دلالة أل في لفظ ﴿الأمور﴾»","url":""}]},{"id":"s8-190","number":190,"surah":8,"verses":[44],"references":[{"surah":8,"verses":[44]}],"verseLabel":"الأنفال: 44","question":"كيف يُجمع بين قوله تعالى في الأنفال: ﴿ويقللكم في أعينهم﴾، وقوله في آل عمران: ﴿يرونهم مثليهم رأي العين﴾؟","answer":"كان التقليل في أول اللقاء ليقدم الفريقان، ثم أُري المشركون المؤمنين مثليهم عند اشتداد القتال فداخلهم الرعب؛ فهما مرحلتان مختلفتان لا تعارض بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص608–609، تحت «توفيق بين ﴿ويقللكم في أعينهم﴾ وبين ﴿يرونهم مثليهم﴾»","url":""}]},{"id":"s8-191","number":191,"surah":8,"verses":[45],"references":[{"surah":8,"verses":[45]}],"verseLabel":"الأنفال: 45","question":"لماذا جمع بين الثبات وكثرة ذكر الله عند لقاء العدو؟","answer":"الثبات عمل الجوارح، وذكر الله قوة القلب؛ فجمعهما لأن ثبات الموقف لا يدوم إلا باستمداد اليقين والعون من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص231، تحت «مناسبة العطف في جملة الجزاء»","url":""}]},{"id":"s8-192","number":192,"surah":8,"verses":[45],"references":[{"surah":8,"verses":[45]}],"verseLabel":"الأنفال: 45","question":"ما سرّ التعبير في قوله تعالى: ﴿اذكروا الله كثيرًا﴾ في أشد مواطن الانشغال؟","answer":"في شدة القتال يكثر الاضطراب والغفلة؛ فأُمروا بكثرة الذكر ليظل القلب متعلقًا بالله، مستمدًا منه الثبات والنصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص231، تحت عنوان «دلالة تنكير لفظ ﴿كثيرًا﴾»","url":""}]},{"id":"s8-193","number":193,"surah":8,"verses":[46,47],"references":[{"surah":8,"verses":[46,47]}],"verseLabel":"الأنفال: 46–47","question":"لماذا أعاد الأمر بالطاعة ثم نهى عن التنازع؟","answer":"أعيدت الطاعة هنا في أحكام مواجهة العدو، ثم خُص التنازع بالنهي لأنه أقرب أسباب الفشل وذهاب القوة في هذا الموطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص238، تحت عنوان «مناسبة عطف النهي عن المنازعة على الأمر بالطاعة»","url":""}]},{"id":"s8-194","number":194,"surah":8,"verses":[46,47],"references":[{"surah":8,"verses":[46,47]}],"verseLabel":"الأنفال: 46–47","question":"ما الصورة في ﴿فتفشلوا وتذهب ريحكم﴾؟","answer":"تصور الريح القوة والغلبة والهيبة لما فيها من نفاذ واندفاع؛ فذهابها صورة لزوال شوكة الجماعة. وقد ذكر المصدر في التعبير الاستعارة والكناية، وربط الصورة بالتنازع الذي يبدد القوة ويوقع الفشل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص241، تحت عنوان «بلاغة العطف في جملتي الجزاء»","url":""}]},{"id":"s8-195","number":195,"surah":8,"verses":[46,47],"references":[{"surah":8,"verses":[46,47]}],"verseLabel":"الأنفال: 46–47","question":"ما وجه البلاغة في التشبيه في قوله ﴿ولا تكونوا كالذين﴾؟","answer":"جمع الوصف علل خروج المشركين: البطر الذي يحمل على الطغيان، والرياء الذي يطلب منزلة الناس، والصد الذي يقاوم سبيل الله؛ وهو نقيض إخلاص المؤمنين وثباتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص247، تحت عنوان «بلاغة التشبيه في قوله ﴿ولا تكونوا كالذين﴾»","url":""}]},{"id":"s8-196","number":196,"surah":8,"verses":[46,47],"references":[{"surah":8,"verses":[46,47]}],"verseLabel":"الأنفال: 46–47","question":"ما مناسبة الختم بـ﴿والله بما يعملون محيط﴾؟","answer":"الإحاطة أوسع من العلم المجرد؛ فهي تصور أن أعمالهم لا يفوت منها شيء قدرةً وعلمًا وجزاءً، فناسبت تهديد الخارجين بطرًا ورياءً وصدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص254، تحت عنوان «بلاغة قوله ﴿والله بما يعملون محيط﴾ بين التصريح والكناية»","url":""}]},{"id":"s8-197","number":197,"surah":8,"verses":[48],"references":[{"surah":8,"verses":[48]}],"verseLabel":"الأنفال: 48","question":"ما دلالة قول الشيطان: ﴿لا غالب لكم اليوم من الناس﴾؟","answer":"نفى وجود أي غالب لهم من جنس الناس ليطمئنهم ويغريهم بالإقدام على القتال. فجمع نفي الجنس والتقييد باليوم والناس في وعد زائف بالنصر، ثم كشف مشهد المعركة بطلان هذا التغرير.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص264، تحت عنوان «دلالة من في قوله ﴿من الناس﴾»","url":""}]},{"id":"s8-198","number":198,"surah":8,"verses":[48],"references":[{"surah":8,"verses":[48]}],"verseLabel":"الأنفال: 48","question":"ما الصورة في ﴿فلما تراءت الفئتان نكص على عقبيه﴾؟","answer":"﴿نكص على عقبيه﴾ يصور رجوعًا سريعًا مذعورًا إلى الخلف بعد التقدم، فكأن حركته انقلبت على أثر رؤية الملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص268، تحت عنوان «فائدة ذكر قوله ﴿على عقبيه﴾»","url":""}]},{"id":"s8-199","number":199,"surah":8,"verses":[48],"references":[{"surah":8,"verses":[48]}],"verseLabel":"الأنفال: 48","question":"ما مناسبة التعبير بالاسم الموصول وصلته في قوله تعالى: ﴿إني أرى ما لا ترون﴾؟","answer":"أبهم ما يراه تهويلًا له؛ والمراد ما عاينه من الملائكة وأسباب التأييد التي لم يرها المشركون، فاتخذها ذريعة للتبرؤ والهرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص271، تحت عنوان «مناسبة التعبير بالاسم الموصول وصلته»","url":""}]},{"id":"s8-200","number":200,"surah":8,"verses":[49],"references":[{"surah":8,"verses":[49]}],"verseLabel":"الأنفال: 49","question":"لماذا وصف المنافقون المؤمنين بقولهم: ﴿غر هؤلاء دينهم﴾؟","answer":"نسبوا إقدام المؤمنين إلى غرور الدين لأنهم قاسوا الموقف بالعدد والعدة، ولم يدركوا حقيقة التوكل ووعد الله؛ فكشف قولهم مرض قلوبهم وقصور نظرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص281، تحت عنوان «دلالة قوله ﴿ومن يتوكل على الله﴾»","url":""}]},{"id":"s8-201","number":201,"surah":8,"verses":[49],"references":[{"surah":8,"verses":[49]}],"verseLabel":"الأنفال: 49","question":"لماذا عقب بقوله: ﴿ومن يتوكل على الله فإن الله عزيز حكيم﴾؟","answer":"جاءت الجملة ردًا على زعم المنافقين أن الدين غر المؤمنين؛ فبيّنت أن اعتمادهم ليس غرورًا، بل توكل على عزيز لا يُغلب وحكيم يضع النصر في موضعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص284، تحت عنوان «مناسبة مجيء وصفي ﴿عزيز حكيم﴾ في الآية»","url":""}]},{"id":"s8-202","number":202,"surah":8,"verses":[50,51],"references":[{"surah":8,"verses":[50,51]}],"verseLabel":"الأنفال: 50–51","question":"ما دلالة ذكر الوجوه والأدبار بين الكناية والمجاز المرسل في قوله تعالى: ﴿يضربون وجوههم وأدبارهم﴾؟","answer":"جمع الوجه والدبر كناية عن استيعاب الضرب والإهانة، أو مجاز مرسل يذكر الطرفين ويريد الجسد كله. فتجتمع الصورة على إحاطة العذاب بهم وشدة التنكيل، فلا يختص الألم بجهة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص293، تحت «ذكر الوجوه والأدبار بين الكناية والمجاز المرسل»","url":""}]},{"id":"s8-203","number":203,"surah":8,"verses":[50,51],"references":[{"surah":8,"verses":[50,51]}],"verseLabel":"الأنفال: 50–51","question":"ما دلالة قول الملائكة: ﴿وذوقوا عذاب الحريق﴾؟","answer":"قول الملائكة ﴿ذوقوا﴾ توبيخ وتهديد يصور مباشرة العذاب وإحساسهم به، و﴿الحريق﴾ يخص عذاب النار الشديد الذي ينتظرهم بعد عذاب النزع.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص295، تحت عنوان «مناسبة التعبير بقوله ﴿وذوقوا عذاب الحريق﴾»","url":""}]},{"id":"s8-204","number":204,"surah":8,"verses":[50,51],"references":[{"surah":8,"verses":[50,51]}],"verseLabel":"الأنفال: 50–51","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك بما قدمت أيديكم﴾ مع أن الذنوب تصدر عن جوارح متعددة؟","answer":"نُسب التقديم إلى الأيدي لأنها أكثر الجوارح مباشرة للأعمال واكتسابًا لها، فغلبت في التعبير عن كل ما قدمه الإنسان من ذنوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص296، تحت عنوان «دلالة الباء في قوله ﴿ذلك بما قدمت أيديكم﴾»","url":""}]},{"id":"s8-205","number":205,"surah":8,"verses":[50,51],"references":[{"surah":8,"verses":[50,51]}],"verseLabel":"الأنفال: 50–51","question":"لماذا نفى الظلم بصيغة المبالغة: ﴿ليس بظلام للعبيد﴾؟","answer":"من وجوه التعبير أن المبالغة تراعي كثرة العبيد؛ فنفي الظلم موزع على كل واحد منهم، فلا يظلم أحدًا. ويذكر المصدر أيضًا أن ﴿ظلام﴾ قد تحمل على النسبة، أي ليس بذي ظلم؛ فالمقصود نفي أصل الظلم، لا نفي كثرته وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص299، تحت «دلالة صيغة فعال في قوله ﴿ليس بظلام للعبيد﴾»","url":""}]},{"id":"s8-207","number":207,"surah":8,"verses":[52,54],"references":[{"surah":8,"verses":[52,54]}],"verseLabel":"الأنفال: 52؛ الأنفال: 52، 54","question":"ما سرّ التعبير في قوله تعالى في الأولى: ﴿فأخذهم الله بذنوبهم﴾، وفي الثانية: ﴿فأهلكناهم بذنوبهم﴾؟","answer":"الأخذ يصور القبض عليهم بقوة بحيث لا يفلتون، و﴿بذنوبهم﴾ تبين سبب العقوبة. وهو أعم من الإهلاك؛ فجاء ﴿فأهلكناهم﴾ في الموضع الثاني ليصرح بنهاية ذلك الأخذ، ثم بيّن إغراق آل فرعون صورةً مخصوصة من الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص328، تحت عنوان «وجه إيثار لفظ الإهلاك دون الأخذ»","url":""}]},{"id":"s8-208","number":208,"surah":8,"verses":[52,54],"references":[{"surah":8,"verses":[52,54]}],"verseLabel":"الأنفال: 52، 54","question":"ما سرّ اختلاف التعبير بين قوله تعالى أولًا: ﴿كفروا بآيات الله﴾، وقوله بعد آيتين: ﴿كذبوا بآيات ربهم﴾؟","answer":"جاء ﴿كفروا بآيات الله﴾ في سياق تظهر فيه قدرة الله وتسخيره الملائكة، فناسب اسم الجلالة. أما ﴿كذبوا بآيات ربهم﴾ فجاءت بعد ذكر النعمة وتغييرها، فناسب وصف الرب المنعم؛ وفيه تقبيح تكذيبهم بآيات من رباهم وأحسن إليهم. والتكذيب صورة أخص من الكفر، فكل تعبير ملائم لما قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص327، تحت عنوان «سر إيثار وصف الربوبية»","url":""}]},{"id":"s8-210","number":210,"surah":8,"verses":[53],"references":[{"surah":8,"verses":[53]}],"verseLabel":"الأنفال: 53","question":"ما سرّ اختلاف التعبير بين قوله تعالى في الأنفال: ﴿ذلك بأن الله لم يك مغيرًا نعمة أنعمها على قوم حتى يغيروا ما بأنفسهم﴾، وقوله تعالى في الرعد: ﴿إن الله لا يغير ما بقوم حتى يغيروا ما بأنفسهم﴾؟","answer":"صرحت آية الأنفال بالنعمة السابقة ﴿نعمة أنعمها﴾، وعبرت بنفي الكون واسم الفاعل ﴿لم يك مغيرًا﴾ لتقرير ثبوت هذه السنة: لا تسلب النعمة قبل تغيير أهلها ما بأنفسهم. وجاءت آية الرعد بلفظ ﴿ما بقوم﴾ وبالمضارع المنفي لتقرير استمرار السنة وعموم الأحوال التي يتناولها اللفظ؛ ويفسر المصدر حالهم هنا بالنعمة والعافية أيضًا، فلا يصح جعل الفرق أن الرعد مخصوصة بتغيير الشر إلى الخير. و﴿يك﴾ فعل مضارع مجزوم بـ﴿لم﴾، وليس فعلًا ماضيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص316، تحت عنوان «نكتة التعبير عن التغيير باسم الفاعل»","url":""}]},{"id":"s8-211","number":211,"surah":8,"verses":[53],"references":[{"surah":8,"verses":[53]}],"verseLabel":"الأنفال: 53","question":"لماذا حذف النون من ﴿يك﴾؟","answer":"حذفت نون ﴿يكن﴾ للتخفيف مع الجزم وسكون النون. ويذكر المصدر لطيفة تناسب هذا الإيجاز، وهي تأكيد تنزيه الله عن أدنى تغيير لنعمة أنعمها قبل أن يغير أهلها ما بأنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص314، تحت «بلاغة الحذف للتخفيف في لفظ ﴿يك﴾»","url":""}]},{"id":"s8-213","number":213,"surah":8,"verses":[54],"references":[{"surah":8,"verses":[54]}],"verseLabel":"الأنفال: 54","question":"لماذا كرر تشبيههم بآل فرعون بعد وروده في الآية 52؟","answer":"للتشبيه جهتان: الأول يشبههم بآل فرعون في الكفر وما استتبعه من الأخذ بالذنوب؛ والثاني يأتي بعد بيان سنة تغيير النعمة، فيشبههم بهم في زوال النعمة والإهلاك بسبب تغيير ما بأنفسهم. فإعادة التشبيه تقرر معنى جديدًا في سياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص323–324، تحت «بلاغة التشبيه في السياق»","url":""}]},{"id":"s8-214","number":214,"surah":8,"verses":[54],"references":[{"surah":8,"verses":[54]}],"verseLabel":"الأنفال: 54","question":"ما الغرض البلاغي من التنكير في لفظ ﴿وكل﴾؟","answer":"التنوين في ﴿كل﴾ عوض عن المضاف إليه؛ أي كل من مشركي بدر وآل فرعون ومن قبلهم، و﴿كانوا ظالمين﴾ تجمعهم في علة الهلاك مع اختلاف صوره.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص332، تحت عنوان «غرض التنكير في لفظ ﴿وكل﴾»","url":""}]},{"id":"s8-215","number":215,"surah":8,"verses":[54],"references":[{"surah":8,"verses":[54]}],"verseLabel":"الأنفال: 54","question":"لماذا زاد في الموضع الثاني: ﴿وأغرقنا آل فرعون﴾، ولم يذكر الإغراق في الموضع الأول؟","answer":"الموضع الأول أجمل الأخذ بذنوبهم، أما الثاني فمقام تفصيل الهلاك؛ لذلك زاد إغراق آل فرعون ليعرض صورة مخصوصة من سنة العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص328، تحت عنوان «وجه إيثار لفظ الإهلاك دون الأخذ»","url":""}]},{"id":"s8-216","number":216,"surah":8,"verses":[55],"references":[{"surah":8,"verses":[55]}],"verseLabel":"الأنفال: 55","question":"لماذا أعاد وصفهم بـ﴿شر الدواب﴾ كما في الآية 22؟","answer":"الأولى فيمن عطل السمع والعقل عمومًا، والثانية في ناقضي العهود خاصة؛ فتكرر وصف ﴿شر الدواب﴾ لأن الصنفين أبطلا خصائص الإنسان، مع تخصيص كل سياق بجرمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص340–341، تحت «بلاغة التشابه اللفظي بين آيتي الأنفال»","url":""}]},{"id":"s8-217","number":217,"surah":8,"verses":[55],"references":[{"surah":8,"verses":[55]}],"verseLabel":"الأنفال: 55","question":"لماذا ختم بـ﴿فهم لا يؤمنون﴾ بالمضارع؟","answer":"المضارع ﴿لا يؤمنون﴾ يدل على استمرار انتفاء الإيمان وتجدد أسبابه فيهم، لا على موقف ماضٍ انقضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص340، تحت «دلالة صوغ الإيمان المنفي مضارعًا»","url":""}]},{"id":"s8-218","number":218,"surah":8,"verses":[56],"references":[{"surah":8,"verses":[56]}],"verseLabel":"الأنفال: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿الذين عاهدت منهم﴾ بـ«من»؟","answer":"من أوجه توجيه ﴿من﴾ أن ﴿عاهدت﴾ ضُمّن معنى أخذ العهد؛ أي عاهدتهم آخذًا منهم التزامهم. فالمعاهدة تتضمن إعطاء العهد وأخذه من الجانبين، ويبرز الحرف ما التزموه ثم نقضوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص345، تحت عنوان «دلالة من في قوله ﴿منهم﴾»","url":""}]},{"id":"s8-219","number":219,"surah":8,"verses":[56],"references":[{"surah":8,"verses":[56]}],"verseLabel":"الأنفال: 56","question":"ما وجه البلاغة في التعبير بجملة ﴿في كل مرة﴾؟","answer":"﴿في كل مرة﴾ تكشف أن النقض عادة متكررة عقب تجديد العهد، لا زلة واحدة، ولذلك استحقوا تشديد المعاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص347، تحت عنوان «بلاغة التعبير بجملة ﴿في كل مرة﴾»","url":""}]},{"id":"s8-220","number":220,"surah":8,"verses":[57],"references":[{"surah":8,"verses":[57]}],"verseLabel":"الأنفال: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿فإما تثقفنهم في الحرب﴾، دون أن يقال: تجدهم؟","answer":"الثقف هنا الظفر بهم والتمكن منهم مع الحذق؛ فهو أخص من مجرد العثور أو المصادفة، لأن من يصادف عدوه قد يغلبه وقد لا يغلبه. فناسب اللفظ ما بعده من القدرة على التشريد بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص353، تحت عنوان «بديع إيثار لفظ ﴿تثقفنهم﴾ على تصادفهم»","url":""}]},{"id":"s8-221","number":221,"surah":8,"verses":[57],"references":[{"surah":8,"verses":[57]}],"verseLabel":"الأنفال: 57","question":"ما الصورة في ﴿فشرد بهم من خلفهم﴾؟","answer":"المعنى: أوقع بهم من النكال ما يفرق ويخيف من وراءهم؛ فجعلهم وسيلة لتشريد غيرهم وردع كل من يفكر في النقض.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص354، تحت عنوان «بلاغة الكناية أو التضمين في فعل التشريد»","url":""}]},{"id":"s8-222","number":222,"surah":8,"verses":[58],"references":[{"surah":8,"verses":[58]}],"verseLabel":"الأنفال: 58","question":"ما وجه البلاغة في الاستعارة في فعل الأمر ﴿فانبذ﴾؟","answer":"النبذ إلقاء العهد وطرحه إليهم علنًا، و﴿على سواء﴾ تعني استواء الطرفين في العلم بانتهائه؛ فلا يبدأ قتال مع بقاء توهم الأمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص361، تحت عنوان «بلاغة الاستعارة في فعل الأمر ﴿فانبذ﴾»","url":""}]},{"id":"s8-223","number":223,"surah":8,"verses":[58],"references":[{"surah":8,"verses":[58]}],"verseLabel":"الأنفال: 58","question":"لماذا ختم بـ﴿إن الله لا يحب الخائنين﴾؟","answer":"الخاتمة تعلل وجوب إعلان نبذ العهد؛ فمباغتة المعاهدين من غير إعلام خيانة، والله لا يحب الخائنين ولو كانت الخيانة مع عدو.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص362، تحت عنوان «بلاغة الاستئناف البياني في جملة الفاصلة»","url":""}]},{"id":"s8-224","number":224,"surah":8,"verses":[59],"references":[{"surah":8,"verses":[59]}],"verseLabel":"الأنفال: 59","question":"ما دلالة النهي عن الحسبان في قوله تعالى: ﴿ولا يحسبن الذين كفروا سبقوا﴾؟","answer":"على قراءة الياء يجوز أن يكون ﴿الذين كفروا﴾ فاعلًا؛ أي لا يظنوا أنفسهم قد أفلتوا. وعلى قراءة التاء يكون الخطاب للنبي ﷺ: لا تحسبن الذين كفروا قد سبقوا. والسبق مستعار للإفلات من العقوبة، والمقصود إبطال ظن النجاة من قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص369، تحت عنوان «دلالة النهي عن الحسبان»","url":""}]},{"id":"s8-225","number":225,"surah":8,"verses":[59],"references":[{"surah":8,"verses":[59]}],"verseLabel":"الأنفال: 59","question":"لماذا ختم بـ﴿إنهم لا يعجزون﴾؟","answer":"﴿لا يعجزون﴾ تقطع توهم سبقهم؛ فهم لا يفوتون قدرة الله ولا يمنعونه من إدراكهم وإن أفلتوا مؤقتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص370، تحت عنوان «بلاغة التعبير بالمضارع وحذف مفعول ﴿يعجزون﴾»","url":""}]},{"id":"s8-226","number":226,"surah":8,"verses":[60],"references":[{"surah":8,"verses":[60]}],"verseLabel":"الأنفال: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿وأعدوا لهم ما استطعتم من قوة﴾، فأجمل القوة؟","answer":"أُجملت القوة لتشمل كل ما تتجدد به القدرة على الردع والقتال في كل عصر، وقُيدت بـ﴿ما استطعتم﴾ لربط التكليف بالطاقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص375، تحت عنوان «بلاغة تنكير لفظ قوة»","url":""}]},{"id":"s8-227","number":227,"surah":8,"verses":[60],"references":[{"surah":8,"verses":[60]}],"verseLabel":"الأنفال: 60","question":"لماذا خصّ ﴿رباط الخيل﴾ بعد عموم القوة؟","answer":"ذُكر رباط الخيل بعد عموم القوة لعظم أثره في زمن التنزيل وظهور منزلته في الاستعداد السريع والحراسة والقتال؛ فهو تخصيص لأبرز أفراد العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص378، تحت عنوان «سر تخصيص الخيل بالذكر في سياق القرآن الكريم»","url":""}]},{"id":"s8-228","number":228,"surah":8,"verses":[60],"references":[{"surah":8,"verses":[60]}],"verseLabel":"الأنفال: 60","question":"ما دلالة ﴿ترهبون به﴾ في بيان غاية إعداد القوة؟","answer":"تبين أن ظهور القوة يوقع الخوف في العدو، فيردعه عن الإقدام على قتال المسلمين أو إيذائهم، ويحد من الخيانة والعدوان. فالإعداد له أثر في ردع العدو قبل مباشرة القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص379، تحت «توجيه القراءات في قوله ﴿ترهبون﴾»","url":""}]},{"id":"s8-229","number":229,"surah":8,"verses":[60],"references":[{"surah":8,"verses":[60]}],"verseLabel":"الأنفال: 60","question":"ما فائدة التعبير بشبه الجملة ﴿من دونهم﴾؟","answer":"أبهم الآخرون لأنهم خفيون على المؤمنين أو لم يدخلوا في دائرة معرفتهم، ثم قابل جهلهم بعلم الله المحيط ليبين أن الإعداد يردع العدو المعروف والمجهول.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص380، تحت عنوان «فائدة التعبير بشبه الجملة ﴿من دونهم﴾»","url":""}]},{"id":"s8-230","number":230,"surah":8,"verses":[60,61],"references":[{"surah":8,"verses":[60,61]}],"verseLabel":"الأنفال: 60–61","question":"كيف يأمر القرآن بإعداد القوة لإرهاب العدو، ثم يأمر في الآية التالية مباشرة بقبول السلم إذا جنحوا له؟","answer":"الإعداد يحفظ قوة المؤمنين واستعدادهم، ثم بيّن النظم حكم ميل العدو إلى الصلح: يقبل إذا كان فيه مصلحة للمسلمين. فجمع السياق إعداد القوة وقبول السلم بحسب حال كل منهما، مع التوكل على الله وعدم إلغاء الصلح لمجرد احتمال الخداع.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص387، تحت عنوان «بلاغة المشاكلة في التعبير بالجنوح عن قبول المصالحة»","url":""}]},{"id":"s8-231","number":231,"surah":8,"verses":[61],"references":[{"surah":8,"verses":[61]}],"verseLabel":"الأنفال: 61","question":"لماذا عبّر عن طلب السلم بالجنوح؟","answer":"الجنوح هو الميل، فتصور الكلمة انتقالهم الظاهر من جانب الحرب إلى جانب الصلح، وتعديتها للسلم تكشف جهة هذا الميل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص387، تحت عنوان «إيثار لفظ الجنوح ووجه تعديته وتضمينه»","url":""}]},{"id":"s8-287","number":287,"surah":8,"verses":[61],"references":[{"surah":8,"verses":[61]}],"verseLabel":"الأنفال: 61","question":"ما بلاغة تكرار الجنوح في قوله: ﴿وإن جنحوا للسلم فاجنح لها﴾؟","answer":"كرر الفعل للمشاكلة: إن مالوا إلى السلم فمل إليها، فجاء الجواب موازيًا لفعلهم ومناسبًا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص387، تحت عنوان «بلاغة المشاكلة في التعبير بالجنوح عن قبول المصالحة»","url":""}]},{"id":"s8-232","number":232,"surah":8,"verses":[61],"references":[{"surah":8,"verses":[61]}],"verseLabel":"الأنفال: 61","question":"لماذا أُنّث الضمير في ﴿فاجنح لها﴾؟","answer":"أُنث الضمير لأنه يعود إلى ﴿السلم﴾ باعتبار معنى المسالمة أو المصالحة المؤنث، وهي لغة فصيحة في اللفظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص388، تحت «بلاغة الاستعارة»","url":""}]},{"id":"s8-233","number":233,"surah":8,"verses":[61],"references":[{"surah":8,"verses":[61]}],"verseLabel":"الأنفال: 61","question":"لماذا ختم بـ﴿إنه هو السميع العليم﴾؟","answer":"﴿السميع﴾ يناسب ما يعلنونه من عرض السلم وما يدار من قول، و﴿العليم﴾ يحيط بما يخفونه من صدق أو خداع؛ وضمير الفصل يقوي انفراده بكمال الصفتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص389، تحت عنوان «بلاغة التذييل في نهاية سياق الآية الجليل»","url":""}]},{"id":"s8-234","number":234,"surah":8,"verses":[62,63],"references":[{"surah":8,"verses":[62,63]}],"verseLabel":"الأنفال: 62–63","question":"ما مناسبة الآيتين لما قبلهما في قوله تعالى: ﴿وإن يريدوا أن يخدعوك فإن حسبك الله﴾؟","answer":"جواب احتمال الخداع لم يكن رفض السلم، بل ﴿فإن حسبك الله﴾؛ أي الله كافيك شرهم، فاقبل الظاهر وتوكل على من يعلم الباطن ويحفظك.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص396، تحت عنوان «مناسبة الآيتين لما قبلهما»","url":""}]},{"id":"s8-235","number":235,"surah":8,"verses":[62,63],"references":[{"surah":8,"verses":[62,63]}],"verseLabel":"الأنفال: 62–63","question":"لماذا جمع بين التأييد بالنصر وبالمؤمنين؟","answer":"جمع بين التأييد بالنصر الخارق للعادة، كإمداد الملائكة، والتأييد بالمؤمنين الذين ينصرونه بالأسباب المعهودة. وإعادة الباء تبرز نوعي التأييد؛ وكلاهما من فضل الله وتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص402–403، تحت «غرض إعادة حرف الجر على المعطوف»","url":""}]},{"id":"s8-236","number":236,"surah":8,"verses":[62,63],"references":[{"surah":8,"verses":[62,63]}],"verseLabel":"الأنفال: 62–63","question":"ما سرّ التعبير في قوله تعالى: ﴿وألف بين قلوبهم﴾، دون أن يقال: جمعهم؟","answer":"التأليف إيجاد الألفة والمحبة بعد التفرق والعداوة، وهو أعمق من جمع الأجساد في مكان واحد؛ إذ يتعلق بوحدة القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص404، تحت «دلالة استعمال مفردة ﴿وألف﴾»","url":""}]},{"id":"s8-237","number":237,"surah":8,"verses":[62,63],"references":[{"surah":8,"verses":[62,63]}],"verseLabel":"الأنفال: 62–63","question":"ما سرّ التعبير بلو دون غيرها من أدوات الشرط في قوله تعالى: ﴿لو أنفقت ما في الأرض جميعًا ما ألفت بين قلوبهم﴾؟","answer":"الشرط يصور عجز كل مال الأرض عن صنع الألفة الحقيقية بين قلوب متعادية، فيظهر أن اجتماعهم آية من تدبير الله لا ثمرة شراء أو مصلحة عارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص406، تحت عنوان «سر التعبير بلو دون غيرها من أدوات الشرط»","url":""}]},{"id":"s8-238","number":238,"surah":8,"verses":[64,65,66],"references":[{"surah":8,"verses":[64,65,66]}],"verseLabel":"الأنفال: 64–66","question":"ما سرّ استعمال مفردة الاتباع في قوله تعالى: ﴿يا أيها النبي حسبك الله ومن اتبعك﴾؟","answer":"المعنى أن الله كافيك وكافي من اتبعك من المؤمنين، أو أن الله والمؤمنين حسبك على جهة أن الله أصل الكفاية وهم من أسبابها؛ والسياق يثبت للنبي ﷺ الطمأنينة بالجماعة المؤمنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص418، تحت عنوان «سر استعمال مفردة الاتباع»","url":""}]},{"id":"s8-239","number":239,"surah":8,"verses":[64,65,66],"references":[{"surah":8,"verses":[64,65,66]}],"verseLabel":"الأنفال: 64–66","question":"ما سرّ التعبير في قوله تعالى: ﴿حرض المؤمنين على القتال﴾ لا «أمرهم»؟","answer":"التحريض حث بالغ يوقظ الهمة ويقوي الدافع إلى الفعل، مع التنبيه إلى خطر تركه. فناسب مقام القتال الذي يحتاج إلى ترغيب وإقناع يزيلان التردد ويقيان الجماعة عاقبة التفريط.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص420–421، تحت «سر اختيار مفردة ﴿حرض﴾»","url":""}]},{"id":"s8-240","number":240,"surah":8,"verses":[64,65,66],"references":[{"surah":8,"verses":[64,65,66]}],"verseLabel":"الأنفال: 64–66","question":"لماذا وصف الحكم الثاني بأنه تخفيف؟","answer":"لأن التكليف الأول ألزم الصابرين بالثبات أمام عشرة أمثالهم، ثم رحمهم الله فجعل الواجب الثبات أمام المثلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص427، تحت عنوان «نكتة التعبير بالتخفيف»","url":""}]},{"id":"s8-288","number":288,"surah":8,"verses":[64,65,66],"references":[{"surah":8,"verses":[64,65,66]}],"verseLabel":"الأنفال: 64–66","question":"ما سرّ التعبير بمفردة ضعفًا في قوله تعالى: ﴿وعلم أن فيكم ضعفًا﴾؟","answer":"يبين الضعف علة التخفيف ومراعاة طاقتهم، ولا يعني أن علم الله بضعفهم حدث بعد خفاء؛ فعلمه محيط بهم من قبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص429، تحت عنوان «سر التعبير بمفردة ضعفًا»","url":""}]},{"id":"s8-241","number":241,"surah":8,"verses":[64,65,66],"references":[{"surah":8,"verses":[64,65,66]}],"verseLabel":"الأنفال: 64–66","question":"لماذا علل تفوق المؤمنين بأن الكافرين ﴿قوم لا يفقهون﴾؟","answer":"الفقه فهم نافذ يقدّر حقائق الأمور وعواقبها؛ والكافرون يقاتلون بلا بصيرة بالغاية ولا رجاء فيما عند الله، أما المؤمن فيضاعف فهمه وصبره قوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص436، تحت عنوان «الفقه والعلم»","url":""}]},{"id":"s8-242","number":242,"surah":8,"verses":[67,68,69],"references":[{"surah":8,"verses":[67,68,69]}],"verseLabel":"الأنفال: 67–69","question":"ما الغرض البلاغي من تنكير كلمة نبي في قوله تعالى: ﴿ما كان لنبي أن يكون له أسرى حتى يثخن في الأرض﴾؟","answer":"صيغة ﴿ما كان لنبي﴾ تنفي ملاءمة اتخاذ الأسرى قبل الإثخان لسنة النبوة؛ لأن تثبيت سلطان الحق وكسر قوة العدو مقدم في بداية المواجهة على منفعة الفداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص444، تحت عنوان «غرض تنكير كلمة نبي»","url":""}]},{"id":"s8-243","number":243,"surah":8,"verses":[67,68,69],"references":[{"surah":8,"verses":[67,68,69]}],"verseLabel":"الأنفال: 67–69","question":"لماذا قابل ﴿عرض الدنيا﴾ بـ﴿والله يريد الآخرة﴾؟","answer":"﴿عرض الدنيا﴾ شيء زائل قريب يُنال من الفداء، وقوبل بالآخرة الباقية التي يريد الله لهم ثوابها وإعزاز الدين الموصل إليها؛ فظهر تفاوت الإرادتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص447، تحت عنوان «سر التعبير بعرض الدنيا عن المال»","url":""}]},{"id":"s8-244","number":244,"surah":8,"verses":[67,68,69],"references":[{"surah":8,"verses":[67,68,69]}],"verseLabel":"الأنفال: 67–69","question":"ما فائدة الأمر في قوله: ﴿فكلوا مما غنمتم﴾؟","answer":"يؤكد الأمر حل الغنيمة ويزيل ما بقي في نفوسهم من التحرج بعد العتاب السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص453، تحت عنوان «غرض الأمر وفائدته»","url":""}]},{"id":"s8-289","number":289,"surah":8,"verses":[67,68,69],"references":[{"surah":8,"verses":[67,68,69]}],"verseLabel":"الأنفال: 67–69","question":"لماذا وصف الغنيمة بأنها ﴿حلالًا طيبًا﴾؟","answer":"يزيد وصفها بالطيب طمأنتهم إلى نقاء الانتفاع بها، مع بقائه منضبطًا بتقوى الله وحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص454، تحت عنوان «فائدة وصف الحال بالطيب»","url":""}]},{"id":"s8-245","number":245,"surah":8,"verses":[67],"references":[{"surah":8,"verses":[67]}],"verseLabel":"الأنفال: 67","question":"كيف يُجمع بين قوله تعالى في الأنفال: ﴿ما كان لنبي أن يكون له أسرى حتى يثخن في الأرض﴾، وقوله في سورة محمد: ﴿فإما منًّا بعد وإما فداء﴾؟","answer":"تلتقي الآيتان على تقديم الإثخان على الأسر والفداء؛ فالأنفال تنهى عن اتخاذ الأسرى قبل الإثخان، وآية محمد نفسها تقول: ﴿حتى إذا أثخنتموهم فشدوا الوثاق فإما منًّا بعد وإما فداء﴾. فذكر المن والفداء متعلق بما بعد الإثخان وإحكام الأسر، فلا تعارض بين ترتيب المرحلتين في الآيتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص439، تحت عنوان «شرح المفردات»","url":""}]},{"id":"s8-246","number":246,"surah":8,"verses":[70],"references":[{"surah":8,"verses":[70]}],"verseLabel":"الأنفال: 70","question":"لماذا وُجّه خطاب الأسرى بواسطة النبي ﷺ؟","answer":"في توجيه القول إلى النبي ﷺ تشريف له وتثبيت لوظيفته في تبليغ الأسرى وعد الله وفتح باب الرجاء لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص463، تحت عنوان «سر خطاب الأسرى بواسطة النبي الأكرم»","url":""}]},{"id":"s8-290","number":290,"surah":8,"verses":[70],"references":[{"surah":8,"verses":[70]}],"verseLabel":"الأنفال: 70","question":"ما الصورة في قوله: ﴿لمن في أيديكم من الأسرى﴾؟","answer":"تصور العبارة تمكن المسلمين من الأسرى وإحاطتهم بهم كأنهم في أيديهم، مع أن باب الخير والمغفرة ما زال مفتوحًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص464، تحت عنوان «براعة الاستعارة في جعل الأسرى في أيديهم»","url":""}]},{"id":"s8-247","number":247,"surah":8,"verses":[70],"references":[{"surah":8,"verses":[70]}],"verseLabel":"الأنفال: 70","question":"هل يفيد قوله: ﴿إن يعلم الله في قلوبكم خيرًا﴾ شكًا في علم الله؟","answer":"لا؛ فالشرط متعلق بتحقق الخير في قلوب الأسرى، لا بعلم الله المحيط بهم، فكأن الوعد معلق بصدق تحولهم هم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص467، تحت عنوان «دلالة عبارة ﴿إن يعلم الله﴾»","url":""}]},{"id":"s8-291","number":291,"surah":8,"verses":[70],"references":[{"surah":8,"verses":[70]}],"verseLabel":"الأنفال: 70","question":"لماذا عبّر عن الإيمان بالخير في قوله: ﴿في قلوبكم خيرًا﴾؟","answer":"لأن صدق الإيمان أصل الخير الذي تتفرع عنه النية الصالحة والعمل، فجمعه اللفظ الواسع من مبدئه في القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص469، تحت عنوان «سر التعبير بلفظ الخير عن الإيمان»","url":""}]},{"id":"s8-292","number":292,"surah":8,"verses":[70],"references":[{"surah":8,"verses":[70]}],"verseLabel":"الأنفال: 70","question":"ما دلالة تكرار ﴿خيرًا﴾ في الآية؟","answer":"قابل خير القلوب بخير الجزاء، ووعدهم عوضًا يفوق ما أُخذ منهم ويشمل خير الدنيا وثواب الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص470، تحت عنوان «دلالة تكرار لفظ خيرًا»","url":""}]},{"id":"s8-248","number":248,"surah":8,"verses":[70],"references":[{"surah":8,"verses":[70]}],"verseLabel":"الأنفال: 70","question":"لماذا جمع بين التعويض والمغفرة؟","answer":"التعويض يجبر خسارة الدنيا، والمغفرة تزيل تبعة الماضي وتحقق خير الآخرة؛ فجمع لهم النفع العاجل والنجاة الآجلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص473، تحت عنوان «سر اختيار المغفرة في ﴿ويغفر لكم﴾»","url":""}]},{"id":"s8-249","number":249,"surah":8,"verses":[71],"references":[{"surah":8,"verses":[71]}],"verseLabel":"الأنفال: 71","question":"ما دلالة تذكير الأسرى بخيانتهم لله من قبل؟","answer":"يذكرهم بأن كفرهم ونقضهم للعهد كانا سببًا في هزيمتهم، ويحذرهم من تكرار الخيانة بعد فتح باب الخير لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص482، تحت عنوان «دلالة الإخبار بخيانتهم لله»","url":""}]},{"id":"s8-293","number":293,"surah":8,"verses":[71],"references":[{"surah":8,"verses":[71]}],"verseLabel":"الأنفال: 71","question":"لماذا قال: ﴿فأمكن منهم﴾ ولم يقل على المقابلة: «فخانهم»؟","answer":"لأن الخيانة وصف نقص لا ينسب إلى الله؛ فعبر عن جزائهم العادل بتمكين المؤمنين منهم، وهو قدرة وعدل لا خيانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص483، تحت عنوان «نكتة العدول في ﴿فأمكن منهم﴾»","url":""}]},{"id":"s8-250","number":250,"surah":8,"verses":[71],"references":[{"surah":8,"verses":[71]}],"verseLabel":"الأنفال: 71","question":"لماذا حذف مفعول ﴿فأمكن منهم﴾؟","answer":"حذف مفعول ﴿أمكن﴾ للإيجاز، لأن سياق الكلام يدل عليه؛ والتقدير: فأمكنكم الله منهم، أي جعلهم تحت قدرتكم. فالعمدة في الحذف ظهور المفعول من المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص484، تحت «دلالة من في ﴿فأمكن منهم﴾»","url":""}]},{"id":"s8-252","number":252,"surah":8,"verses":[72],"references":[{"surah":8,"verses":[72]}],"verseLabel":"الأنفال: 72","question":"ما دلالة ترتيب الإيمان ثم الهجرة ثم الجهاد؟","answer":"بدأ بأصل الاعتقاد، ثم أتبعَه بمفارقة موطن الكفر ونصرة الجماعة، ثم ببذل الوسع في حمايتها؛ فترقى من الأصل إلى آثاره العملية.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص494، تحت عنوان «بلاغة ترتيب الصفات الإيمان والهجرة والجهاد»","url":""}]},{"id":"s8-294","number":294,"surah":8,"verses":[72],"references":[{"surah":8,"verses":[72]}],"verseLabel":"الأنفال: 72","question":"لماذا قُدّم الجهاد بالمال على الجهاد بالنفس؟","answer":"لأن بذل المال أوسع وقوعًا وأكثر استمرارًا، وبه تجهز النفوس وأسباب القتال، ثم ذُكر بذل النفس وهو غاية التضحية.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص496، تحت عنوان «نكتة تقديم المال على النفس»","url":""}]},{"id":"s8-253","number":253,"surah":8,"verses":[72],"references":[{"surah":8,"verses":[72]}],"verseLabel":"الأنفال: 72","question":"ما سرّ التعبير بالولاية من بعضهم لبعض في قوله تعالى: ﴿أولئك بعضهم أولياء بعض﴾؟","answer":"﴿بعضهم أولياء بعض﴾ تقرر ولاية متبادلة بين المهاجرين والأنصار تشمل النصرة والتعاون وما كان من أحكام الجماعة، فجعلتهم كتلة متكافلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص502، تحت «سر التعبير بالولاية من بعضهم لبعض»","url":""}]},{"id":"s8-254","number":254,"surah":8,"verses":[72],"references":[{"surah":8,"verses":[72]}],"verseLabel":"الأنفال: 72","question":"لماذا نفى الولاية عن المؤمنين الذين لم يهاجروا مع بقاء إيمانهم؟","answer":"فرّق السياق بين تمام الولاية المرتبط بالهجرة وبين أصل الإيمان الذي أثبته لهم. ومن تفسير الولاية المنفية هنا التوارث والأحكام الخاصة بجماعة المهاجرين والأنصار، وليست نفيًا لكل نصرة دينية؛ إذ قال بعدها: ﴿وإن استنصروكم في الدين فعليكم النصر﴾. وجعل الهجرة غاية لهذا النفي وحثّهم عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص504، تحت عنوان «دلالة نفي الولاية»","url":""}]},{"id":"s8-255","number":255,"surah":8,"verses":[72],"references":[{"surah":8,"verses":[72]}],"verseLabel":"الأنفال: 72","question":"لماذا استثنى النصرة عند وجود ميثاق مع قوم آخرين؟","answer":"استثنى القوم الذين بينهم وبين المسلمين ميثاقًا لوجوب الوفاء بالعهد؛ فلا تنقض المعاهدة استجابة لطلب النصرة. وجاء ختام الآية تذكيرًا برقابة الله على الوفاء بمواثيقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص510، تحت عنوان «بلاغة التذييل في آخر الآية الكريمة»","url":""}]},{"id":"s8-256","number":256,"surah":8,"verses":[72],"references":[{"surah":8,"verses":[72]},{"surah":9,"verses":[20]}],"verseLabel":"الأنفال: 72؛ التوبة: 20","question":"ما سرّ التعبير في قوله تعالى في التوبة: ﴿وجاهدوا في سبيل الله بأموالهم وأنفسهم﴾، بينما قدم في الأنفال: ﴿بأموالهم وأنفسهم في سبيل الله﴾؟","answer":"من توجيه ذلك أن الأنفال سبق فيها ذكر الفداء والغنيمة و﴿عرض الدنيا﴾، فناسب تقديم ﴿بأموالهم وأنفسهم﴾ في وصف بذلهم. أما التوبة فسبق فيها ذكر الجهاد في سبيل الله، فناسب تقديمه. ويذكر المصدر أيضًا أن سياق الأنفال يعظم تضحية المهاجرين بأموالهم وأنفسهم، بينما سياق التوبة يقارن الجهاد بالسقاية وعمارة المسجد الحرام، فاختير لكل مقام ما يبرز فضله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص498–499، تحت «توجيه التشابه اللفظي في هذه الآية قيد التفسير»","url":""}]},{"id":"s8-257","number":257,"surah":8,"verses":[72,74,75],"references":[{"surah":8,"verses":[72,74,75]}],"verseLabel":"الأنفال: 72؛ الأنفال: 74–75","question":"لماذا حُذف قيدا المال والنفس بعد أن ذُكرا أولًا؟","answer":"اكتفى الموضع اللاحق بما سبق تفصيله؛ فصار إطلاق الجهاد حاملًا معنى البذل بالمال والنفس من غير حاجة إلى تكرارهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص526، تحت عنوان «سر حذف ذكر المال والنفس»","url":""}]},{"id":"s8-295","number":295,"surah":8,"verses":[72,74,75],"references":[{"surah":8,"verses":[72,74,75]}],"verseLabel":"الأنفال: 72؛ الأنفال: 74–75","question":"ما دلالة معكم في قوله تعالى: ﴿وجاهدوا معكم﴾؟","answer":"تفيد المعية إلحاق المتأخرين بالسابقين ومشاركتهم الفعلية في جهاد الجماعة، لا مجرد ادعاء الانتساب إليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص539، تحت عنوان «دلالة معكم»","url":""}]},{"id":"s8-258","number":258,"surah":8,"verses":[73],"references":[{"surah":8,"verses":[73]}],"verseLabel":"الأنفال: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿والذين كفروا بعضهم أولياء بعض﴾ في مقابلة ولاية المؤمنين؟","answer":"كما يتناصر المؤمنون، يتناصر الكافرون بحكم اجتماعهم على الكفر والمصلحة؛ فالمقابلة تحذر المؤمنين من ترك ولايتهم التي تحفظ جماعتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص514، تحت عنوان «دلالة الواو في الجملة المبدوءة بالموصول»","url":""}]},{"id":"s8-259","number":259,"surah":8,"verses":[73],"references":[{"surah":8,"verses":[73]}],"verseLabel":"الأنفال: 73","question":"لماذا أبهم الفعل في قوله: ﴿إلا تفعلوه﴾؟","answer":"يتسع الفعل المبهم لمجموع ما تقدم من أحكام الولاية والنصرة والوفاء، فيحذر من تعطيل هذا النظام كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص516، تحت عنوان «سر التعبير بقوله إلا تفعلوه»","url":""}]},{"id":"s8-296","number":296,"surah":8,"verses":[73],"references":[{"surah":8,"verses":[73]}],"verseLabel":"الأنفال: 73","question":"إلى ماذا يعود الضمير في قوله: ﴿إلا تفعلوه﴾؟","answer":"يحتمل أن يعود إلى النصرة أو حفظ الميثاق أو مجموع أحكام الولاية المتقدمة، وتتسع العبارة لهذه المعاني المتكاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص516، تحت عنوان «تعدد مرجع الضمير في سياق الآية»","url":""}]},{"id":"s8-297","number":297,"surah":8,"verses":[73],"references":[{"surah":8,"verses":[73]}],"verseLabel":"الأنفال: 73","question":"لماذا سُمّيت عاقبة ترك الولاية والنصرة فتنة؟","answer":"لأن ترك المؤمنين بلا نصرة يعرضهم للاضطهاد والاضطراب، ويفتن الناس عن دينهم، ثم يفضي إلى فساد واسع في الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص517، تحت عنوان «سر اختيار التعبير بالفتنة»","url":""}]},{"id":"s8-260","number":260,"surah":8,"verses":[74],"references":[{"surah":8,"verses":[74]}],"verseLabel":"الأنفال: 74","question":"لماذا أعاد وصف المهاجرين والأنصار ثم قال: ﴿أولئك هم المؤمنون حقًا﴾؟","answer":"أعيد وصفهم بعد تفصيل أحكام الولاية تثبيتًا لفضل الهجرة والنصرة والجهاد، ثم أكد بـ﴿أولئك هم المؤمنون حقًا﴾ أن أعمالهم حققت دعوى الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص528، تحت عنوان «نفي التكرار بين الآيات قيد التفسير»","url":""}]},{"id":"s8-261","number":261,"surah":8,"verses":[74],"references":[{"surah":8,"verses":[74]}],"verseLabel":"الأنفال: 74","question":"لماذا قُدمت المغفرة على الرزق الكريم؟","answer":"لأن المغفرة تزيل تبعة التقصير أولًا، ثم يأتي الرزق الكريم تتميمًا للنعمة بعد صفاء الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص533، تحت عنوان «سر تقديم المغفرة على الرزق الكريم»","url":""}]},{"id":"s8-298","number":298,"surah":8,"verses":[74],"references":[{"surah":8,"verses":[74]}],"verseLabel":"الأنفال: 74","question":"لماذا ذُكرت الدرجات في أول السورة ولم تُذكر هنا مع المغفرة والرزق الكريم؟","answer":"زاد الموضع الأول الدرجات لأنه يعدد مراتب صفات الإيمان، أما هنا فالمقام للشهادة بصدق الهجرة والجهاد والإيواء والنصرة، فناسبه الوعد بالمغفرة والرزق.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص533، تحت عنوان «سر اختلاف فاصلة هذه الآية عن سابقتها»","url":""}]},{"id":"s8-262","number":262,"surah":8,"verses":[75],"references":[{"surah":8,"verses":[75]}],"verseLabel":"الأنفال: 75","question":"لماذا أُلحق المتأخرون في الهجرة بقوله: ﴿فأولئك منكم﴾؟","answer":"تقرر ﴿منكم﴾ دخول من تأخر ثم هاجر وجاهد في جماعة السابقين وولايتهم وأحكامهم. وفي التعبير تشريف لهم وإلحاق بالمتقدمين، مع بقاء فضل السبق؛ فالمشاركة في الولاية لا تستلزم تساوي المراتب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص540، تحت عنوان «دلالة من في قوله منكم»","url":""}]},{"id":"s8-263","number":263,"surah":8,"verses":[75],"references":[{"surah":8,"verses":[75]}],"verseLabel":"الأنفال: 75","question":"ما سرّ تقديم أولو الأرحام في الحكم بعد تقرير أخوة الإيمان؟","answer":"أخوة الإيمان أصل الولاية والنصرة، أما أولو الأرحام فأولى في الحكم الخاص بالميراث وسائر الحقوق التي خصها الشرع بالقرابة؛ فلا تعارض لاختلاف المجال.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص541، تحت عنوان «سر التعبير بصيغة التفضيل أولى»","url":""}]},{"id":"s8-264","number":264,"surah":8,"verses":[75],"references":[{"surah":8,"verses":[75]}],"verseLabel":"الأنفال: 75","question":"ما سرّ تقييد أولوية أولي الأرحام في كتاب الله في قوله تعالى: ﴿في كتاب الله﴾؟","answer":"﴿في كتاب الله﴾ تثبت أن أولوية الأرحام حكم مكتوب مقرر في شرع الله وعلمه، لا ترتيبًا ناشئًا من عرف الناس أو مصالحهم المؤقتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص542، تحت عنوان «سر تقييد أولوية أولي الأرحام في كتاب الله»","url":""}]},{"id":"s8-265","number":265,"surah":8,"verses":[75],"references":[{"surah":8,"verses":[75]}],"verseLabel":"الأنفال: 75","question":"لماذا ختمت السورة بـ﴿إن الله بكل شيء عليم﴾؟","answer":"خُتمت السورة بالعلم المحيط لأنه أساس دقة أحكام الأنفال والعهود والولاية والمواريث؛ فالله يعلم المصالح والنيات والصلات، ويضع لكل منها حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص544، تحت عنوان «براعة ختم السورة»","url":""}]},{"id":"s8-299","number":299,"surah":8,"verses":[24],"references":[{"surah":8,"verses":[24]}],"verseLabel":"الأنفال: 24","question":"ما سر التعبير بالحَوْل في قوله: ﴿واعلموا أن الله يحول بين المرء وقلبه﴾؟","answer":"من معاني «الحول» في اللغة الحجز والمنع، ومنها التحوّل والتغيّر. والتعبير هنا يدل على شدة قرب الله من عبده وتمكّنه من قلبه، فهو يحجز بينه وبين قلبه ويصرّفه كيف يشاء، فينبغي للعبد أن يبادر إلى الاستجابة قبل أن يُحال بينه وبين قلبه.","sources":[{"label":"فاضل السامرائي، برنامج «لمسات بيانية»، منقول في صفحة «لمسات ومتشابهات وأسباب النزول لسورة الأنفال»: https://engyfoda.com/blog/?page_id=2290 ؛ وانظر في معنى الحول: فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص21.","url":""}]},{"id":"s8-300","number":300,"surah":8,"verses":[45],"references":[{"surah":8,"verses":[45]}],"verseLabel":"الأنفال: 45","question":"ما دلالة حذف الموصوف في قوله: ﴿واذكروا الله كثيرًا﴾؟","answer":"ذُكر الموصوف في مواضع أخرى مثل ﴿ذكرًا كثيرًا﴾ لأن السياق فيها سياق الذكر نفسه. أما في الأنفال فالسياق في لقاء العدو والثبات في القتال، فحذف الموصوف ولم يؤكد بالمصدر، لأن الموضع ليس للحديث عن الذكر نفسه.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص101–102.","url":""}]},{"id":"s8-301","number":301,"surah":8,"verses":[50],"references":[{"surah":8,"verses":[50]}],"verseLabel":"الأنفال: 50","question":"ما سر تذكير الفعل في قوله: ﴿إذ يتوفى الذين كفروا الملائكة﴾ وتأنيثه في سورة محمد: ﴿فكيف إذا توفتهم الملائكة﴾؟","answer":"يرى السامرائي أن الفعل يُذكّر مع الملائكة حين يكون الموقف أشد، ويؤنث فيما دونه. وآية الأنفال في قتلى بدر من الكفار، وفيها ضرب الوجوه والأدبار وذوق عذاب الحريق، فهو موقف أشد، فذكّر الفعل.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص190.","url":""}]},{"id":"s8-302","number":302,"surah":8,"verses":[13],"references":[{"surah":8,"verses":[13]}],"verseLabel":"الأنفال: 13","question":"ما دلالة فك الإدغام في قوله: ﴿ومن يُشاقِقِ اللهَ ورسولَه﴾؟","answer":"فكّ الإدغام هنا لأنه ذُكر الرسول مع الله، فالمشاقة وقعت في أمرين، فناسب إظهار المثلين وإطالة اللفظ. أما في الحشر ﴿ومن يُشاقِّ الله﴾ فاقتصر على ذكر الله فأدغم.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص14.","url":""}]},{"id":"s8-303","number":303,"surah":8,"verses":[15,16],"references":[{"surah":8,"verses":[15,16]}],"verseLabel":"الأنفال: 15–16","question":"ما الفرق بين ﴿الأدبار﴾ في قوله: ﴿فلا تولوهم الأدبار﴾ و﴿إدبار﴾ في قوله: ﴿وإدبار النجوم﴾؟","answer":"﴿الأدبار﴾ بفتح الهمزة جمع «دُبُر» وهو الخلف، فتولية الأدبار أن يجعل المقاتل ظهره للعدو فرارًا. أما «الإدبار» بكسرها فمصدر الفعل «أدبر» كالإقبال من «أقبل»، والنجوم لا أدبار لها، وإنما هي تُدبر أي تغيب.","sources":[{"label":"فاضل السامرائي، برنامج «لمسات بيانية»، منقول في صفحة «لمسات ومتشابهات وأسباب النزول لسورة الأنفال»:","url":"https://engyfoda.com/blog/?page_id=2290"}]},{"id":"s8-304","number":304,"surah":8,"verses":[32],"references":[{"surah":8,"verses":[32]}],"verseLabel":"الأنفال: 32","question":"ما سر الدعاء بـ«اللهم» وحدها دون لفظ «الرب» في قوله: ﴿اللهم إن كان هذا هو الحق من عندك فأمطر علينا حجارة﴾؟","answer":"يلاحظ السامرائي أن الدعاء في القرآن ورد كثيرًا مع لفظ «الرب»، ولم يرد مع «اللهم» وحدها إلا في هذه الآية. والسبب أنه دعاء بالعذاب على أنفسهم، فلا يناسبه ذكر الرب الذي هو المربي المتولي أمرهم والقيّم عليهم ورازقهم.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص71–72.","url":""}]},{"id":"s8-305","number":305,"surah":8,"verses":[39],"references":[{"surah":8,"verses":[39]}],"verseLabel":"الأنفال: 39","question":"ما سر ختم الآية بقوله: ﴿فإن الله بما يعملون بصير﴾ وختم نظيرتها في البقرة بقوله: ﴿فإن الله غفور رحيم﴾؟","answer":"كل خاتمة مناسبة لسياقها. فآية البقرة في كفار مكة، والدعوة فيها إلى الكفّ عن الشرك والقتال، فناسبها ذكر المغفرة والرحمة ترغيبًا. أما آية الأنفال فعامة، وناسبها التذكير بأن الله بصير بأعمالهم يجازيهم عليها.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص18.","url":""}]},{"id":"s8-306","number":306,"surah":8,"verses":[50],"references":[{"surah":8,"verses":[50]}],"verseLabel":"الأنفال: 50","question":"ما سر حذف جواب «لو» في قوله: ﴿ولو ترى إذ يتوفى الذين كفروا الملائكة يضربون وجوههم وأدبارهم﴾؟","answer":"حُذف الجواب للتعظيم والتهويل، فلم يقل: لرأيت أمرًا فظيعًا، بل ترك الجواب ليذهب الذهن في تصوّر هول المشهد كل مذهب، وهذا أبلغ من ذكره. ولهذا الحذف نظائر في القرآن، منها في سبأ.","sources":[{"label":"فاضل السامرائي، برنامج «لمسات بيانية»، منقول في صفحة «لمسات ومتشابهات وأسباب النزول لسورة الأنفال»:","url":"https://engyfoda.com/blog/?page_id=2290"}]},{"id":"s8-307","number":307,"surah":8,"verses":[51],"references":[{"surah":8,"verses":[51]}],"verseLabel":"الأنفال: 51","question":"ما دلالة التعبير بالتقديم في قوله: ﴿ذلك بما قدمت أيديكم﴾ دون «بما كسبت أيديكم»؟","answer":"التقديم إرسال الشيء إلى الأمام وتقديمه لما بعدُ، أما الكسب فجمعٌ وتحصيلٌ لنفسك. والآية في مشهد توفي الكافرين وضرب الملائكة لهم، فناسب أن يُذكر لهم أن هذا الجزاء هو ما قدّموه لأنفسهم من أعمال فوجدوه أمامهم.","sources":[{"label":"فاضل السامرائي، برنامج «لمسات بيانية»، منقول في صفحة «لمسات ومتشابهات وأسباب النزول لسورة الأنفال»:","url":"https://engyfoda.com/blog/?page_id=2290"}]},{"id":"s8-308","number":308,"surah":8,"verses":[52],"references":[{"surah":8,"verses":[52]}],"verseLabel":"الأنفال: 52","question":"ما سر زيادة وصف القوة في قوله: ﴿إن الله قوي شديد العقاب﴾، وقد قال في آل عمران: ﴿والله شديد العقاب﴾؟","answer":"آية آل عمران قالت: ﴿كذبوا بآياتنا﴾، وآية الأنفال قالت: ﴿كفروا بآيات الله﴾، والكفر أعم وأشد من التكذيب. ثم إن سياق الأنفال سياق قتال ونصر في بدر، والنصر يحتاج إلى القوة، فزاد وصف ﴿قوي﴾.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص26–27؛ ومن أسرار البيان القرآني، ص25.","url":""}]},{"id":"s8-309","number":309,"surah":8,"verses":[52,54],"references":[{"surah":8,"verses":[52,54]}],"verseLabel":"الأنفال: 52، 54","question":"ما سر تكرار ﴿كدأب آل فرعون﴾، واختلاف العقوبة بين ﴿فأخذهم الله بذنوبهم﴾ و﴿فأهلكناهم بذنوبهم وأغرقنا آل فرعون﴾؟","answer":"الدأب الأول تشبيه لهم في الكفر نفسه، والثاني تشبيه لهم في تغيير النعم، بدليل ما قبله: ﴿ذلك بأن الله لم يك مغيرًا نعمة أنعمها على قوم حتى يغيروا ما بأنفسهم﴾. وفي تفسير هذا التغيير ينقل السامرائي كلام «البحر المحيط» و«الكشاف». وجعل عقوبة الكفر عامة وهي الأخذ بالذنوب في الدنيا والآخرة، وعقوبة التكذيب، وهو نوع من الكفر، خاصة وهي الإهلاك والإغراق.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص78–81.","url":""}]},{"id":"s8-310","number":310,"surah":8,"verses":[58],"references":[{"surah":8,"verses":[58]}],"verseLabel":"الأنفال: 58","question":"ما سر التعبير باسم الفاعل في قوله: ﴿إن الله لا يحب الخائنين﴾ دون صيغة المبالغة «الخوّانين»؟","answer":"الآية لم تذكر أنهم خانوا، بل قالت: ﴿وإما تخافن من قوم خيانة﴾، أي خِيفت منهم الخيانة ولم تقع، فجاء باسم الفاعل. أما في النساء فقال: ﴿لا يحب من كان خوّانًا أثيمًا﴾ بالمبالغة، لأنه ذكر وقوع خيانتهم وتكرارها وما يفضحها من صفاتهم.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص32.","url":""}]},{"id":"s8-311","number":311,"surah":8,"verses":[61],"references":[{"surah":8,"verses":[61]}],"verseLabel":"الأنفال: 61","question":"ما سر تقديم السمع على العلم في قوله: ﴿إنه هو السميع العليم﴾؟","answer":"ينقل السامرائي عن «بدائع الفوائد» و«البرهان» أن الخبر يتضمن التخويف والتهديد، فبدأ بالسمع لتعلقه بما يقرب كالأصوات وهمس الحركات، وذكر السميع أوقع في التخويف. ويضيف من عنده أن السمع من وسائل العلم فهو يسبقه.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص57.","url":""}]},{"id":"s9-1","number":1,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"لماذا بدأت سورة التوبة من غير بسملة، بخلاف سائر سور القرآن؟","answer":"يذكر المؤلف في تفسير اسم «القرينة» خبرًا عن عثمان يربط ترك البسملة بقرن الأنفال والتوبة معًا في المصحف. فهذا الوجه يربط تلك الخصوصية باقتران السورتين وترتيبهما في المصحف.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص548–550، تحت «أسماؤها المذكورة وسبب تسميتها: القرينة»","url":""}]},{"id":"s9-2","number":2,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"ما براعة افتتاح السورة بالمصدر: ﴿براءة﴾؟","answer":"جعل المصدر قطع العهد عنوانًا للسورة وأول ما يقرع السمع، فبدأ الحكم بقوة ووضوح قبل تفصيل أسبابه وآثاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص562، تحت عنوان «براعة الاستهلال بالمصدر براءة»","url":""}]},{"id":"s9-697","number":697,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"ما دلالة تنكير كلمة ﴿براءة﴾؟","answer":"يفيد التنكير التفخيم: إنها براءة عظيمة الشأن تترتب عليها أحكام عامة في العهود والمواقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص563، تحت عنوان «دلالة التنكير في براءة»","url":""}]},{"id":"s9-3","number":3,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿براءة﴾، دون أن يقال: «تبرؤ» أو «نقض عهد»؟","answer":"البراءة خلاص وانفصال مما يوجب الضرر أو الالتزام؛ فاختيرت لتعلن رفع تبعة العهد وقطع رابطته بعد ما وقع من نقضه. ويبين اللفظ أن المقصود فسخ المعاهدة والإذن بزوال التزامها، لا مجرد انقضائها الطبيعي بانتهاء الأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص562، تحت عنوان «براعة الاستهلال بالمصدر براءة»","url":""}]},{"id":"s9-4","number":4,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"ما موقع ﴿براءة﴾ من الإعراب، وما أثر افتتاح السورة بالجملة الاسمية؟","answer":"يجوز أن تكون خبرًا لمبتدأ محذوف، أي هذه براءة، أو مبتدأ تخصص بوصفه وخبره متعلق بما بعده. والجملة الاسمية تقرر ثبوت البراءة وتحققها عند الله، مع إفادة أمر المخاطبين بإجرائها؛ فاجتمع تثبيت الحكم ومعنى الإنشاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص562، تحت عنوان «دلالة الافتتاح بالجملة الاسمية»","url":""}]},{"id":"s9-5","number":5,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"لماذا نُسبت البراءة إلى الله ورسوله في ﴿براءة من الله ورسوله﴾؟","answer":"لأن الله هو الذي حكم بالبراءة وأذن فيها، والرسول ﷺ يبلغ حكمه ويباشر تنفيذه. فنسبت إليهما مع اختلاف الجهة: تشريع وإذن من الله، وتبليغ وإجراء من رسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص565، تحت عنوان «معنى العطف بين الله ورسوله»","url":""}]},{"id":"s9-6","number":6,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿من الله ورسوله﴾، ولم يكرر حرف الجر فيقول: «من الله ومن رسوله»؟","answer":"جمعهما حرف جر واحد لأن البراءة الصادرة حكم واحد، ولإظهار اتصال تبليغ الرسول بأمر الله، مع بقاء الله مصدر الحكم ورسوله مبلغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص566، تحت «دلالة عدم تكرار من مع الرسول»","url":""}]},{"id":"s9-7","number":7,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"لماذا اختير حرف الابتداء ﴿من﴾ في ﴿براءة من الله﴾؟","answer":"﴿من﴾ لابتداء الغاية؛ أي إن منشأ هذا الحكم ومصدر صدوره من عند الله ورسوله، فليست البراءة رأيًا بشريًا أو تصرفًا منفردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص564، تحت «دلالة تعدية المصدر بالحرف»","url":""}]},{"id":"s9-8","number":8,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"لماذا عُبر عن المعاهدة بالماضي: ﴿عاهدتم﴾؟","answer":"الماضي ﴿عاهدتم﴾ يقرر وقوع العهد وثبوته قبل إعلان البراءة، فيبني الحكم على عقد سبق وجوده لا على احتمال مستقبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص568، تحت «نكتة التعبير بالماضي في عاهدتم»","url":""}]},{"id":"s9-9","number":9,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿عاهدتم من المشركين﴾، فأدخل ﴿من﴾ على المشركين؟","answer":"﴿من﴾ بيانية تبين صنف المعاهدين؛ لأن العهد قد يكون مع أهل الكتاب أو غيرهم، فجاء ﴿من المشركين﴾ ليزيل هذا الاحتمال ويحدد المقصود. ثم تبين الآيات التالية حكم من بقي منهم وفيًا بعهده.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص568، تحت «دلالة من»","url":""}]},{"id":"s9-10","number":10,"surah":9,"verses":[1],"references":[{"surah":9,"verses":[1]}],"verseLabel":"التوبة: 1","question":"لماذا نسب المعاهدة إلى المسلمين: ﴿عاهدتم﴾، مع أن النبي ﷺ هو الذي عقدها؟","answer":"أسندت المعاهدة إلى المؤمنين لأنهم طرفها الملزم بمراعاتها وتنفيذ حكمها، وإن تولى الرسول ﷺ عقدها. وفي الإسناد تشريف لهم بوفائهم، وتنبيه إلى أن الإخلال جاء من الجهة الأخرى وأنهم أهل خطاب التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص568، تحت «دلالة إسناد فعل المعاهدة في عاهدتم»","url":""}]},{"id":"s9-11","number":11,"surah":9,"verses":[2],"references":[{"surah":9,"verses":[2]}],"verseLabel":"التوبة: 2","question":"ما الذي أفاده قوله تعالى ﴿فسيحوا في الأرض أربعة أشهر﴾؟","answer":"أفاد تمكينهم من السير آمنين في الأرض خلال مهلة محددة قبل انتهاء الأمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص571، تحت عنوان «اصطفاء لفظ فسيحوا»","url":""}]},{"id":"s9-12","number":12,"surah":9,"verses":[2],"references":[{"surah":9,"verses":[2]}],"verseLabel":"التوبة: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿فسيحوا﴾، دون أن يقال: «فسيروا» أو «اذهبوا»؟","answer":"السياحة هي السير الممتد في سعة وأمن وتصرّف، فناسبت المهلة الممنوحة لهم، وهي أوسع دلالة من مجرد الذهاب أو السير.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص571، تحت عنوان «اصطفاء لفظ فسيحوا»","url":""}]},{"id":"s9-13","number":13,"surah":9,"verses":[2],"references":[{"surah":9,"verses":[2]}],"verseLabel":"التوبة: 2","question":"لماذا قيد السياحة بقوله: ﴿في الأرض﴾؟","answer":"يفيد القيد تعميم الإذن بالسير الآمن في جهات الأرض خلال المهلة. كما يحدد المقصود بالسياحة هنا بأنه السير في الأرض، لأن لفظ السياحة قد يستعمل في غيره؛ ولا يمنع ذلك ما يذكره المصدر من أصلها التصويري المشبه بجريان الماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص572–573، تحت «دلالة التقييد في الأرض»","url":""}]},{"id":"s9-14","number":14,"surah":9,"verses":[2],"references":[{"surah":9,"verses":[2]}],"verseLabel":"التوبة: 2","question":"ما الحكمة من منحهم مهلة في قوله: ﴿فسيحوا في الأرض أربعة أشهر﴾؟","answer":"أعطتهم المهلة أمانًا وفرصة للنظر في أمرهم قبل انتهاء العهد، ليعلموا ما سيؤول إليه موقفهم ويختاروا على بينة. وتحديد المدة يبين أن الإمهال مضبوط بأجل، فيتحقق الإنذار دون مباغتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص570، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-15","number":15,"surah":9,"verses":[2],"references":[{"surah":9,"verses":[2]}],"verseLabel":"التوبة: 2","question":"ما أثر ذكر ﴿أربعة أشهر﴾ بعد قوله: ﴿في الأرض﴾؟","answer":"أتبع القيد المكاني بقيد زماني ليضبط مهلة البراءة من جهتي المكان والزمان؛ فالإذن بالسياحة ليس مطلق المدة، بل ينتهي عند أجل معلوم. وفي هذا البيان إظهار عدل الحكم وإزالة ما قد يلتبس في حدود الأمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص573، تحت «فائدة التقييد بالظرف أربعة أشهر»","url":""}]},{"id":"s9-16","number":16,"surah":9,"verses":[2],"references":[{"surah":9,"verses":[2]}],"verseLabel":"التوبة: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿واعلموا أنكم غير معجزي الله﴾، دون أن يقال: «لن تعجزوا الله»؟","answer":"يجمع التركيب نفي الإعجاز وتثبيت ذلك في حقهم، وجاء اسم الفاعل دالًا على ثبوت عجزهم عن الإفلات في الحال والاستقبال. و﴿غير﴾ تنفي عنهم القدرة على الإعجاز مهما اختلفت أحوالهم؛ فلا يغترون بالإمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص574، تحت عنوان «دلالة غير»","url":""}]},{"id":"s9-17","number":17,"surah":9,"verses":[2],"references":[{"surah":9,"verses":[2]}],"verseLabel":"التوبة: 2","question":"لماذا اختير وصف ﴿غير معجزي الله﴾ بدل «مغلوبون»؟","answer":"﴿غير معجزي الله﴾ ينفي قدرتهم على السبق والإفلات، وهو أدق من «مغلوبون»؛ فقد يتأخر أخذهم لكنهم لا يعجزون الله بحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص574–575، تحت «اصطفاء لفظ معجزين»","url":""}]},{"id":"s9-18","number":18,"surah":9,"verses":[2],"references":[{"surah":9,"verses":[2]}],"verseLabel":"التوبة: 2","question":"لماذا انتقل من خطاب المشركين إلى الغيبة في قوله: ﴿وأن الله مخزي الكافرين﴾؟","answer":"انتقل من مواجهتهم في ﴿أنكم﴾ إلى وصف جنسهم بـ﴿الكافرين﴾؛ ليجعل الخزي سنة عامة في كل من ثبت على الكفر، لا خبرًا خاصًا بالحاضرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص576، تحت عنوان «بلاغة الإظهار في مقام الإضمار وأن الله»","url":""}]},{"id":"s9-19","number":19,"surah":9,"verses":[2],"references":[{"surah":9,"verses":[2]}],"verseLabel":"التوبة: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿مخزي الكافرين﴾ بصيغة اسم الفاعل؟","answer":"اسم الفاعل ﴿مخزي﴾ يفيد ثبوت الخزي وتحققه واستمراره، فكأن وقوعه وصف قائم لا مجرد فعل عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص576، تحت «إيثار التعبير باسم الفاعل»","url":""}]},{"id":"s9-20","number":20,"surah":9,"verses":[2],"references":[{"surah":9,"verses":[2]}],"verseLabel":"التوبة: 2","question":"لماذا وصفهم في الخاتمة بالكافرين بعد تسميتهم أولًا بالمشركين؟","answer":"وصف الشرك أخص، ثم جاء وصف الكفر الأعم ليشمل الوعيد كل من استمر على الكفر. فانتقل السياق من بيان شأن المعاهدين المشركين إلى تعميم التحذير وتقوية سبب الخزي.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص577، تحت «التعبير بوصف الكفر ومجيئه مفعولا للإخزاء»","url":""}]},{"id":"s9-21","number":21,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"لماذا أعاد إعلان البراءة في قوله: ﴿وأذان من الله ورسوله﴾ بعد قوله في الآية الأولى: ﴿براءة من الله ورسوله﴾؟","answer":"البراءة في الآية الأولى نفس الحكم، و﴿أذان﴾ هنا إعلان ذلك الحكم وتبليغه إلى الناس في يوم مشهود؛ فالثانية ليست إعادة للأولى بل إشهار لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص585، تحت عنوان «حكمة التكرار في صيغة البراءة»","url":""}]},{"id":"s9-22","number":22,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿أذان﴾، دون أن يقال: «إعلام»؟","answer":"الأذان إعلام مرتفع يبلغ الأسماع ويشيع، فناسب الإعلان العام في الحج أكثر من لفظ «إعلام» الذي لا يفيد قوة النداء وانتشاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص593، تحت «الأذان والإعلام»","url":""}]},{"id":"s9-23","number":23,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"ما أثر التعبير بالاسم ﴿أذان﴾ بدل الاقتصار على فعل يدل على الإعلام؟","answer":"التعبير بالاسم يثبت الإعلان ويقرره، ويجعل البلاغ أمرًا قائمًا يتناوله الناس، لا حدثًا عابرًا مقيدًا بزمن. والجملة خبرية تتضمن طلب تبليغ هذا الحكم وإشاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص581، تحت عنوان «بلاغة التعبير بالاسمية دون الفعل»","url":""}]},{"id":"s9-24","number":24,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿إلى الناس﴾، مع أن البراءة متعلقة بالمشركين؟","answer":"وُجه الأذان إلى الناس جميعًا لأن أحكام العهود والحج والأمان تمس المجتمع كله، وليشهد المؤمن والمشرك الإعلان فلا تبقى جهالة أو شبهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص581، تحت عنوان «سر التقييد بـإلى الناس»","url":""}]},{"id":"s9-25","number":25,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"لماذا وصف يوم الحج بأنه ﴿الأكبر﴾؟","answer":"من تفسير ﴿يوم الحج الأكبر﴾ أنه يوم النحر لاجتماع أكثر أعمال الحج فيه، وقيل المراد زمن الحج عمومًا. ووصف الحج بالأكبر يميزه من العمرة المسماة الحج الأصغر، ويناسب عموم الاجتماع الذي يبلغ فيه الإعلان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص582–583، تحت «حكمة الوصف في الحج الأكبر»","url":""}]},{"id":"s9-26","number":26,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"لماذا صُرّح باسم الله ورسوله مرة أخرى في ﴿أن الله بريء من المشركين ورسوله﴾؟","answer":"لزيادة البيان في إعلان موجه إلى جمهور متنوع، ولقطع المعاذير، فكان التصريح أوضح من الإضمار.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص587، تحت «نكتة التصريح بفعل البراءة مرة ثانية»","url":""}]},{"id":"s9-27","number":27,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿أن الله بريء من المشركين ورسوله﴾، دون أن يقال: «أن الله ورسوله بريئان»؟","answer":"أثبتت الجملة براءة الله أولًا، ثم براءة رسوله ﷺ على جهة مستقلة في التعبير، فكأن البراءة معلنة من جهتين لتقوية الوعيد وتقريره. ويراعي هذا النظم عموم الإعلان للناس، ويؤكد أن الله ورسوله بريئان من المشركين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص586–587، تحت «علة تأخير لفظ الرسول»","url":""}]},{"id":"s9-28","number":28,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"لماذا رُفع ﴿ورسوله﴾ بعد قوله: ﴿من المشركين﴾، مع احتمال التباس السامع؟","answer":"رُفع ﴿ورسوله﴾ لأنه معطوف على محل اسم الجلالة أو مبتدأ خبره محذوف تقديره «بريء»، فلا يجوز جره عطفًا على المشركين؛ والرفع يمنع المعنى الفاسد عند تمام التركيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص586، تحت «موقع جملة ورسوله مما قبله»","url":""}]},{"id":"s9-29","number":29,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"لماذا جاء بعد إعلان البراءة مباشرة: ﴿فإن تبتم فهو خير لكم﴾؟","answer":"عقب إعلان البراءة ببيان حال التوبة، إظهارًا للرغبة في رجوعهم وفتحًا لباب الخير لهم. فالحكم ليس إغلاقًا لطريق الهداية؛ بل إن تابوا من الشرك كان ذلك خيرًا لهم، ورحمهم الله وغفر لهم ما مضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص587، تحت عنوان «دلالة تبتم»","url":""}]},{"id":"s9-30","number":30,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿فهو خير لكم﴾، ولم يصرح بما في التوبة من النجاة والمغفرة؟","answer":"﴿خير لكم﴾ عبارة جامعة لكل خير التوبة في الدنيا والآخرة، وترك التفصيل يطلق الذهن لاستحضار أنواع النجاة والمغفرة والأمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص588، تحت عنوان «إيثار اصطفاء خير»","url":""}]},{"id":"s9-31","number":31,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"لماذا قابل التوبة بقوله: ﴿وإن توليتم فاعلموا أنكم غير معجزي الله﴾؟","answer":"قوبلت التوبة بالتولي لإظهار الطريقين وعاقبتيهما: الرجوع خير، والإعراض لا يحقق نجاة؛ لأنهم لا يفوتون قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص590، تحت عنوان «دلالة تكرار نفي إعجازهم والفرق بينه وبين السابق قبله»","url":""}]},{"id":"s9-32","number":32,"surah":9,"verses":[3],"references":[{"surah":9,"verses":[3]}],"verseLabel":"التوبة: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿وبشر الذين كفروا بعذاب أليم﴾، واستعمل البشارة في العذاب؟","answer":"من وجوه التعبير استعمال البشارة تهكمًا: ينتظر السامع منها خبرًا سارًا، فإذا الذي يبلغه عذاب أليم، فيشتد التحسر والوعيد. ويذكر المصدر أيضًا وجه حملها على أصل الإخبار بما يظهر أثره على البشرة، خيرًا كان أو شرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص591–592، تحت «دلالة الحقيقة والمجاز في البشارة المذكورة»","url":""}]},{"id":"s9-33","number":33,"surah":9,"verses":[4],"references":[{"surah":9,"verses":[4]}],"verseLabel":"التوبة: 4","question":"لماذا استثنى من البراءة المشركين الذين لم ينقصوا المسلمين شيئًا ولم يظاهروا عليهم أحدًا؟","answer":"استُثني الموفون لأن البراءة من الناقضين لا تبيح خيانة من حفظ عهده؛ فالعدل يوجب إتمام مدته لمن لم ينقص ولم يعن عدوًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص596، تحت عنوان «دلالة مفهوم الوصف بنفي النقص عنهم»","url":""}]},{"id":"s9-34","number":34,"surah":9,"verses":[4],"references":[{"surah":9,"verses":[4]}],"verseLabel":"التوبة: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿لم ينقصوكم شيئًا﴾، ونكّر ﴿شيئًا﴾؟","answer":"﴿شيئًا﴾ في سياق النفي تعم كل نقص، قليلًا أو كثيرًا، فتؤكد كمال وفائهم وعدم إخلالهم بأي حق.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص597، تحت «إيثار كلمة شيئًا وتنكيرها»","url":""}]},{"id":"s9-35","number":35,"surah":9,"verses":[4],"references":[{"surah":9,"verses":[4]}],"verseLabel":"التوبة: 4","question":"لماذا عبّر عن إعانة العدو بقوله: ﴿ولم يظاهروا عليكم أحدًا﴾؟","answer":"المظاهرة المعاونة؛ وأصلها أن يجعل المعين نفسه ظهرًا يقوي صاحبه، فالتعبير يصور اتحادهم مع العدو في القوة والنصرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص597، تحت عنوان «دلالة اشتقاق يظاهروا»","url":""}]},{"id":"s9-36","number":36,"surah":9,"verses":[4],"references":[{"surah":9,"verses":[4]}],"verseLabel":"التوبة: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿فأتموا إليهم عهدهم﴾، دون أن يقال: «فاحفظوا عهدهم»؟","answer":"الإتمام إيصال العهد إلى نهاية مدته كاملًا غير منقوص، وهو أدق من «الحفظ» الذي قد يدل على مجرد عدم النقض دون استيفاء الأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص599، تحت عنوان «دلالة حرف الانتهاء إليهم»","url":""}]},{"id":"s9-37","number":37,"surah":9,"verses":[4],"references":[{"surah":9,"verses":[4]}],"verseLabel":"التوبة: 4","question":"لماذا أضاف العهد إليهم: ﴿عهدهم﴾، مع أنه عهد بين طرفين؟","answer":"إضافة العهد إليهم تذكّر بأنهم حفظوه والتزموا حدوده، فاستحقوا أن يتم لهم. وفيها إبراز لحقهم في الوفاء، مع أن العهد قائم بين الطرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص599، تحت «دلالة الإضافة إلى الضمير»","url":""}]},{"id":"s9-38","number":38,"surah":9,"verses":[4],"references":[{"surah":9,"verses":[4]}],"verseLabel":"التوبة: 4","question":"لماذا ختم الأمر بالوفاء بقوله: ﴿إن الله يحب المتقين﴾؟","answer":"ختم بمحبة المتقين لأن الوفاء للمعاهد المخالف مع القدرة عليه من التقوى؛ فالخاتمة تعلل الإتمام وتجعله طاعة لله لا مجرد مصلحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص601، تحت عنوان «علة الفصل في إن الله يحب المتقين»","url":""}]},{"id":"s9-39","number":39,"surah":9,"verses":[5],"references":[{"surah":9,"verses":[5]}],"verseLabel":"التوبة: 5","question":"لماذا علّق الأمر بقتال المشركين على انسلاخ الأشهر الحرم؟","answer":"عُلّق القتال بانتهاء المهلة صيانة للأمان الذي مُنح لهم، فلا يبدأ الحكم قبل تمام الأجل وبلوغ الإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص603، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-40","number":40,"surah":9,"verses":[5],"references":[{"surah":9,"verses":[5]}],"verseLabel":"التوبة: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿انسلخ الأشهر الحرم﴾، فشبّه الزمن بشيء ينسلخ؟","answer":"استعير الانسلاخ لانقضاء الأشهر وزوال ما فيها من وقاية وأمان، كما ينفصل الجلد عن الجسد. فتبرز الصورة الانتقال من زمن تحميهم فيه المهلة إلى ما بعدها، وتناسب حركة الأحداث والأحكام في السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص605، تحت عنوان «اصطفاء لفظ انسلخ»","url":""}]},{"id":"s9-41","number":41,"surah":9,"verses":[5],"references":[{"surah":9,"verses":[5]}],"verseLabel":"التوبة: 5","question":"لماذا جاءت الأوامر متتابعة: ﴿فاقتلوا... وخذوهم واحصروهم واقعدوا لهم﴾؟","answer":"جمعت الأوامر أنواع الإذن في مواجهة المعنيين بالحكم بعد انقضاء المهلة: القتل والأخذ والحصر والترصد. ولا يلزم جمع هذه الأفعال في كل شخص؛ بل يختلف الإجراء بحسب الإمكان والقدرة والمصلحة، فيشمل النظم صورًا متعددة من المواجهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص608–609، تحت «معنى العطف بالواو»","url":""}]},{"id":"s9-42","number":42,"surah":9,"verses":[5],"references":[{"surah":9,"verses":[5]}],"verseLabel":"التوبة: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿حيث وجدتموهم﴾ مع وجود استثناءات العهود والأمان في السياق؟","answer":"العموم مقيد بالسياق: فهو في المشركين الناقضين بعد انقضاء مهلتهم، لا أهل العهد المستقيم ولا طالب الأمان المذكور في الآية التالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص607، تحت عنوان «دلالة اصطفاء المشركين»","url":""}]},{"id":"s9-43","number":43,"surah":9,"verses":[5],"references":[{"surah":9,"verses":[5]}],"verseLabel":"التوبة: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿وخذوهم﴾ بعد ذكر القتل؟","answer":"ذُكر الأخذ بعد القتل ليشمل الأسر والقبض على من لم يقع عليه القتل؛ فليس الأمر مقصورًا على صورة واحدة من المعاملة الحربية.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص615، تحت عنوان «الأخذ والأسر»","url":""}]},{"id":"s9-44","number":44,"surah":9,"verses":[5],"references":[{"surah":9,"verses":[5]}],"verseLabel":"التوبة: 5","question":"ما الصورة في قوله: ﴿واقعدوا لهم كل مرصد﴾؟","answer":"صوّرهم مترقبين في طرق العدو ومداخله، حتى كأن كل موضع ترصد قد صار مجلسًا ثابتًا لهم يمنع الحركة المعادية.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص609، تحت عنوان «نكتة التعبير بلفظ القعود»","url":""}]},{"id":"s9-45","number":45,"surah":9,"verses":[5],"references":[{"surah":9,"verses":[5]}],"verseLabel":"التوبة: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿كل مرصد﴾، فنصب المرصد، دون أن يقال: «في كل مرصد»؟","answer":"وصل الفعل إلى ﴿كل مرصد﴾ مباشرة على الظرفية، فدل على استغراق مواقع الرصد وأجزائها بحسب القدرة. ويذكر المصدر أن توسيط حرف الجر قد يحتمل الوقوف في موضع من المرصد، فجاء التعبير المباشر أوضح في الاستيعاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص611، تحت «وجه إيصال الفعل للظرف بنفسه»","url":""}]},{"id":"s9-46","number":46,"surah":9,"verses":[5],"references":[{"surah":9,"verses":[5]}],"verseLabel":"التوبة: 5","question":"لماذا فتح باب النجاة بعد هذه الشدة بقوله: ﴿فإن تابوا وأقاموا الصلاة وآتوا الزكاة فخلوا سبيلهم﴾؟","answer":"جعلت التوبة وإقامة الصلاة وإيتاء الزكاة دليلًا ظاهرًا على الدخول في جماعة المسلمين، فيترتب عليها تخلية السبيل ورفع التعرض. فالأوامر السابقة يتغير حكمها في حق من تحقق فيه هذا الشرط.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص611، تحت عنوان «نكتة تعيين الصلاة والزكاة بعد التوبة»","url":""}]},{"id":"s9-47","number":47,"surah":9,"verses":[5],"references":[{"surah":9,"verses":[5]}],"verseLabel":"التوبة: 5","question":"لماذا عبّر عن تركهم بقوله: ﴿فخلوا سبيلهم﴾؟","answer":"تخلية السبيل كناية عن رفع كل تعرض ومنع، كأن طريقهم كان محبوسًا فأطلق؛ وهي أوسع من مجرد «اتركوهم».","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص612، تحت عنوان «اصطفاء لفظ سبيلهم»","url":""}]},{"id":"s9-48","number":48,"surah":9,"verses":[5],"references":[{"surah":9,"verses":[5]}],"verseLabel":"التوبة: 5","question":"لماذا ختمت آية القتال بـ﴿إن الله غفور رحيم﴾؟","answer":"ناسب ﴿غفور رحيم﴾ قبول التوبة بعد الكفر والعداء؛ فالمغفرة تمحو الماضي والرحمة تفتح لهم حياة جديدة بين المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص614، تحت عنوان «تضمن الجملة الخبرية معنى الإنشاء»","url":""}]},{"id":"s9-49","number":49,"surah":9,"verses":[6],"references":[{"surah":9,"verses":[6]}],"verseLabel":"التوبة: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن أحد من المشركين استجارك﴾، فأفرد ﴿أحد﴾ بعد الحكم العام؟","answer":"﴿أحد﴾ تعم من يطلب الأمان، ولا تقتصر على جماعة بأكملها. ويبين المصدر أنها تتناول الفرد والجماعة، وأن التقييد بـ﴿من المشركين﴾ يدخل المستجير من القوم الذين سبق ذكر حكمهم؛ فالحكم العام لا يسقط حق المستجير في الأمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص618–619، تحت «بلاغة التعبير بلفظ أحد»","url":""}]},{"id":"s9-50","number":50,"surah":9,"verses":[6],"references":[{"surah":9,"verses":[6]}],"verseLabel":"التوبة: 6","question":"لماذا تقدّم ﴿أحد﴾ على فعله في قوله: ﴿وإن أحد من المشركين استجارك﴾؟","answer":"تقدم ﴿أحد﴾، مع تقدير فعل يفسره ﴿استجارك﴾، للعناية بذات المستجير. فالمقصود الحرص عليه بإجارته وإسماعه القرآن رجاء هدايته، لا الاقتصار على ذكر فعل الاستجارة مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص619، تحت «سر تقديم المسند إليه أحد»","url":""}]},{"id":"s9-51","number":51,"surah":9,"verses":[6],"references":[{"surah":9,"verses":[6]}],"verseLabel":"التوبة: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿فأجره﴾، ولم يكتف بالنهي عن قتله؟","answer":"﴿فأجره﴾ أمر إيجابي بمنحه الحماية، وهو أبلغ من مجرد عدم قتله؛ إذ يوجب صونه وتمكينه من سماع الحق في أمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص619، تحت عنوان «دلالة أسلوب الخطاب في قوله استجارك»","url":""}]},{"id":"s9-52","number":52,"surah":9,"verses":[6],"references":[{"surah":9,"verses":[6]}],"verseLabel":"التوبة: 6","question":"لماذا جُعلت غاية الأمان أن ﴿يسمع كلام الله﴾؟","answer":"جُعل سماع كلام الله غاية الأمان ليعرف حقيقة الدعوة من مصدرها قبل الحكم عليها، فتقام الحجة في جو خالٍ من الإكراه والخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص623، تحت «وجه جعل سماع كلام الله غاية للإجارة»","url":""}]},{"id":"s9-53","number":53,"surah":9,"verses":[6],"references":[{"surah":9,"verses":[6]}],"verseLabel":"التوبة: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿كلام الله﴾، دون أن يقال: «القرآن»؟","answer":"﴿كلام الله﴾ يبرز مصدر القرآن وشرفه وحجيته؛ فالمستجير لا يسمع كلام بشر بل الوحي الذي دُعي إلى الإيمان به.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص621، تحت «دلالة إضافة الكلام إلى الاسم الجليل»","url":""}]},{"id":"s9-54","number":54,"surah":9,"verses":[6],"references":[{"surah":9,"verses":[6]}],"verseLabel":"التوبة: 6","question":"ما مناسبة قوله تعالى بعد إسماع المستجير القرآن: ﴿ثم أبلغه مأمنه﴾؟","answer":"إبلاغه مأمنه وفاء بالأمان حتى بعد سماع القرآن؛ فلا يترك عرضة للقتل في طريق العودة، سواء آمن أم اختار الانصراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص622، تحت عنوان «معنى ثم في قوله ثم أبلغه مأمنه»","url":""}]},{"id":"s9-55","number":55,"surah":9,"verses":[6],"references":[{"surah":9,"verses":[6]}],"verseLabel":"التوبة: 6","question":"لماذا لم يُلزم المستجير بالإسلام بعد سماع كلام الله؟","answer":"لأن الإجارة تمتد إلى مدة سماع القرآن والنظر فيه، ثم إلى الرجوع الآمن إن لم يسلم. فالأمر بإبلاغه مأمنه يحفظ له الأمان بعد السماع، ويمنع أن تتحول فرصة البيان إلى تعرض له في طريقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص622، تحت عنوان «معنى ثم في قوله ثم أبلغه مأمنه»","url":""}]},{"id":"s9-56","number":56,"surah":9,"verses":[6],"references":[{"surah":9,"verses":[6]}],"verseLabel":"التوبة: 6","question":"لماذا علّل حمايته بقوله: ﴿ذلك بأنهم قوم لا يعلمون﴾؟","answer":"عللت الآية الإجارة وإسماع القرآن وتبليغ المأمن بجهلهم، لإتاحة العلم والبيان لهم قبل اتخاذ موقفهم. وفي التعليل بيان للرفق بهم والعناية بإزالة سبب الجهل، حتى يفهموا ما دُعوا إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص624، تحت عنوان «دلالة الإشارة في ذلك بأنهم وعلة الفصل»","url":""}]},{"id":"s9-57","number":57,"surah":9,"verses":[7],"references":[{"surah":9,"verses":[7]}],"verseLabel":"التوبة: 7","question":"لماذا بدأ بالاستفهام: ﴿كيف يكون للمشركين عهد عند الله وعند رسوله﴾؟","answer":"الاستفهام إنكاري يستبعد ثبوت عهد عام لمن ظهرت خيانتهم، ويمهد لاستثناء من استقام على عهده؛ فلا ينفي كل عهد بلا تفصيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص627، تحت عنوان «بلاغة الاستفهام المجازي»","url":""}]},{"id":"s9-58","number":58,"surah":9,"verses":[7],"references":[{"surah":9,"verses":[7]}],"verseLabel":"التوبة: 7","question":"لماذا كرر ﴿عند﴾ في ﴿عند الله وعند رسوله﴾؟","answer":"يكرر الظرف تقرير الإنكار من كل جهة: لا عهد محفوظ لهم عند الله ولا عند رسوله مع خيانتهم. وفيه تقوية استبعاد بقاء عهد من لا يراعي العهد، وتأكيد صدور البراءة من الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص632–633، تحت «دلالة تكرار الظرف عند»","url":""}]},{"id":"s9-59","number":59,"surah":9,"verses":[7],"references":[{"surah":9,"verses":[7]}],"verseLabel":"التوبة: 7","question":"لماذا استثنى مرة أخرى أهل العهد عند المسجد الحرام؟","answer":"أعيد الاستثناء لأن السياق بعد الإنكار العام يحتاج إلى إخراج الموفين صراحة، لئلا يحمل ذم الناقضين على نقض عهد المستقيمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص634، تحت عنوان «براعة الاستدراك بقوله إلا الذين عاهدتم»","url":""}]},{"id":"s9-60","number":60,"surah":9,"verses":[7],"references":[{"surah":9,"verses":[7]}],"verseLabel":"التوبة: 7","question":"لماذا جعل وفاء المسلمين تابعًا لاستقامتهم: ﴿فما استقاموا لكم فاستقيموا لهم﴾؟","answer":"جعل الوفاء مقابل وفائهم تحقيقًا للعدل؛ فمدة استقامتهم هي مدة لزوم الاستقامة لهم، فإذا نقضوا زال موجب استمرار العهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص635، تحت عنوان «دلالة الفاء في قوله فما استقاموا»","url":""}]},{"id":"s9-61","number":61,"surah":9,"verses":[7],"references":[{"surah":9,"verses":[7]}],"verseLabel":"التوبة: 7","question":"ما دلالة ﴿لكم﴾ و﴿لهم﴾ في قوله: ﴿فما استقاموا لكم فاستقيموا لهم﴾؟","answer":"تخصص الجملتان الاستقامة بعلاقة الطرفين وعهدهما، وتربطان وفاء المسلمين بوفاء المعاهدين لهم. وفي مقابلة ﴿لكم﴾ بـ﴿لهم﴾ تأكيد أن الاستقامة المطلوبة وفاء متبادل منضبط بالعهد، وليست التزامًا مطلقًا يستمر مع نقضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص638، تحت عنوان «بديع المقابلة في قوله لكم ولهم»","url":""}]},{"id":"s9-62","number":62,"surah":9,"verses":[7],"references":[{"surah":9,"verses":[7]}],"verseLabel":"التوبة: 7","question":"لماذا تكررت مادة الاستقامة في الشرط والجواب؟","answer":"تكررت الاستقامة ليقابل الوفاءُ الوفاءَ، ويجيء الجزاء من جنس الشرط. وفي مادة الاستقامة تصوير للثبات على العهد بلزوم الطريق المستقيم دون انحراف؛ فأكد تكرارها هذا المعنى في الجانبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص638، تحت عنوان «بديع المقابلة في قوله لكم ولهم»","url":""}]},{"id":"s9-63","number":63,"surah":9,"verses":[7],"references":[{"surah":9,"verses":[7]}],"verseLabel":"التوبة: 7","question":"لماذا ختم مرة أخرى بـ﴿إن الله يحب المتقين﴾؟","answer":"كرر الختم لأن الوفاء في هذا الموضع أيضًا امتحان للتقوى، ولتأكيد أن الاستقامة للمعاهدين محبوبة لله وليست ضعفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص639، تحت عنوان «دلالة إن في قوله إن الله يحب المتقين»","url":""}]},{"id":"s9-64","number":64,"surah":9,"verses":[8],"references":[{"surah":9,"verses":[8]}],"verseLabel":"التوبة: 8","question":"لماذا أعاد الاستفهام بكلمة واحدة: ﴿كيف﴾؟","answer":"أعادت ﴿كيف﴾ وحدها إنكار إمكان بقاء العهد، ثم فصلت علة الإنكار: أنهم إن يظفروا لا يراعوا قرابة ولا عهدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص644، تحت عنوان «سر تكرار اسم الاستفهام كيف»","url":""}]},{"id":"s9-65","number":65,"surah":9,"verses":[8],"references":[{"surah":9,"verses":[8]}],"verseLabel":"التوبة: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن يظهروا عليكم﴾، دون أن يقال: «وإن ينتصروا»؟","answer":"الظهور هو العلو والغلبة والتمكن، وهو أوسع من مجرد الانتصار في واقعة؛ إذ يصور صيرورتهم فوق المسلمين قادرين عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص647، تحت عنوان «بلاغة قوله يظهروا عليكم»","url":""}]},{"id":"s9-66","number":66,"surah":9,"verses":[8],"references":[{"surah":9,"verses":[8]}],"verseLabel":"التوبة: 8","question":"لماذا جمع بين ﴿إلًّا ولا ذمة﴾؟","answer":"﴿الإل﴾ يشمل القرابة أو العهد والحلف، و﴿الذمة﴾ حرمة الأمان والالتزام؛ فالجمع ينفي مراعاتهم للرابطة الطبيعية والحق التعاقدي معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص656، تحت عنوان «الإل والذمة والعهد والميثاق واليمين»","url":""}]},{"id":"s9-67","number":67,"surah":9,"verses":[8],"references":[{"surah":9,"verses":[8]}],"verseLabel":"التوبة: 8","question":"أين تتجلى براعة الاستئناف البياني في يرضونكم في قوله تعالى: ﴿يرضونكم بأفواههم وتأبى قلوبهم﴾؟","answer":"الصورة تقابل بين ظاهر الكلام وباطن الاعتقاد: أفواه تنطق بما يرضي، وقلوب ترفض الوفاء؛ فتفضح التناقض والنفاق في معاملتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص650، تحت عنوان «براعة الاستئناف البياني في يرضونكم»","url":""}]},{"id":"s9-68","number":68,"surah":9,"verses":[8],"references":[{"surah":9,"verses":[8]}],"verseLabel":"التوبة: 8","question":"لماذا نُسب الإرضاء إلى الأفواه والإباء إلى القلوب؟","answer":"نُسب الإرضاء للأفواه لأنه قول سطحي لا يجاوز اللسان، ونُسب الإباء للقلوب لأنها محل النية والعزم الحقيقي؛ فظهر انفصال القول عن الضمير.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص653، تحت عنوان «براعة تعليق الإرضاء بقوله بأفواههم»","url":""}]},{"id":"s9-69","number":69,"surah":9,"verses":[8],"references":[{"surah":9,"verses":[8]}],"verseLabel":"التوبة: 8","question":"لماذا عبّر عن رفض القلوب بـ﴿تأبى﴾ لا «تكره»؟","answer":"الإباء يدل على شدة الامتناع ورفض ما تدعو إليه الأقوال الظاهرة، مع القدرة على الامتثال. فهو يكشف أن المشكلة ليست عجزًا عن الوفاء، بل رفضًا يعزمون عليه في قلوبهم، فيؤكد زيف ما يظهرونه بأفواههم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص654، تحت «نكتة التعبير بلفظ وتأبى»","url":""}]},{"id":"s9-70","number":70,"surah":9,"verses":[8],"references":[{"surah":9,"verses":[8]}],"verseLabel":"التوبة: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿وأكثرهم فاسقون﴾، ولم يعمم الفسق عليهم جميعًا؟","answer":"الفسق هنا نقض العهد والخروج عما توجبه المروءة والوفاء، لا مجرد الكفر الذي سبق وصفهم به. فنسب إلى أكثرهم لأن فيهم من يحفظ العهد أو يتعفف عن بعض صور الغدر، فجاء التقييد دقيقًا في تحديد الصفة المرادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص655–656، تحت «سبب الحكم بالفسق على الأكثرين»","url":""}]},{"id":"s9-71","number":71,"surah":9,"verses":[9],"references":[{"surah":9,"verses":[9]}],"verseLabel":"التوبة: 9","question":"لماذا صوّر استبدالهم بآيات الله بقوله: ﴿اشتروا بآيات الله ثمنًا قليلًا﴾؟","answer":"استعير الشراء لاستبدالهم آيات الله ومقتضاها بمصلحة عاجلة؛ فصوروا كتاجر باع النفيس الباقي بثمن حقير.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص660، تحت عنوان «بلاغة الاستعارة في ثمنًا قليلًا»","url":""}]},{"id":"s9-72","number":72,"surah":9,"verses":[9],"references":[{"surah":9,"verses":[9]}],"verseLabel":"التوبة: 9","question":"لماذا وصف الثمن بـ﴿قليلًا﴾ مهما عظم في أعينهم؟","answer":"كل عرض دنيوي قليل إذا قيس بآيات الله وثوابها، ولو عظم في أعينهم؛ فالقلة نسبية إلى ما تركوه وإلى سرعة زواله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص661، تحت عنوان «سبب وصف الثمن بالقليل»","url":""}]},{"id":"s9-73","number":73,"surah":9,"verses":[9],"references":[{"surah":9,"verses":[9]}],"verseLabel":"التوبة: 9","question":"ما دلالة الفاء في قوله: ﴿فصدوا عن سبيله﴾؟","answer":"تفيد أن الصد نتيجة مباشرة لصفقتهم الخاسرة؛ فلما آثروا الثمن القليل ترتب عليه إعراضهم وإعراض غيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص662، تحت عنوان «دلالة الفاء في فصدوا»","url":""}]},{"id":"s9-698","number":698,"surah":9,"verses":[9],"references":[{"surah":9,"verses":[9]}],"verseLabel":"التوبة: 9","question":"ما دلالة حذف مفعول ﴿فصدوا﴾؟","answer":"يتسع الحذف لأن يشمل صدهم أنفسهم وصدهم غيرهم عن سبيل الله، فيكشف عموم أثر فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص663، تحت عنوان «دلالة حذف مفعول فصدوا»","url":""}]},{"id":"s9-74","number":74,"surah":9,"verses":[9],"references":[{"surah":9,"verses":[9]}],"verseLabel":"التوبة: 9","question":"ما دلالة إضافة السبيل إلى الله في قوله: ﴿فصدوا عن سبيله﴾؟","answer":"الإضافة تشرف السبيل وتبين أنه الطريق الموصل إلى الله ورضوانه، فيعظم قبح الصد عنه. كما تربط الضمير بذكر آيات الله قبله، فتظهر أن الإعراض عن الآيات يفضي إلى الصد عن سبيله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص663، تحت عنوان «فائدة الإضافة في قوله سبيله»","url":""}]},{"id":"s9-75","number":75,"surah":9,"verses":[9],"references":[{"surah":9,"verses":[9]}],"verseLabel":"التوبة: 9","question":"لماذا ختم بـ﴿إنهم ساء ما كانوا يعملون﴾، ولم يقل: «ساء عملهم»؟","answer":"﴿ما كانوا يعملون﴾ تجعل الذم واقعًا على جنس عملهم المتجدد المستمر، لا على عمل مفرد، وتبرز رسوخ السوء في عادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص665، تحت عنوان «دلالة ما في ما كانوا يعملون»","url":""}]},{"id":"s9-76","number":76,"surah":9,"verses":[10],"references":[{"surah":9,"verses":[10]}],"verseLabel":"التوبة: 10","question":"لماذا كرر: ﴿لا يرقبون في مؤمن إلًّا ولا ذمة﴾ بعد وروده في الآية 8؟","answer":"الموضع الأول يعلل استبعاد عهدهم عند التمكن، والثاني يقرر الصفة نفسها في حق كل مؤمن ويمهد للحكم عليهم بالاعتداء؛ فزاد السياق الثاني تقريرًا وتعميمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص669، تحت «مناسبة مجيء الآية بطريق الفصل دون الوصل»","url":""}]},{"id":"s9-77","number":77,"surah":9,"verses":[10],"references":[{"surah":9,"verses":[10]}],"verseLabel":"التوبة: 10","question":"ما فائدة تقديم ﴿في مؤمن﴾؟","answer":"يوجه النظر إلى أن عداوتهم متعلقة بالمؤمن من حيث إيمانه، لا بخصومة عارضة مع جماعة بعينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص670، تحت عنوان «فائدة التقديم في قوله في مؤمن»","url":""}]},{"id":"s9-699","number":699,"surah":9,"verses":[10],"references":[{"surah":9,"verses":[10]}],"verseLabel":"التوبة: 10","question":"لماذا عبّر بوصف ﴿مؤمن﴾ بدل ضمير الجماعة؟","answer":"يجعل الوصف الإيماني نفسه سبب عداوتهم، ويعمم الحكم ليشمل كل فرد تحققت فيه صفة الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص671، تحت عنوان «سر صيغة المشتق في قوله مؤمن»","url":""}]},{"id":"s9-78","number":78,"surah":9,"verses":[10],"references":[{"surah":9,"verses":[10]}],"verseLabel":"التوبة: 10","question":"لماذا أفرد ﴿مؤمن﴾ مع أن الحديث عن جماعة؟","answer":"أُفرد ﴿مؤمن﴾ في سياق النفي ليعم كل مؤمن واحدًا واحدًا؛ فهم لا يراعون الحرمة في أي فرد متصف بالإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص671، تحت «فائدة التنكير في لفظ ﴿مؤمن﴾»","url":""}]},{"id":"s9-79","number":79,"surah":9,"verses":[10],"references":[{"surah":9,"verses":[10]}],"verseLabel":"التوبة: 10","question":"لماذا قال: ﴿وأولئك﴾؟","answer":"يشير اسم الإشارة إلى أصحاب الصفات المتقدمة، فيربط الحكم بما ظهر منهم من نكث وطعن وعدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص672، تحت عنوان «سبب إيثار التعبير باسم الإشارة»","url":""}]},{"id":"s9-700","number":700,"surah":9,"verses":[10],"references":[{"surah":9,"verses":[10]}],"verseLabel":"التوبة: 10","question":"ما دلالة ضمير الفصل في قوله: ﴿هم المعتدون﴾؟","answer":"يقوي إثبات الاعتداء لهم ويحصره فيهم على سبيل المبالغة أو رد دعواهم أن المسلمين هم المعتدون.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص672، تحت عنوان «دلالة القصر بضمير الفصل في هم المعتدون»","url":""}]},{"id":"s9-701","number":701,"surah":9,"verses":[10],"references":[{"surah":9,"verses":[10]}],"verseLabel":"التوبة: 10","question":"لماذا وصفهم بالمعتدين؟","answer":"لأن صفاتهم السابقة تجاوزت حد العهد والحق، فجمع الوصف نكثهم وطعنهم وبدءهم بالعدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص673، تحت عنوان «سبب إيثار الإخبار عنهم بلفظ المعتدون»","url":""}]},{"id":"s9-80","number":80,"surah":9,"verses":[11],"references":[{"surah":9,"verses":[11]}],"verseLabel":"التوبة: 11","question":"لماذا كرر شروط التوبة والصلاة والزكاة بعد ذكرها في الآية 5؟","answer":"في الآية الخامسة كانت الشروط سببًا لتخلية سبيلهم ووقف القتال، وهنا هي أساس دخولهم في أخوة الدين؛ فتكرر اللفظ واختلف الأثر المبني عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص683–684، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s9-81","number":81,"surah":9,"verses":[11],"references":[{"surah":9,"verses":[11]}],"verseLabel":"التوبة: 11","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿فإخوانكم في الدين﴾، وقال في الآية 5: ﴿فخلوا سبيلهم﴾؟","answer":"﴿فخلوا سبيلهم﴾ يبين زوال حكم القتال، أما ﴿فإخوانكم في الدين﴾ فيرتقي بهم إلى العضوية الكاملة في جماعة المؤمنين؛ فالثاني أبلغ في بيان أثر التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص683–684، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s9-82","number":82,"surah":9,"verses":[11],"references":[{"surah":9,"verses":[11]}],"verseLabel":"التوبة: 11","question":"لماذا قُيدت الأخوة بقوله: ﴿في الدين﴾؟","answer":"أضيفت الأخوة إلى الدين لتحديد أساسها الجديد: العقيدة الجامعة، لا النسب أو الحلف، ولتقرير ما يترتب عليها من حقوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص680، تحت عنوان «دلالة التقييد في الدين»","url":""}]},{"id":"s9-83","number":83,"surah":9,"verses":[11],"references":[{"surah":9,"verses":[11]}],"verseLabel":"التوبة: 11","question":"لماذا خُص تفصيل الآيات بقوم يعلمون؟","answer":"لأنهم الذين يتدبرون الفروق بين أحكام العهد والتوبة والقتال، ثم يعملون بما كشفه هذا التفصيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص682، تحت عنوان «فائدة التقييد بقوله لقوم يعلمون»","url":""}]},{"id":"s9-702","number":702,"surah":9,"verses":[11],"references":[{"surah":9,"verses":[11]}],"verseLabel":"التوبة: 11","question":"ما دلالة المضارع في ﴿نفصل﴾ و﴿يعلمون﴾؟","answer":"يفيد تجدد البيان واستمرار انتفاع أهل العلم به، فكلما تدبروا الآيات ازداد انكشاف الأحكام لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص683، تحت عنوان «دلالة المضارع نفصل ويعلمون»","url":""}]},{"id":"s9-84","number":84,"surah":9,"verses":[12],"references":[{"surah":9,"verses":[12]}],"verseLabel":"التوبة: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن نكثوا أيمانهم﴾، فشبّه نقض العهد بنكث الحبل؟","answer":"النكث في الأصل حل فتل الحبل، فاستعير لنقض الأيمان بعد إحكامها؛ إذ يصير العهد المحكم كحبل فُكّت قواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص688، تحت عنوان «بلاغة الاستعارة في نكثوا أيمانهم»","url":""}]},{"id":"s9-85","number":85,"surah":9,"verses":[12],"references":[{"surah":9,"verses":[12]}],"verseLabel":"التوبة: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعد عهدهم﴾ مع أن النكث لا يكون إلا بعد العهد؟","answer":"﴿من بعد عهدهم﴾ تؤكد شناعة النكث؛ فقد وقع بعد ميثاق ثابت مخصوص، لا قبل انعقاده أو عن جهل بوجوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص689، تحت عنوان «دلالة الإضافة في عهدهم»","url":""}]},{"id":"s9-86","number":86,"surah":9,"verses":[12],"references":[{"surah":9,"verses":[12]}],"verseLabel":"التوبة: 12","question":"لماذا جمع بين نكث الأيمان والطعن في الدين؟","answer":"جمع بين خيانة العهد والقدح في الدين، فزاد ذكر الطعن بيانًا لعداوتهم. ومن توجيهات العطف أن الطعن صورة من النكث خُصت بالذكر لشناعتها، ومن توجيهاته اعتبارهما وصفين اجتمعا فيهم؛ فلا يختزل المعنى في مخالفة عملية وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص689–690، تحت «دلالة الواو في وطعنوا»","url":""}]},{"id":"s9-87","number":87,"surah":9,"verses":[12],"references":[{"surah":9,"verses":[12]}],"verseLabel":"التوبة: 12","question":"لماذا عبّر عن الإساءة إلى الدين بـ﴿طعنوا في دينكم﴾؟","answer":"الطعن حقيقته الضرب بآلة نافذة، فاستعير للقدح الشديد في الدين؛ لما يحدثه من أذى ومحاولة تمزيق حرمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص690، تحت عنوان «دلالة لفظ وطعنوا»","url":""}]},{"id":"s9-88","number":88,"surah":9,"verses":[12],"references":[{"surah":9,"verses":[12]}],"verseLabel":"التوبة: 12","question":"لماذا وصفهم بأنهم ﴿أئمة الكفر﴾؟","answer":"لرسوخهم في الكفر وتقدمهم في النكث والطعن حتى صاروا قادة يقتدي بهم غيرهم في العدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص692، تحت عنوان «دلالة التعبير بلفظ أئمة»","url":""}]},{"id":"s9-703","number":703,"surah":9,"verses":[12],"references":[{"surah":9,"verses":[12]}],"verseLabel":"التوبة: 12","question":"لماذا خُص أئمة الكفر بالأمر بالقتال؟","answer":"لأن كف قادة العدوان يضعف أثرهم في أتباعهم ويوقف التحريض والنكث من منبعهما الأشد.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص693، تحت عنوان «مناسبة الأمر بقتال أئمة الكفر دون غيرهم»","url":""}]},{"id":"s9-89","number":89,"surah":9,"verses":[12],"references":[{"surah":9,"verses":[12]}],"verseLabel":"التوبة: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿إنهم لا أيمان لهم﴾ بعد ذكر أيمانهم التي نكثوها؟","answer":"أثبتت لهم الأيمان من حيث صدورها بألسنتهم، ثم نفت الاعتداد بها لعدم الوفاء. فالأيمان التي لا يحفظونها نُزلت منزلة المعدوم، وفي ذلك تعليل للأمر بقتال الناكثين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص696، تحت عنوان «دلالة النفي في لا أيمان لهم لما أثبت»","url":""}]},{"id":"s9-90","number":90,"surah":9,"verses":[12],"references":[{"surah":9,"verses":[12]}],"verseLabel":"التوبة: 12","question":"لماذا خُتم القتال بقوله: ﴿لعلهم ينتهون﴾؟","answer":"غاية القتال أن ينتهوا عن النكث والطعن والعدوان، لا أن يكون القتل مطلوبًا لذاته؛ و﴿لعل﴾ تفتح إمكان رجوعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص697، تحت عنوان «سر التعبير بقوله لعلهم ينتهون»","url":""}]},{"id":"s9-91","number":91,"surah":9,"verses":[13],"references":[{"surah":9,"verses":[13]}],"verseLabel":"التوبة: 13","question":"لماذا افتتحت الآية بالتحضيض: ﴿ألا تقاتلون قومًا﴾؟","answer":"﴿ألا﴾ للتحضيض الشديد؛ تستنكر التردد في قتال قوم اجتمعت منهم أسباب القتال، وتحرك همة المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص702–703، تحت «بلاغة التحضيض في ألا تقاتلون»","url":""}]},{"id":"s9-92","number":92,"surah":9,"verses":[13],"references":[{"surah":9,"verses":[13]}],"verseLabel":"التوبة: 13","question":"لماذا سُردت جرائمهم: نكث الأيمان، والهم بإخراج الرسول، والبدء بالقتال؟","answer":"سرد الجرائم يبني الحجة من ثلاث جهات: نقض الحق، والعدوان على الرسول، والبدء بالحرب؛ فلا يبقى للتردد مسوغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص704، تحت عنوان «سبب إيثار وصف القوم بثلاث جمل متعاطفة»","url":""}]},{"id":"s9-93","number":93,"surah":9,"verses":[13],"references":[{"surah":9,"verses":[13]}],"verseLabel":"التوبة: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿هموا بإخراج الرسول﴾، دون أن يقال: «هموا بإخراج محمد»؟","answer":"التعريف بالعهد يستحضر الرسول المعروف في قلوب المخاطبين بما له من الهيبة والتعظيم. وذكره بوصف الرسالة أبلغ هنا في تهويل جرأتهم على إخراجه واستنهاض المؤمنين لنصرته من الاقتصار على اسمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص707، تحت «دلالة أل في لفظ الرسول»","url":""}]},{"id":"s9-94","number":94,"surah":9,"verses":[13],"references":[{"surah":9,"verses":[13]}],"verseLabel":"التوبة: 13","question":"ما سرّ تقديم الضمير في ﴿وهم بدءوكم أول مرة﴾؟","answer":"تصدير الجملة بالضمير وبناؤها بناءً اسميًا يؤكد نسبة المبادأة إليهم، فيقرر أنهم بدأوا بالعدوان، ويقوي التحريض على دفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص707، تحت «براعة التعبير بقوله وهم بدءوكم أول مرة»","url":""}]},{"id":"s9-95","number":95,"surah":9,"verses":[13],"references":[{"surah":9,"verses":[13]}],"verseLabel":"التوبة: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿أول مرة﴾ مع أن البدء لا يكون إلا أولًا؟","answer":"يؤكد القيد أنهم أصحاب المبادأة بالعدوان منذ بدايته، فيزيد تقرير موجب قتالهم وذمهم، وإن كان معنى الابتداء مفهومًا من الفعل نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص707–708، تحت «دلالة النصب والإضافة في قوله أول مرة»","url":""}]},{"id":"s9-96","number":96,"surah":9,"verses":[13],"references":[{"surah":9,"verses":[13]}],"verseLabel":"التوبة: 13","question":"لماذا انتقل فجأة إلى السؤال: ﴿أتخشونهم﴾؟","answer":"انتقل إلى ﴿أتخشونهم﴾ لكشف علة التردد بعد ثبوت موجبات القتال؛ فالذي قد يبقى ليس نقص الحجة بل خوف الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص708، تحت عنوان «براعة الحث على القتال»","url":""}]},{"id":"s9-97","number":97,"surah":9,"verses":[13],"references":[{"surah":9,"verses":[13]}],"verseLabel":"التوبة: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿فالله أحق أن تخشوه﴾، فجاء باسم التفضيل؟","answer":"ليس المقصود إثبات استحقاق الطرفين لخشية التعظيم ثم ترجيح أحدهما، بل تقرير أن الله وحده المستحق لها. فجاء اسم التفضيل لرد ما عرض لهم من خشية العدو، وحملهم على تقديم أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص709، تحت عنوان «دلالة اسم التفضيل أحق»","url":""}]},{"id":"s9-98","number":98,"surah":9,"verses":[13],"references":[{"surah":9,"verses":[13]}],"verseLabel":"التوبة: 13","question":"لماذا ختم بقوله: ﴿إن كنتم مؤمنين﴾؟","answer":"التعليق بالإيمان يستنهض مقتضاه؛ فالإيمان الحق يجعل خشية الله مقدمة ويمنع التخاذل عن أمره، وليس المراد نفي أصل إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص710، تحت عنوان «بلاغة التعبير بأسلوب الشرط»","url":""}]},{"id":"s9-99","number":99,"surah":9,"verses":[14],"references":[{"surah":9,"verses":[14]}],"verseLabel":"التوبة: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿قاتلوهم يعذبهم الله بأيديكم﴾، فنسب الفعل إلى المؤمنين والعذاب إلى الله؟","answer":"المؤمنون يباشرون القتال بأيديهم، والله يجعله عذابًا مستحقًا وينفذ به حكمه؛ فنسبت المباشرة إليهم والتقدير والجزاء إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص718، تحت «بلاغة المجاز العقلي»","url":""}]},{"id":"s9-100","number":100,"surah":9,"verses":[14],"references":[{"surah":9,"verses":[14]}],"verseLabel":"التوبة: 14","question":"لماذا اختير ﴿يعذبهم﴾ لا «يهزمهم»؟","answer":"اختير ﴿يعذبهم﴾ لأن الهزيمة تصف النتيجة العسكرية فقط، أما التعذيب فيجعل ما ينزل بهم جزاءً على كفرهم وعدوانهم، ويشمل القتل والأسر والذل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص717، تحت «سر اختيار لفظ يعذبهم»","url":""}]},{"id":"s9-101","number":101,"surah":9,"verses":[14],"references":[{"surah":9,"verses":[14]}],"verseLabel":"التوبة: 14","question":"ما سر تقييد العذاب بقوله: ﴿بأيديكم﴾؟","answer":"فيه تشريف للمؤمنين بأن يجعلهم الله سببًا في تعذيب أعدائهم، وبشارة بإقدارهم عليهم. ووقوع ذلك بأيديهم أبلغ في شفاء صدورهم، وأشد على العدو من عذاب لا يكون المؤمنون وسيلته.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص718، تحت «سر تعليق العذاب بأيدي المؤمنين»","url":""}]},{"id":"s9-102","number":102,"surah":9,"verses":[14],"references":[{"surah":9,"verses":[14]}],"verseLabel":"التوبة: 14","question":"لماذا جمع أربعة آثار للقتال: تعذيبهم، وإخزاؤهم، ونصر المؤمنين، وشفاء الصدور؟","answer":"جمعت الآثار استيفاءً لوجهي الجزاء: ما يصيب العدو من عذاب وخزي، وما يناله المؤمنون من نصر وشفاء؛ فظهر أثر القتال في الخارج والنفس معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص716–717، تحت «براعة التعبير بتتابع الجزاء ودلالتها على التأييد الإلهي»","url":""}]},{"id":"s9-103","number":103,"surah":9,"verses":[14],"references":[{"surah":9,"verses":[14]}],"verseLabel":"التوبة: 14","question":"لماذا عبّر عن إزالة الألم بقوله: ﴿ويشف صدور قوم مؤمنين﴾؟","answer":"شُبه زوال ألم المؤمنين وغيظهم بشفاء المريض؛ لأن أذى المشركين استقر في صدورهم كالداء، فجاء النصر علاجًا يزيله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص720–721، تحت «بلاغة الاستعارة التصريحية التبعية»","url":""}]},{"id":"s9-104","number":104,"surah":9,"verses":[14],"references":[{"surah":9,"verses":[14]}],"verseLabel":"التوبة: 14","question":"ما دلالة الانتقال من خطاب المقاتلين إلى الغيبة في قوله: ﴿ويشف صدور قوم مؤمنين﴾؟","answer":"ينوه الانتقال بالمؤمنين بوصف الإيمان، ويجعل شفاء صدورهم ثمرة ظاهرة ينظر إليها المخاطبون.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص720، تحت عنوان «مناسبة الخطاب في التعذيب والنصر والغيبة في سواهما»","url":""}]},{"id":"s9-704","number":704,"surah":9,"verses":[14],"references":[{"surah":9,"verses":[14]}],"verseLabel":"التوبة: 14","question":"لماذا قال: ﴿قوم مؤمنين﴾ ولم يقل: «صدوركم»؟","answer":"يتسع لفظ القوم لكل من آذاه المعتدون من المؤمنين، ولو لم يكن من المخاطبين الذين باشروا القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص721، تحت عنوان «نكتة التعبير بلفظ قوم»","url":""}]},{"id":"s9-105","number":105,"surah":9,"verses":[15],"references":[{"surah":9,"verses":[15]}],"verseLabel":"التوبة: 15","question":"ما وجه عطف ﴿ويذهب غيظ قلوبهم﴾ على ﴿ويشف صدور قوم مؤمنين﴾؟","answer":"من توجيهاته اختلاف الأثرين: شفاء الصدور يرفع ألم الأذى، وذهاب الغيظ يزيل ما بقي من حرارته. وذُكر أيضًا أن العطف يؤكد تمام الشفاء، أو يترقى من حصول السرور بالنصر إلى زوال الغيظ؛ فالمعنيان متكاملان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص722–723، تحت «مناسبة العطف»","url":""}]},{"id":"s9-106","number":106,"surah":9,"verses":[15],"references":[{"surah":9,"verses":[15]}],"verseLabel":"التوبة: 15","question":"ما سرّ التعبير في قوله تعالى: ﴿غيظ قلوبهم﴾ بعد قوله: ﴿صدور قوم مؤمنين﴾؟","answer":"الغيظ حرارة شديدة محلها القلب، والقلب أخص من الصدر. أما الهم والألم الناشئان عن الأذى فيناسبهما التعبير بالصدور؛ فجيء بالقلوب عند بيان زوال الغيظ خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص721، تحت عنوان «مناسبة التعبير بلفظ الصدور دون القلوب»","url":""}]},{"id":"s9-107","number":107,"surah":9,"verses":[15],"references":[{"surah":9,"verses":[15]}],"verseLabel":"التوبة: 15","question":"لماذا جاء بعد القتال قوله: ﴿ويتوب الله على من يشاء﴾؟","answer":"يبين ذكر التوبة أن بابها مفتوح لمن رجع من المشركين، وأن القتال لا يقتضي تعذيب كل فرد منهم. فقد يكون ما يرونه من النصر وكسر شوكة الكفر سببًا في رجوع بعضهم إلى الإيمان، فيتوب الله عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص724، تحت عنوان «مناسبة مجيء قوله ويتوب الله بالوصل دون الفصل»","url":""}]},{"id":"s9-108","number":108,"surah":9,"verses":[15],"references":[{"surah":9,"verses":[15]}],"verseLabel":"التوبة: 15","question":"لماذا عُلقت التوبة بالمشيئة؟","answer":"تعليقها بالمشيئة يبين أن التوفيق للتوبة بيد الله، لا نتيجة لازمة لكل من وقع عليه القتال. وحذف مفعول ﴿يشاء﴾ يوجه إلى عموم قدرته وفضله، دون تقييد قبول التوبة بسبب مخصوص مذكور في اللفظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص726، تحت عنوان «دلالة التعبير بالموصول من»","url":""}]},{"id":"s9-109","number":109,"surah":9,"verses":[15],"references":[{"surah":9,"verses":[15]}],"verseLabel":"التوبة: 15","question":"لماذا ختم بـ﴿والله عليم حكيم﴾؟","answer":"﴿عليم﴾ بمن يستحق الهداية وبما في القلوب، و﴿حكيم﴾ في النصر والتعذيب والتوبة؛ فكل حكم موضوع في موضعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص727، تحت عنوان «توجيه المتشابه اللفظي»","url":""}]},{"id":"s9-110","number":110,"surah":9,"verses":[16],"references":[{"surah":9,"verses":[16]}],"verseLabel":"التوبة: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿أم حسبتم أن تتركوا﴾ بعد أوامر القتال؟","answer":"﴿أم حسبتم﴾ تنكر ظن أن يتركوا بلا اختبار بعد أمر القتال؛ فالدعوى لا تكفي حتى يظهر صدق الجهاد والولاء بالفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص729، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-111","number":111,"surah":9,"verses":[16],"references":[{"surah":9,"verses":[16]}],"verseLabel":"التوبة: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿ولما يعلم الله الذين جاهدوا منكم﴾ مع أن الله يعلمهم قبل الجهاد؟","answer":"ليس المراد حدوث علم بعد جهل، بل ظهور المعلوم في عالم العمل ليتميز المجاهد المخلص وتقوم عليه الحجة ويترتب الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص734، تحت عنوان «دلالة العلم في قوله ولما يعلم الله»","url":""}]},{"id":"s9-112","number":112,"surah":9,"verses":[16],"references":[{"surah":9,"verses":[16]}],"verseLabel":"التوبة: 16","question":"لماذا اختيرت ﴿لما﴾ بدل «لم»؟","answer":"﴿لما﴾ تنفي وقوع العلم المتعلق بظهور العمل إلى زمن الكلام مع توقع وقوعه بعد الاختبار، بخلاف ﴿لم﴾ التي لا تتضمن هذا التوقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص732–733، تحت «دلالة التعبير بحرف الجزم ولما»","url":""}]},{"id":"s9-113","number":113,"surah":9,"verses":[16],"references":[{"surah":9,"verses":[16]}],"verseLabel":"التوبة: 16","question":"لماذا جمع بين الجهاد وعدم اتخاذ الوليجة؟","answer":"الجهاد يختبر العمل الظاهر، وترك الوليجة يختبر الولاء الباطن؛ فجمعهما لاستكمال صدق المؤمن في فعله وسره.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص734، تحت عنوان «فائدة مجيء صلتين للاسم الموصول»","url":""}]},{"id":"s9-114","number":114,"surah":9,"verses":[16],"references":[{"surah":9,"verses":[16]}],"verseLabel":"التوبة: 16","question":"ما الصورة في قوله: ﴿ولم يتخذوا... وليجة﴾؟","answer":"الوليجة من الولوج والدخول؛ فصُوّر الخليل الذي يدخل في أسرار القوم ويستبطن شؤونهم كمن يدخل مكانًا مستورًا. والمراد هنا نفي اتخاذ بطانة من خارج جماعة الإيمان يُطلعها المرء على خفايا المسلمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص738، تحت عنوان «بلاغة الاستعارة في لفظ وليجة»","url":""}]},{"id":"s9-115","number":115,"surah":9,"verses":[16],"references":[{"surah":9,"verses":[16]}],"verseLabel":"التوبة: 16","question":"ما دلالة ترتيب الله ثم رسوله ثم المؤمنين في الآية؟","answer":"يراعي الترتيب جلال الله أولًا، ثم مقام رسوله، ثم شرف المؤمنين بانتسابهم إلى الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص736، تحت عنوان «دلالة الترتيب بين لفظ الجلالة وما بعده من معطوفات»","url":""}]},{"id":"s9-705","number":705,"surah":9,"verses":[16],"references":[{"surah":9,"verses":[16]}],"verseLabel":"التوبة: 16","question":"لماذا تكررت ﴿لا﴾ في قوله: ﴿ولا رسوله ولا المؤمنين﴾؟","answer":"يؤكد التكرار النفي ويجعل كل جهة مستقلة بالحكم، فلا يصح ولاء يدعي صاحبه واحدة ويهدر الباقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص737، تحت عنوان «مناسبة تكرار ولا في الآية»","url":""}]},{"id":"s9-116","number":116,"surah":9,"verses":[16],"references":[{"surah":9,"verses":[16]}],"verseLabel":"التوبة: 16","question":"ما مناسبة ختم الآية بقوله: ﴿والله خبير بما تعملون﴾؟","answer":"المقام يختبر إخلاص الجهاد والولاء، وهما متصلان بباطن الإنسان وسره؛ فناسبه وصف ﴿خبير﴾ الدال على الإحاطة بالخفايا. وفي التذييل تنبيه إلى أن الله يعلم الأعمال ودوافعها، ويجازي عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص738، تحت عنوان «بلاغة التعبير بجملة التذييل»","url":""}]},{"id":"s9-117","number":117,"surah":9,"verses":[17],"references":[{"surah":9,"verses":[17]}],"verseLabel":"التوبة: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿ما كان للمشركين أن يعمروا مساجد الله﴾، دون أن يقال: «لا يعمر المشركون»؟","answer":"صيغة ﴿ما كان لهم أن﴾ تنفي استحقاقهم وصلاحيتهم للعمارة، لا مجرد وقوع الفعل؛ فالشرك يناقض عمارة مسجد بني لعبادة الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص743، تحت عنوان «مناسبة التعبير بما كان»","url":""}]},{"id":"s9-118","number":118,"surah":9,"verses":[17],"references":[{"surah":9,"verses":[17]}],"verseLabel":"التوبة: 17","question":"لماذا نُفيت عمارة المشركين لمساجد الله مع قيامهم بالبناء والخدمة؟","answer":"النفي متوجه إلى صحة عمارتهم والاعتداد بها عند الله، لا إلى إنكار وقوع البناء والخدمة حسًا. فالعمارة تشمل البناء والعبادة، وقد نزل ما فعلوه منزلة العدم من جهة القبول بسبب شركهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص743، تحت عنوان «دلالة ما كان في الآية»","url":""}]},{"id":"s9-119","number":119,"surah":9,"verses":[17],"references":[{"surah":9,"verses":[17]}],"verseLabel":"التوبة: 17","question":"لماذا وصفهم بأنهم ﴿شاهدين على أنفسهم بالكفر﴾؟","answer":"إظهارهم آثار الشرك، كنصب الأوثان والعبادة لها، بمنزلة شهادة ظاهرة على كفرهم، وهي أدل من دعوى مجردة. ووقوع هذه الشهادة حالًا من عمارتهم يبرز التناقض بين شركهم وعمارة بيوت التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص748، تحت عنوان «نكتة التعبير بلفظ شاهدين»","url":""}]},{"id":"s9-120","number":120,"surah":9,"verses":[17],"references":[{"surah":9,"verses":[17]}],"verseLabel":"التوبة: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿حبطت أعمالهم﴾ مع وجود أعمال نافعة ظاهرًا؟","answer":"حبطت أعمالهم أي بطل ثوابها وآثارها الأخروية بسبب الكفر، وإن ظهر لبعضها نفع دنيوي؛ فالعمل لا يقبل دون أصل الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص749، تحت عنوان «سبب إيثار صيغة الجمع في قوله أعمالهم»","url":""}]},{"id":"s9-121","number":121,"surah":9,"verses":[17],"references":[{"surah":9,"verses":[17]}],"verseLabel":"التوبة: 17","question":"لماذا انتقل من حبوط الأعمال إلى الخلود في النار؟","answer":"الحبوط يبين بطلان ما ظنوه رصيدًا من الأعمال، والخلود يبين العاقبة المقابلة؛ فلا ثواب لهم بل إقامة دائمة في النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص750، تحت عنوان «دلالة الواو في الآية»","url":""}]},{"id":"s9-122","number":122,"surah":9,"verses":[18],"references":[{"surah":9,"verses":[18]}],"verseLabel":"التوبة: 18","question":"لماذا قصر عمارة المساجد بقوله: ﴿إنما يعمر مساجد الله من آمن بالله﴾؟","answer":"القصر يرد دعوى المشركين في استحقاق العمارة، ويثبتها لمن جمع الإيمان والعبادة والخشية؛ فليست العمارة مجرد خدمة مكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص753، تحت عنوان «دلالة القصر بأداة الحصر إنما»","url":""}]},{"id":"s9-123","number":123,"surah":9,"verses":[18],"references":[{"surah":9,"verses":[18]}],"verseLabel":"التوبة: 18","question":"لماذا جمع في عُمّار المساجد بين الإيمان والصلاة والزكاة والخشية؟","answer":"الإيمان أصل صحة العمل، والصلاة عمارة المسجد بالعبادة، والزكاة برهان البذل، والخشية تحفظ الإخلاص؛ فاجتمعت أصول الاعتقاد والعمل الباطن والظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص755، تحت عنوان «سبب عدم ذكر الإيمان بالرسول في الآية»","url":""}]},{"id":"s9-124","number":124,"surah":9,"verses":[18],"references":[{"surah":9,"verses":[18]}],"verseLabel":"التوبة: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿ولم يخش إلا الله﴾ مع أن الخوف الطبيعي من الناس واقع؟","answer":"المنفي خشية العبادة والطاعة التي تحمل على مخالفة الله، لا الخوف الجبلي من ضرر محسوس؛ فالقصر متعلق بخشية التعظيم والانقياد.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص759، تحت عنوان «دلالة الحصر»","url":""}]},{"id":"s9-125","number":125,"surah":9,"verses":[18],"references":[{"surah":9,"verses":[18]}],"verseLabel":"التوبة: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿فعسى أولئك أن يكونوا من المهتدين﴾ مع تحقق صفاتهم؟","answer":"من توجيهات ﴿عسى﴾ هنا أنها وعد من الله، وصيغت بصيغة الرجاء لئلا يغتر المؤمن بعمله ويتكل عليه. وفيها أيضًا قطع لطمع المشركين في الاهتداء مع فقد هذه الصفات، وحث للمؤمن على رجاء الهداية والأخذ بأسبابها دون الجزم لنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص760–761، تحت «دلالة عسى»","url":""}]},{"id":"s9-126","number":126,"surah":9,"verses":[19],"references":[{"surah":9,"verses":[19]}],"verseLabel":"التوبة: 19","question":"ما غرض الاستفهام في قوله: ﴿أجعلتم سقاية الحاج...﴾؟","answer":"ينكر الاستفهام التسوية ويوبخ عليها؛ فلا يستوي عمل ظاهر مع الإيمان بالله والجهاد في سبيله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص767، تحت عنوان «بلاغة الاستفهام المجازي»","url":""}]},{"id":"s9-706","number":706,"surah":9,"verses":[19],"references":[{"surah":9,"verses":[19]}],"verseLabel":"التوبة: 19","question":"إلى من وُجه الخطاب في قوله: ﴿أجعلتم سقاية الحاج﴾؟","answer":"إن وُجه إلى المشركين أبطل مساواة الخدمة مع الشرك بالإيمان والجهاد، وإن وُجه إلى مؤمنين افتخروا بها بيّن أنها لا تبلغ منزلتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص767، تحت عنوان «دلالة الخطاب بين الالتفات أو الدلالة على مقتضى الظاهر»","url":""}]},{"id":"s9-127","number":127,"surah":9,"verses":[19],"references":[{"surah":9,"verses":[19]}],"verseLabel":"التوبة: 19","question":"لماذا قورنت أعمال مادية بأشخاص مؤمنين، لا بأعمالهم؟","answer":"من توجيهات التعبير تقدير مضاف: أجعلتم أهل السقاية والعمارة كمن آمن، أو تقدير عمل في الطرف الآخر: كإيمان من آمن. ووجه آخر أنه احتباك، حُذف صاحب العمل من جانب والعمل من الآخر لدلالة المذكور عليهما؛ فالمقارنة مفهومة دون تطويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص768–769، تحت «براعة التشبيه»","url":""}]},{"id":"s9-128","number":128,"surah":9,"verses":[19],"references":[{"surah":9,"verses":[19]}],"verseLabel":"التوبة: 19","question":"لماذا ذُكر الإيمان بالله واليوم الآخر مع الجهاد في الطرف المقابل للسقاية والعمارة؟","answer":"تذكر الصلة صفات العاملين، لتبين أن مناط تميزهم هو الإيمان والجهاد في سبيل الله، لا صورة العمل وحدها. وفي جمعها تعظيم لهذه الأوصاف وحث عليها، وبيان منزلة الجهاد بالقياس إلى الأعمال المذكورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص770، تحت عنوان «مناسبة ذكر الجهاد لرد العدوان دون غيره من الأعمال»","url":""}]},{"id":"s9-129","number":129,"surah":9,"verses":[19],"references":[{"surah":9,"verses":[19]}],"verseLabel":"التوبة: 19","question":"لماذا قُيد نفي الاستواء بقوله: ﴿عند الله﴾؟","answer":"ليبين أن الميزان المعتبر هو حكم الله وجزاؤه، لا ما يعتقده الناس من المفاخرة والتسوية. فعدم الاستواء ثابت في ميزانه سبحانه، ولو زعموا لأنفسهم منزلة مساوية أو أفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص771، تحت «فائدة تقييد لا يستوون بقوله عند الله»","url":""}]},{"id":"s9-130","number":130,"surah":9,"verses":[19],"references":[{"surah":9,"verses":[19]}],"verseLabel":"التوبة: 19","question":"لماذا ختم بـ﴿والله لا يهدي القوم الظالمين﴾؟","answer":"من سوّى بين الشرك والإيمان ووضع العمل في غير منزلته فقد ظلم، وعدم هدايته جزاء إصراره ويؤكد بطلان هذه التسوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص772، تحت عنوان «دلالة نفي الهداية على عدم وصولهم إلى المطلوب»","url":""}]},{"id":"s9-131","number":131,"surah":9,"verses":[20],"references":[{"surah":9,"verses":[20]}],"verseLabel":"التوبة: 20","question":"لماذا أعاد ذكر الإيمان والجهاد وأضاف الهجرة بعد نفي المساواة في الآية السابقة؟","answer":"الآية السابقة نفت المساواة، ثم جاء التصريح بالطرف الراجح وبيان صفاته ودرجته. فذُكرت الهجرة مع الإيمان والجهاد لاستيفاء صفات هؤلاء المؤمنين والثناء عليهم، والانتقال من المقارنة إلى تقرير فضلهم وجزائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص774، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-132","number":132,"surah":9,"verses":[20],"references":[{"surah":9,"verses":[20]}],"verseLabel":"التوبة: 20","question":"ما سرّ تقديم الجهاد بالأموال على الأنفس؟","answer":"من وجوه التقديم أن بذل المال أخف من بذل النفس، فترقى من الأدنى إلى الأعلى. والمال أيضًا قوام الإنفاق والتجهيز للجهاد، وقد يحتاج إليه المجاهد حتى يصل إلى ميدان القتال؛ فقدم ما هو من أسبابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص779–780، تحت «مناسبة تقديم الأموال على الأنفس»","url":""}]},{"id":"s9-133","number":133,"surah":9,"verses":[20],"references":[{"surah":9,"verses":[20]}],"verseLabel":"التوبة: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿أعظم درجة عند الله﴾ ولم يذكر الطرف الآخر؟","answer":"من توجيهاته أن المقصود بيان علو منزلة هؤلاء المؤمنين على الإطلاق، لا تخصيص فضلهم بالمقارنة بأهل السقاية والعمارة وحدهم. وعلى حمل المقارنة على المشركين، فليس لهم عند الله درجة معتبرة أصلًا؛ فجاء التعبير ردًا لما توهموه لأنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص781، تحت «سبب عدم ذكر الطرف المرجوح في آية أعظمية الدرجة»","url":""}]},{"id":"s9-134","number":134,"surah":9,"verses":[20],"references":[{"surah":9,"verses":[20]}],"verseLabel":"التوبة: 20","question":"ما دلالة تنكير ﴿درجة﴾ في قوله: ﴿أعظم درجة عند الله﴾؟","answer":"التنكير للتعظيم والتفخيم؛ فيبرز علو منزلتهم ورفعة مقامهم عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص780، تحت «دلالة تنكير درجة»","url":""}]},{"id":"s9-135","number":135,"surah":9,"verses":[20],"references":[{"surah":9,"verses":[20]}],"verseLabel":"التوبة: 20","question":"لماذا جاء القصر: ﴿وأولئك هم الفائزون﴾؟","answer":"اسم الإشارة وضمير الفصل يقصران الفوز الحقيقي عليهم؛ لأنهم جمعوا الإيمان والهجرة والجهاد، لا أصحاب المفاخر الظاهرة الخالية من الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص782، تحت عنوان «بلاغة الحصر»","url":""}]},{"id":"s9-137","number":137,"surah":9,"verses":[21],"references":[{"surah":9,"verses":[21]}],"verseLabel":"التوبة: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿يبشرهم ربهم﴾، فاختار اسم الرب؟","answer":"اختير ﴿ربهم﴾ لاستحضار الرعاية والتربية والإنعام؛ فهو الذي تولى أمرهم حتى بلغهم منازل البشارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص790، تحت عنوان «دلالة الإضافة في لفظ ربهم»","url":""}]},{"id":"s9-138","number":138,"surah":9,"verses":[21],"references":[{"surah":9,"verses":[21]}],"verseLabel":"التوبة: 21","question":"لماذا بدأت البشارة برحمة من الله؟","answer":"لأن الرحمة أصل ما يتلقاه المؤمنون من الإنعام، ومنها رضوان الله وجزاء الجنات الدائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص791، تحت عنوان «إيثار التعبير بلفظ رحمة ومناسبته للسياق»","url":""}]},{"id":"s9-707","number":707,"surah":9,"verses":[21],"references":[{"surah":9,"verses":[21]}],"verseLabel":"التوبة: 21","question":"ما سر ترتيب الرحمة ثم الرضوان ثم الجنات؟","answer":"بدأ بالرحمة العامة، ثم بالرضوان الذي يخصهم بالقبول، ثم فصل الجزاء المحسوس في الجنات؛ فشمل أسباب النعيم وصوره.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص792، تحت عنوان «سر تقديم الرحمة على الرضوان»","url":""}]},{"id":"s9-139","number":139,"surah":9,"verses":[21],"references":[{"surah":9,"verses":[21]}],"verseLabel":"التوبة: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿برحمة منه﴾ مع أن كل رحمة منه؟","answer":"﴿منه﴾ تؤكد أن الرحمة عطاء خاص صادر من عنده لا سبب مستقل عنه، وفيها تعظيم لقرب المنحة وشرف مصدرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص791، تحت عنوان «سر تنكير لفظ رحمة»","url":""}]},{"id":"s9-140","number":140,"surah":9,"verses":[21,72],"references":[{"surah":9,"verses":[21,72]}],"verseLabel":"التوبة: 21؛ التوبة: 72","question":"ما سر تنكير ﴿رحمة﴾ في قوله: ﴿يبشرهم ربهم برحمة منه﴾؟","answer":"يفيد التنكير التعظيم والتفخيم: فهي رحمة عظيمة صادرة من ربهم لا يحيط الوصف بقدرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص791، تحت عنوان «سر تنكير لفظ رحمة»","url":""}]},{"id":"s9-708","number":708,"surah":9,"verses":[21,72],"references":[{"surah":9,"verses":[21,72]}],"verseLabel":"التوبة: 21؛ التوبة: 72","question":"ما نكتة تنكير ﴿رضوان﴾؟","answer":"يشير التنكير إلى عظم رضوان الله وتنوع آثاره، ثم يبين السياق أنه أكبر من النعيم المذكور.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص791، تحت عنوان «نكتة تنكير رضوان»","url":""}]},{"id":"s9-141","number":141,"surah":9,"verses":[21],"references":[{"surah":9,"verses":[21]}],"verseLabel":"التوبة: 21","question":"لماذا وصف النعيم بأنه ﴿مقيم﴾؟","answer":"وُصف النعيم بالمقيم لأنه ثابت لا يزول ولا ينتقل عن صاحبه، خلاف نعيم الدنيا العارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص794، تحت عنوان «دلالة وصف النعيم بكونه مقيمًا»","url":""}]},{"id":"s9-143","number":143,"surah":9,"verses":[22],"references":[{"surah":9,"verses":[22]}],"verseLabel":"التوبة: 22","question":"لماذا فُصل قوله: ﴿إن الله عنده أجر عظيم﴾ عما قبله؟","answer":"جاءت الجملة استئنافًا يعلل البشارة السابقة ويقرر أن ما عند الله هو الجزاء الجدير بطلبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص797، تحت عنوان «علة فصل قوله إن الله عنده أجر عظيم عما قبله»","url":""}]},{"id":"s9-709","number":709,"surah":9,"verses":[22],"references":[{"surah":9,"verses":[22]}],"verseLabel":"التوبة: 22","question":"لماذا وُصف الأجر بأنه عظيم؟","answer":"لأنه يجمع رحمة الله ورضوانه والجنة، وهو عظيم في قدره ودائم لا ينقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص798، تحت عنوان «سر وصف الأجر بالعظمة»","url":""}]},{"id":"s9-144","number":144,"surah":9,"verses":[23],"references":[{"surah":9,"verses":[23]}],"verseLabel":"التوبة: 23","question":"لماذا خُص الآباء والإخوان بالنهي عن اتخاذهم أولياء إذا استحبوا الكفر؟","answer":"لأنهما من أقرب القرابات وأقواها أثرًا في النصرة والمشورة، فإذا نُهي عن موالاتهما على هذه الحال كان من دونهما أولى. ويذكر المصدر أن الأبناء والأزواج يتبعون المخاطبين في هذا المقام، بخلاف الآباء والإخوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص14–15، تحت «نكتة تخصيص الآباء والإخوان بالذكر»","url":""}]},{"id":"s9-145","number":145,"surah":9,"verses":[23],"references":[{"surah":9,"verses":[23]}],"verseLabel":"التوبة: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿استحبوا الكفر على الإيمان﴾، دون أن يقال: «اختاروا الكفر»؟","answer":"تدل الصيغة على إيثار الكفر على الإيمان وطلب محبته. ومن نكتها أن الإيمان محبوب بظهور محاسنه وأدلته، فترجيح الكفر عليه يصور انحراف الاختيار وشدة تعلقهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص16، تحت «دلالة السين والتاء في استحبوا»","url":""}]},{"id":"s9-146","number":146,"surah":9,"verses":[23],"references":[{"surah":9,"verses":[23]}],"verseLabel":"التوبة: 23","question":"لماذا عُدي ﴿استحبوا﴾ بـ﴿على﴾؟","answer":"عدي بـ﴿على﴾ لتضمين الاستحباب معنى الإيثار والتفضيل؛ أي قدموا الكفر ورفعوه فوق الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص16–17، تحت «دلالة التضمين»","url":""}]},{"id":"s9-147","number":147,"surah":9,"verses":[23],"references":[{"surah":9,"verses":[23]}],"verseLabel":"التوبة: 23","question":"لماذا أُفرد الضمير في ﴿يتولهم﴾ ثم جُمع الجزاء في ﴿فأولئك﴾؟","answer":"رُوعي لفظ ﴿من﴾ في إفراد الضمير في ﴿يتولهم﴾، ثم رُوعي عموم معناها في جمع الجزاء؛ ليشمل الحكم كل من وقع منه التولي.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص17، تحت «نكتة إفراد الضمير في يتولهم»","url":""}]},{"id":"s9-710","number":710,"surah":9,"verses":[23],"references":[{"surah":9,"verses":[23]}],"verseLabel":"التوبة: 23","question":"ما وجه القصر في قوله تعالى: ﴿فأولئك هم الظالمون﴾؟","answer":"يفيد ضمير الفصل مع تعريف الخبر المبالغة في إثبات الظلم لهم وتهويل شناعة موالاتهم لأعداء الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص19، تحت «بلاغة القصر»","url":""}]},{"id":"s9-148","number":148,"surah":9,"verses":[23],"references":[{"surah":9,"verses":[23]}],"verseLabel":"التوبة: 23","question":"ما دلالة التعريف في لفظ ﴿الظالمون﴾؟","answer":"يفيد التعريف المبالغة في شناعة ظلمهم، مع تعميم الوعيد على من يضع الولاية في غير موضعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص19، تحت «دلالة أل في لفظ الظالمون»","url":""}]},{"id":"s9-711","number":711,"surah":9,"verses":[23],"references":[{"surah":9,"verses":[23]}],"verseLabel":"التوبة: 23","question":"ما وجه براعة التذييل في قوله تعالى: ﴿فأولئك هم الظالمون﴾؟","answer":"جاء التذييل حكمًا جامعًا يقرر أن موالاة أعداء الإيمان وضع للولاية في غير موضعها، ولذلك سُمّيت ظلمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص20، تحت «براعة التذييل»","url":""}]},{"id":"s9-149","number":149,"surah":9,"verses":[24],"references":[{"surah":9,"verses":[24]}],"verseLabel":"التوبة: 24","question":"لماذا عدّد الآباء والأبناء والإخوان والأزواج والعشيرة والأموال والتجارة والمساكن؟","answer":"عُددت لتستوعب أهم محبوبات الإنسان: أصوله وفروعه وإخوته وأزواجه وعشيرته وماله وكسبه ومسكنه، فلا يبقى محبوب يتذرع به لتقديمه على أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص27، تحت «بلاغة مراعاة النظير»","url":""}]},{"id":"s9-150","number":150,"surah":9,"verses":[24],"references":[{"surah":9,"verses":[24]}],"verseLabel":"التوبة: 24","question":"لماذا انتقل من القرابات إلى الأموال ثم التجارة ثم المساكن؟","answer":"انتقل من الروابط البشرية إلى المال المملوك، ثم إلى نمائه المتوقع في التجارة، ثم إلى محل الاستقرار؛ فتدرج في دوائر التعلق من الأشخاص إلى أسباب العيش.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص29–30، تحت «براعة الترتيب والترقي في المعاني»","url":""}]},{"id":"s9-151","number":151,"surah":9,"verses":[24],"references":[{"surah":9,"verses":[24]}],"verseLabel":"التوبة: 24","question":"لماذا وصف الأموال بـ﴿اقترفتموها﴾؟","answer":"الاقتراف هو الاكتساب، ووصف الأموال به يبرز تعلق النفس بما حصّلته بسعيها وجهدها. فإذا لم يجز تقديم هذا المال العزيز عليها على محبة الله ورسوله، كان غيره من الأموال أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص28، تحت «دلالة وصف الأموال بالاقتراف»","url":""}]},{"id":"s9-152","number":152,"surah":9,"verses":[24],"references":[{"surah":9,"verses":[24]}],"verseLabel":"التوبة: 24","question":"لماذا وُصفت التجارة بقوله: ﴿تخشون كسادها﴾؟","answer":"لأن التجارة متعلقة بتقلبات السوق بين الرواج والكساد؛ فذكر خشية كسادها يصور موطن التعلق والقلق لدى أصحابها. والسياق ينبه إلى ألا يحملهم هذا الخوف على تقديمها على طاعة الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص29، تحت «دلالة الأوصاف للأموال والتجارة والمساكن»","url":""}]},{"id":"s9-153","number":153,"surah":9,"verses":[24],"references":[{"surah":9,"verses":[24]}],"verseLabel":"التوبة: 24","question":"ما مناسبة وصف المساكن بقوله: ﴿ترضونها﴾؟","answer":"لأن المسكن تتحقق به غاية الاطمئنان والاستقرار، فيرضى به صاحبه إذا لبى حاجته. وذكر هذا الرضا يستحضر قوة تعلقه به، لينبه إلى ألا يشغله عن الطاعة ومقتضى الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص29، تحت «دلالة الأوصاف للأموال والتجارة والمساكن»","url":""}]},{"id":"s9-154","number":154,"surah":9,"verses":[24],"references":[{"surah":9,"verses":[24]}],"verseLabel":"التوبة: 24","question":"ما سرّ ذكر النفير مع محبة الله ورسوله؟","answer":"من توجيهات الآية أن المحبة تظهر في امتثال أمر الله ورسوله، فخُص الجهاد بالذكر تعظيمًا لشأنه وبيانًا لما فيه من بذل المال والنفس. وعلى إبقاء المحبة على ظاهرها، يكون الجهاد من ثمراتها ودلائل صدقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص32، تحت «سر ذكر النفير مع محبة الله ورسوله»","url":""}]},{"id":"s9-155","number":155,"surah":9,"verses":[24],"references":[{"surah":9,"verses":[24]}],"verseLabel":"التوبة: 24","question":"ما سرّ التعبير في قوله تعالى: ﴿فتربصوا حتى يأتي الله بأمره﴾، ولم يصرح بالعقوبة؟","answer":"﴿فتربصوا﴾ تهديد يترك العقوبة مبهمة، فيذهب الوهم في صورها ويزيد هول انتظار أمر الله الذي لا يرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص33، تحت «دلالة الأمر في قوله فتربصوا»","url":""}]},{"id":"s9-156","number":156,"surah":9,"verses":[24],"references":[{"surah":9,"verses":[24]}],"verseLabel":"التوبة: 24","question":"لماذا ختم بـ﴿والله لا يهدي القوم الفاسقين﴾؟","answer":"تقديم المحبوبات على الله ورسوله والجهاد خروج عن مقتضى الطاعة، فناسب وصف الفسق، وعدم الهداية نتيجة الإصرار عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص35، تحت «بلاغة التذييل»","url":""}]},{"id":"s9-157","number":157,"surah":9,"verses":[25],"references":[{"surah":9,"verses":[25]}],"verseLabel":"التوبة: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿لقد نصركم الله في مواطن كثيرة﴾ قبل ذكر هزيمة أول المعركة في حنين؟","answer":"قُدمت المواطن الكثيرة لتذكيرهم بأن النصر عادة فضل من الله لا ثمرة العدد، ثم ذكرت عثرة حنين لتصحح لحظة الاغترار بالكثرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص36، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-158","number":158,"surah":9,"verses":[25],"references":[{"surah":9,"verses":[25]}],"verseLabel":"التوبة: 25","question":"ما وجه التنويع بين ذكر المكان في ﴿مواطن كثيرة﴾ والزمان في ﴿يوم حنين﴾؟","answer":"ذُكر المكان أولًا والزمان ثانيًا، وكل منهما يدل على الآخر؛ فالمواطن تستلزم أيام القتال، ويوم حنين يستحضر موطنه. وفي هذا التنويع إيجاز، وإيماء إلى ما وقع في ذلك اليوم من هزيمة في أول الأمر ثم نصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص40، تحت «براعة تلوين الكلام»","url":""}]},{"id":"s9-159","number":159,"surah":9,"verses":[25],"references":[{"surah":9,"verses":[25]}],"verseLabel":"التوبة: 25","question":"لماذا خُص يوم حنين بالذكر بعد إجمال المواطن الكثيرة؟","answer":"خُص حنين لأن بدايته كشفت عجز الكثرة حين أعجبتهم، ثم أظهر نهايته عودة النصر بإنزال السكينة؛ فهو شاهد عملي على المقصود.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص40–41، تحت «سر عطف الخاص على العام»","url":""}]},{"id":"s9-160","number":160,"surah":9,"verses":[25],"references":[{"surah":9,"verses":[25]}],"verseLabel":"التوبة: 25","question":"لماذا أُضيف الإعجاب بالكثرة إلى الجماعة كلها؟","answer":"أُضيف الإعجاب إلى الجماعة مع صدوره من بعضهم تعظيمًا لشأنهم، وتنبيهًا إلى أن مثل هذا الاغترار لا ينبغي أن يصدر منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص41، تحت «نكتة إضافة الإعجاب إلى الجميع»","url":""}]},{"id":"s9-712","number":712,"surah":9,"verses":[25],"references":[{"surah":9,"verses":[25]}],"verseLabel":"التوبة: 25","question":"ما دلالة موقع قوله تعالى: ﴿إذ أعجبتكم كثرتكم﴾؟","answer":"يحدد الظرف لحظة الخطأ في الاغترار بالقوة العددية ونسيان عون الله، فيجعلها موضع العبرة من قصة حنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص41، تحت «دلالة موقع قوله إذ أعجبتكم كثرتكم»","url":""}]},{"id":"s9-161","number":161,"surah":9,"verses":[25],"references":[{"surah":9,"verses":[25]}],"verseLabel":"التوبة: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿فلم تغن عنكم شيئًا﴾، ونكّر ﴿شيئًا﴾؟","answer":"﴿شيئًا﴾ في سياق النفي تعم أقل إغناء؛ فلم تدفع الكثرة عنهم ضررًا ولا حققت نصرًا مستقلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص42، تحت «دلالة تنكير لفظ شيئًا»","url":""}]},{"id":"s9-162","number":162,"surah":9,"verses":[25],"references":[{"surah":9,"verses":[25]}],"verseLabel":"التوبة: 25","question":"ما الصورة في قوله: ﴿وضاقت عليكم الأرض بما رحبت﴾؟","answer":"صوّر شدة الحيرة والخوف بأن الأرض الواسعة ضاقت بهم فلم يجدوا مهربًا؛ فجمع بين حقيقة سعتها وشعورهم بانغلاقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص43، تحت «بلاغة الاستعارة»","url":""}]},{"id":"s9-163","number":163,"surah":9,"verses":[25],"references":[{"surah":9,"verses":[25]}],"verseLabel":"التوبة: 25","question":"لماذا جمع بين ﴿وليتم﴾ و﴿مدبرين﴾؟","answer":"﴿وليتم﴾ يثبت فعل الانصراف، و﴿مدبرين﴾ يصور هيئتهم وهم يعطون العدو أدبارهم؛ فالثاني يؤكد الأول ويجسده.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص44، تحت «سر التعبير بالإدبار بعد ذكر التولي»","url":""}]},{"id":"s9-164","number":164,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"ما دلالة إسناد إنزال السكينة إلى اسم الله صراحة؟","answer":"يبين إسناد إنزال السكينة إلى الله أنها عطية منه، خارجة عما يستقل به تدبير الناس وأسبابهم الظاهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص47، تحت «دلالة تعريف المسند إليه بالعلمية»","url":""}]},{"id":"s9-713","number":713,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"ما دلالة إضافة السكينة إلى الله في قوله تعالى: ﴿سكينته﴾؟","answer":"تشرف الإضافة السكينة وتعظم شأنها، وتبين أنها طمأنينة خاصة يهبها الله لتثبيت القلوب في الشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص48، تحت «دلالة الإضافة في سكينته»","url":""}]},{"id":"s9-165","number":165,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"لماذا قيل: ﴿على رسوله وعلى المؤمنين﴾ ولم يقل: «عليكم»؟","answer":"لأن الجماعة المخاطبة قد خالطها منافقون؛ فعدل عن الضمير إلى الاسمين الظاهرين حتى لا يدخل في الثناء كل من شمله الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص48، تحت «بلاغة الإظهار في محل الإضمار»","url":""}]},{"id":"s9-714","number":714,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"ما نكتة ذكر الرسول صراحة عند إنزال السكينة؟","answer":"ذُكر الرسول تعظيمًا لمنزلته وزيادة في الامتنان بتثبيته بالسكينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص49، تحت «نكتة ذكر الرسول»","url":""}]},{"id":"s9-715","number":715,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"ما دلالة وصف من نزلت عليهم السكينة بالمؤمنين؟","answer":"في وصفهم بالإيمان تنويه بما يقتضيه الإيمان من الثبات وقبول الطمأنينة، وتمييز لهم ممن خالط الصف من المنافقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص50، تحت «دلالة التعبير بوصف الإيمان»","url":""}]},{"id":"s9-166","number":166,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"ما دلالة تنكير ﴿جنودًا﴾ وجمعها؟","answer":"يفيد تنكير الجنود وجمعها تعظيم شأنها وتكثيرها، ويوسع ما يدخل في جنود الله من أسباب النصر الغيبية.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص51، تحت «دلالة تنكير جنودًا وجمعها»","url":""}]},{"id":"s9-716","number":716,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"ما دلالة تقييد الجنود بقوله تعالى: ﴿لم تروها﴾؟","answer":"يبرز القيد أن النصر جاء بمدد غيبي لم تقع عليه أبصار المؤمنين، فالمقصود أثر القوة التي أيدهم الله بها لا مجرد تسميتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص51، تحت «دلالة جملة لم تروها»","url":""}]},{"id":"s9-167","number":167,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"ما مناسبة الجمع بين إنزال السكينة وإنزال الجنود؟","answer":"السكينة مدد للقلوب من الداخل، والجنود مدد للموقف من الخارج؛ فجمع تثبيت النفس وتقوية الصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص45، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-168","number":168,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"ما سرّ التعبير بقوله تعالى: ﴿وعذب الذين كفروا﴾؟","answer":"تجعل صلة الكفر علة ظاهرة لاستحقاق العذاب، وتبين أن النصر لم يكن نجاة للمؤمنين فقط، بل جزاءً للعدو على كفره وعدوانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص52، تحت «سر التعبير بالاسم الموصول»","url":""}]},{"id":"s9-169","number":169,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"ما سرّ الإشارة إلى العذاب في قوله تعالى: ﴿وذلك جزاء الكافرين﴾؟","answer":"يربط اسم الإشارة الجزاء بالعذاب المتقدم، ويستحضره مشاهدًا مع تعظيم شأنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص53، تحت «سر تعريف المسند إليه بالإشارة»","url":""}]},{"id":"s9-717","number":717,"surah":9,"verses":[26],"references":[{"surah":9,"verses":[26]}],"verseLabel":"التوبة: 26","question":"ما وجه التذييل في قوله تعالى: ﴿وذلك جزاء الكافرين﴾؟","answer":"يقرر التذييل أن العذاب جزاء جنس الكافرين، لا حادثة عارضة بلا حكم أو علة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص53، تحت «بلاغة التذييل»","url":""}]},{"id":"s9-170","number":170,"surah":9,"verses":[27],"references":[{"surah":9,"verses":[27]}],"verseLabel":"التوبة: 27","question":"لماذا جاء بعد عذاب الكافرين مباشرة: ﴿ثم يتوب الله من بعد ذلك على من يشاء﴾؟","answer":"جاءت التوبة بعد العذاب لتبين أن الجزاء الدنيوي لا يغلق باب الهداية، وأن من بقي منهم قد يرجع فيقبله الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص55، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-171","number":171,"surah":9,"verses":[27],"references":[{"surah":9,"verses":[27]}],"verseLabel":"التوبة: 27","question":"لماذا استُعملت ﴿ثم﴾ قبل التوبة؟","answer":"﴿ثم﴾ تفيد تراخي رتبة التوبة عن مشهد القتال والعذاب وانتقال السياق إلى طور جديد، وقد يقع أثر الهداية بعد انكشاف الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص56، تحت «دلالة ثم في الآية»","url":""}]},{"id":"s9-172","number":172,"surah":9,"verses":[27],"references":[{"surah":9,"verses":[27]}],"verseLabel":"التوبة: 27","question":"ما دلالة ﴿من﴾ في قوله تعالى: ﴿من بعد ذلك﴾؟","answer":"تؤكد ﴿من﴾ ابتداء إمكان التوبة بعد تلك الأحداث الشديدة، فلا يغلق العذاب الدنيوي باب الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص58، تحت «دلالة من في الآية»","url":""}]},{"id":"s9-718","number":718,"surah":9,"verses":[27],"references":[{"surah":9,"verses":[27]}],"verseLabel":"التوبة: 27","question":"ما نكتة التعبير باسم الإشارة ﴿ذلك﴾ عن العذاب؟","answer":"يستحضر اسم الإشارة العذاب المتقدم كاملًا قبل فتح باب التوبة بعده، فيبرز سعة الرحمة مع شدة ما سبق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص59، تحت «نكتة التعبير باسم الإشارة ذلك عن العذاب»","url":""}]},{"id":"s9-173","number":173,"surah":9,"verses":[27],"references":[{"surah":9,"verses":[27]}],"verseLabel":"التوبة: 27","question":"لماذا ختم بـ﴿والله غفور رحيم﴾؟","answer":"﴿غفور﴾ يمحو ما سبق من الكفر والعداء، و﴿رحيم﴾ يتفضل على التائب بعد المغفرة؛ فناسبا فتح الباب بعد العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص62، تحت «دلالة ختم الآية باسمي غفور رحيم»","url":""}]},{"id":"s9-719","number":719,"surah":9,"verses":[27],"references":[{"surah":9,"verses":[27]}],"verseLabel":"التوبة: 27","question":"ما الفرق بين المغفرة والرحمة في ختام الآية؟","answer":"المغفرة تمحو ما سبق من الكفر والعداء، والرحمة تتفضل على التائب بعد محو ذنبه؛ فاجتمع رفع الضرر وإيصال الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص62، تحت «الفروق المعجمية: المغفرة والرحمة»","url":""}]},{"id":"s9-174","number":174,"surah":9,"verses":[28],"references":[{"surah":9,"verses":[28]}],"verseLabel":"التوبة: 28","question":"لماذا وصف المشركين بأنهم ﴿نجس﴾ بالمصدر المفرد، لا «أنجاس»؟","answer":"أخبر بالمصدر المفرد ﴿نجس﴾ للمبالغة، كأن حقيقتهم عين النجاسة المعنوية، والمصدر لا يثنى ولا يجمع فاستوى فيه الجمع والمفرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص72، تحت «دلالة التعبير بالمصدر نجس بصيغة المفرد»","url":""}]},{"id":"s9-175","number":175,"surah":9,"verses":[28],"references":[{"surah":9,"verses":[28]}],"verseLabel":"التوبة: 28","question":"لماذا رُتّب منعهم من المسجد الحرام على وصف النجاسة بالفاء؟","answer":"الفاء تفيد أن منعهم مترتب على وصف الشرك والنجاسة المعنوية، فالحكم ليس لمجرد جنس أو قومية بل لعلة مذكورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص74–75، تحت «دلالة الفاء في قوله فلا يقربوا»","url":""}]},{"id":"s9-176","number":176,"surah":9,"verses":[28],"references":[{"surah":9,"verses":[28]}],"verseLabel":"التوبة: 28","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا يقربوا المسجد الحرام﴾، دون أن يقال: «فلا يدخلوه»؟","answer":"النهي عن القرب أبلغ، ويوافق سياق منعهم من الحج والعمرة. فبعض المناسك يقع خارج بناء المسجد، كالوقوف بعرفة؛ ولذلك يتسع التعبير بالمقاربة لما لا يؤديه الاقتصار على دخول البناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص74، تحت «سر التعبير بلفظ فلا يقربوا دون فلا يدخلوا»","url":""}]},{"id":"s9-177","number":177,"surah":9,"verses":[28],"references":[{"surah":9,"verses":[28]}],"verseLabel":"التوبة: 28","question":"ما دلالة إضافة العام إلى المشركين في قوله تعالى: ﴿بعد عامهم هذا﴾؟","answer":"تستحضر الإضافة اختصاص ذلك العام بهم بوصفه آخر عهدهم بالمشاركة في موسم الحج، مع استمرار المنع بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص78، تحت «دلالة إضافة لفظ عام إلى الضمير العائد على المشركين»","url":""}]},{"id":"s9-178","number":178,"surah":9,"verses":[28],"references":[{"surah":9,"verses":[28]}],"verseLabel":"التوبة: 28","question":"لماذا واجه خوف الفقر صراحة: ﴿وإن خفتم عيلة﴾؟","answer":"صرح بالخوف لأنه كان شبهة واقعية: انقطاع تجارة المشركين قد يسبب الفقر؛ فواجهها الوحي بوعد يحرر الطاعة من ضغط المصلحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص79، تحت «سر التعبير بالخوف»","url":""}]},{"id":"s9-179","number":179,"surah":9,"verses":[28],"references":[{"surah":9,"verses":[28]}],"verseLabel":"التوبة: 28","question":"لماذا جاء الوعد بالإغناء بلفظ ﴿فسوف يغنيكم الله﴾؟","answer":"تربط الفاء الجواب بالشرط، وتؤكد ﴿سوف﴾ حصول الإغناء في المستقبل. وفي اختيارها مناسبة لما يتحقق من أسبابه مع الزمن، فيطمئن المؤمن إلى الوعد دون اشتراط وقوعه في اللحظة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص80، تحت «سر اقتران الجواب بلفظة فسوف»","url":""}]},{"id":"s9-180","number":180,"surah":9,"verses":[28],"references":[{"surah":9,"verses":[28]}],"verseLabel":"التوبة: 28","question":"لماذا قيد الإغناء بقوله: ﴿إن شاء﴾؟","answer":"قُيد بالمشيئة لتبقى القلوب معلقة بالله لا بالوعد المادي وحده، ولأن كيفية الغنى وزمانه ومقداره تابعة لحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص84، تحت «نكتة تعليق الإغناء بالمشيئة»","url":""}]},{"id":"s9-181","number":181,"surah":9,"verses":[28],"references":[{"surah":9,"verses":[28]}],"verseLabel":"التوبة: 28","question":"ما مناسبة ختم وعد الإغناء بقوله: ﴿إن الله عليم حكيم﴾؟","answer":"يثبت الختام سعة علم الله بأحوال عباده ومصالحهم، وحكمته في تدبير أرزاقهم ووضع الأمور مواضعها. وفيه تقوية لليقين بوعد الإغناء بعد انقطاع بعض أسبابه الظاهرة، وإزالة لما قد يعرض في القلوب من تردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص86، تحت «براعة التذييل»","url":""}]},{"id":"s9-182","number":182,"surah":9,"verses":[29],"references":[{"surah":9,"verses":[29]}],"verseLabel":"التوبة: 29","question":"لماذا عُبر بالموصول ثم فُصّلت صلته في أوصاف المقاتَلين؟","answer":"فصل الأوصاف لإظهار تعدد أصول مخالفتهم التي تبرر الحكم: خلل الاعتقاد بالبدء والمعاد، وخلل التشريع، وخلل الانقياد لدين الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص91، تحت «نكتة التعبير بالموصول وصلته»","url":""}]},{"id":"s9-183","number":183,"surah":9,"verses":[29],"references":[{"surah":9,"verses":[29]}],"verseLabel":"التوبة: 29","question":"ما دلالة إضافة الرسول إلى الله في قوله تعالى: ﴿ما حرم الله ورسوله﴾؟","answer":"تفيد الإضافة تشريف الرسول وتأكيد صدقه في التبليغ، وتقرر أن ما يحرمه مأذون فيه من الله، فتكون طاعته من طاعة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص98، تحت «دلالة الإضافة»","url":""}]},{"id":"s9-184","number":184,"surah":9,"verses":[29],"references":[{"surah":9,"verses":[29]}],"verseLabel":"التوبة: 29","question":"ما سرّ التعبير بقوله تعالى: ﴿ولا يدينون﴾؟","answer":"الدين هنا بمعنى الانقياد والطاعة؛ فالتعبير يكشف أنهم لا يخضعون للمنهج الحق اعتقادًا وحكمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص99، تحت «سر التعبير بقوله لا يدينون»","url":""}]},{"id":"s9-720","number":720,"surah":9,"verses":[29],"references":[{"surah":9,"verses":[29]}],"verseLabel":"التوبة: 29","question":"ما نكتة إضافة الدين إلى الحق في قوله تعالى: ﴿دين الحق﴾؟","answer":"تصف الإضافة المنهج بأنه الحق الثابت الذي يجب أن يخضع له الإنسان، فلا يكون المراد مجرد اسم طائفة أو شعار.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص100، تحت «نكتة إضافة الدين إلى الحق»","url":""}]},{"id":"s9-186","number":186,"surah":9,"verses":[29],"references":[{"surah":9,"verses":[29]}],"verseLabel":"التوبة: 29","question":"لماذا عبّر عن أداء الجزية بـ﴿يعطوا﴾ دون «يؤتوا»؟","answer":"يبين المصدر أن الإعطاء قد يكون عن طيب نفس وقد يكون عن غير رضا، فناسب وصف أداء الجزية في هذا السياق. أما الإيتاء فيستعمل في المقامات التي يكون فيها المعطى ذا شأن وتظهر معه دلالة العطاء عن رغبة، كالزكاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص103، تحت «سر التعبير بلفظ الإعطاء دون الإيتاء»","url":""}]},{"id":"s9-187","number":187,"surah":9,"verses":[29],"references":[{"surah":9,"verses":[29]}],"verseLabel":"التوبة: 29","question":"ما وجه المجاز المرسل في قوله تعالى: ﴿عن يد﴾؟","answer":"من توجيهاته أن اليد مجاز عن القوة، أي يؤدون الجزية عن انقياد للسلطان، أو عن النعمة بما يترتب على قبولها من حقن الدماء والحماية.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص104، تحت «بلاغة المجاز المرسل»","url":""}]},{"id":"s9-721","number":721,"surah":9,"verses":[29],"references":[{"surah":9,"verses":[29]}],"verseLabel":"التوبة: 29","question":"ما وجه الكناية في قوله تعالى: ﴿عن يد﴾؟","answer":"كُنّي باليد عن مباشرة الأداء بأنفسهم وما يصاحبها من الانقياد، بدل الاكتفاء بذكر دفع الجزية مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص104، تحت «بلاغة الكناية في قوله عن يد»","url":""}]},{"id":"s9-188","number":188,"surah":9,"verses":[29],"references":[{"surah":9,"verses":[29]}],"verseLabel":"التوبة: 29","question":"لماذا ختم بـ﴿وهم صاغرون﴾؟","answer":"﴿وهم صاغرون﴾ تبين خضوعهم لحكم الدولة وامتناعهم عن محاربتها، فلا تكون الجزية مالًا بلا اعتراف بسلطان النظام العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص105، تحت «دلالة إيراد جملة الحال اسمية»","url":""}]},{"id":"s9-189","number":189,"surah":9,"verses":[30],"references":[{"surah":9,"verses":[30]}],"verseLabel":"التوبة: 30","question":"لماذا عبّر عن قول طائفة من اليهود بصيغة الجنس: ﴿وقالت اليهود عزير ابن الله﴾؟","answer":"يذكر المصدر وجهين: أن يكون الإسناد إلى الجماعة والمراد القائلون منهم، من إطلاق العام وإرادة بعض أفراده؛ أو أن القائل بعضهم والباقين لم ينكروا مقالته فجرى الإسناد عليهم. فالعبارة لا تقتضي أن كل فرد قالها بنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص110، تحت «دلالة إسناد القول إلى عموم اليهود»","url":""}]},{"id":"s9-190","number":190,"surah":9,"verses":[30],"references":[{"surah":9,"verses":[30]}],"verseLabel":"التوبة: 30","question":"ما دلالة الواو في قوله تعالى: ﴿وقالت اليهود﴾؟","answer":"تجمع الواو قول اليهود في عزير وقول النصارى في المسيح؛ لأنهما يشتركان في رفع بشر إلى البنوة الإلهية مع اختلاف الشخص والطائفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص109، تحت «دلالة الواو في قوله وقالت اليهود»","url":""}]},{"id":"s9-191","number":191,"surah":9,"verses":[30],"references":[{"surah":9,"verses":[30]}],"verseLabel":"التوبة: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك قولهم بأفواههم﴾ مع أن كل قول يكون بالفم؟","answer":"﴿بأفواههم﴾ يقرر أنه قول لا يقوم عليه برهان ولا حقيقة وراء الألفاظ، ويشعر بأنه مجرد جرأة لسانية.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص114، تحت «دلالة التعبير بالأفواه»","url":""}]},{"id":"s9-192","number":192,"surah":9,"verses":[30],"references":[{"surah":9,"verses":[30]}],"verseLabel":"التوبة: 30","question":"ما سرّ التعبير بقوله يضاهئون قول الذين؟","answer":"المضاهاة المشابهة؛ فقولهم يحاكي مقالات من سبقهم في نسبة الولد إلى الله أو إشراك غيره في العبادة. وفيه بيان أنهم اتبعوا أقوالًا موروثة من الضلال، وتركوا ما جاء به الهدى من توحيد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص115، تحت «سر التعبير بقوله يضاهئون قول الذين»","url":""}]},{"id":"s9-193","number":193,"surah":9,"verses":[30],"references":[{"surah":9,"verses":[30]}],"verseLabel":"التوبة: 30","question":"لماذا جاء الدعاء عليهم بصيغة الخبر: ﴿قاتلهم الله﴾؟","answer":"الجملة خبرية في صورتها، واستعملت للدعاء عليهم والتعجيب من شناعة مقالتهم. وصيغة المفاعلة للمبالغة في هذا الدعاء، فهي تقوي الذم والإنكار ولا يراد بها الإخبار عن قتال بشري.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص117–118، تحت «دلالة الخبر في قوله قاتلهم الله»","url":""}]},{"id":"s9-194","number":194,"surah":9,"verses":[30],"references":[{"surah":9,"verses":[30]}],"verseLabel":"التوبة: 30","question":"ما دلالة الاستفهام في قوله تعالى: ﴿أنى يؤفكون﴾؟","answer":"خرج الاستفهام للتعجب والإنكار من الجهة التي يصرفون إليها عن الحق مع وضوح بطلان قولهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص118، تحت «دلالة الاستفهام»","url":""}]},{"id":"s9-722","number":722,"surah":9,"verses":[30],"references":[{"surah":9,"verses":[30]}],"verseLabel":"التوبة: 30","question":"لماذا قيل: ﴿يؤفكون﴾ دون «يصرفون»؟","answer":"يصور ﴿يؤفكون﴾ شدة انقلابهم عن الدليل وصرفهم عن الحق، فهو أبلغ من مجرد ذكر الصرف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص118، تحت «سر التعبير بلفظ يؤفكون دون يصرفون»","url":""}]},{"id":"s9-195","number":195,"surah":9,"verses":[31],"references":[{"surah":9,"verses":[31]}],"verseLabel":"التوبة: 31","question":"كيف اتخذ أهل الكتاب أحبارهم ورهبانهم أربابًا مع أنهم لم يسجدوا لهم؟","answer":"اتخذوهم أربابًا بطاعتهم في تحليل الحرام وتحريم الحلال وتقديم أقوالهم على حكم الله، لا بالسجود لهم؛ فالربوبية هنا ربوبية تشريع وطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص126، تحت «سر التعبير بلفظ أربابًا»","url":""}]},{"id":"s9-196","number":196,"surah":9,"verses":[31],"references":[{"surah":9,"verses":[31]}],"verseLabel":"التوبة: 31","question":"لماذا جمع بين ﴿أحبارهم ورهبانهم﴾؟","answer":"الأحبار علماء اليهود، والرهبان عباد النصارى؛ فالجمع يستوعب القيادات الدينية العلمية والتعبدية التي مُنحت حق التشريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص124، تحت «بلاغة اللف والنشر»","url":""}]},{"id":"s9-197","number":197,"surah":9,"verses":[31],"references":[{"surah":9,"verses":[31]}],"verseLabel":"التوبة: 31","question":"ما وجه التعبير عن الأحبار والرهبان بلفظ ﴿أربابًا﴾؟","answer":"لأن أتباعهم منحوا أقوالهم سلطة التحليل والتحريم، وقدموها على ما أنزل الله؛ فشُبهت منزلتهم في هذا الاتباع بمنزلة الأرباب. والتعبير يصور غلو الأتباع في تعظيمهم وتسليمهم أمر الدين إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص126، تحت «سر التعبير بلفظ أربابًا»","url":""}]},{"id":"s9-198","number":198,"surah":9,"verses":[31],"references":[{"surah":9,"verses":[31]}],"verseLabel":"التوبة: 31","question":"لماذا عطف ﴿والمسيح ابن مريم﴾ على الأحبار والرهبان مع اختلاف طريقة اتخاذه ربًّا؟","answer":"عُطف المسيح لأنه اتخذ ربًا بالاعتقاد في ذاته وعبادته، بينما اتخذ الأحبار والرهبان أربابًا بالطاعة التشريعية؛ فجمع صورتي الانحراف مع اختلافهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص127، تحت «دلالة تخصيص عيسى بالذكر»","url":""}]},{"id":"s9-199","number":199,"surah":9,"verses":[31],"references":[{"surah":9,"verses":[31]}],"verseLabel":"التوبة: 31","question":"لماذا وصف المسيح بـ﴿ابن مريم﴾ في مقام إنكار ألوهيته؟","answer":"﴿ابن مريم﴾ يذكر بنسبه البشري وولادته من أم، فينقض دعوى الألوهية من داخل الوصف ويؤكد عبوديته وبشريته.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص127–128، تحت «دلالة نسبة عيسى إلى أمه»","url":""}]},{"id":"s9-200","number":200,"surah":9,"verses":[31],"references":[{"surah":9,"verses":[31]}],"verseLabel":"التوبة: 31","question":"ما دلالة القصر في قوله تعالى: ﴿وما أمروا إلا ليعبدوا إلهًا واحدًا﴾؟","answer":"القصر بـ﴿ما... إلا﴾ يرد اتخاذ الأرباب المتعددة، ويقرر أن أصل الأمر المنزل عليهم عبادة معبود واحد لا شريك له؛ فناقض فعلهم حقيقة التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص128، تحت «دلالة القصر»","url":""}]},{"id":"s9-201","number":201,"surah":9,"verses":[31],"references":[{"surah":9,"verses":[31]}],"verseLabel":"التوبة: 31","question":"لماذا ختم بـ﴿سبحانه عما يشركون﴾؟","answer":"التسبيح تنزيه لله عن الشركاء والبنوة وعن أن يشاركه بشر في حق التشريع والعبادة، فجاء خاتمة تبطل ما سبق من اتخاذ الأرباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص130، تحت «علة فصل قوله سبحانه عما قبله»","url":""}]},{"id":"s9-202","number":202,"surah":9,"verses":[32],"references":[{"surah":9,"verses":[32]}],"verseLabel":"التوبة: 32","question":"ما غرض استعارة النور للدين في قوله تعالى: ﴿نور الله﴾؟","answer":"شُبه الدين بالنور لما فيه من هداية وظهور وكشف لطريق الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص135، تحت «غرض الاستعارة التصريحية»","url":""}]},{"id":"s9-723","number":723,"surah":9,"verses":[32],"references":[{"surah":9,"verses":[32]}],"verseLabel":"التوبة: 32","question":"ما وجه براعة الاستعارة في تصوير إطفاء نور الله بالأفواه؟","answer":"شُبه طعنهم في الدين بالنفخ لإطفاء النور؛ فالصورة تسخر من ضعف وسيلتهم أمام نور الله الذي لا يطفأ.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص136، تحت «براعة الاستعارة في مجموع التركيب»","url":""}]},{"id":"s9-203","number":203,"surah":9,"verses":[32],"references":[{"surah":9,"verses":[32]}],"verseLabel":"التوبة: 32","question":"لماذا خص الأفواه وسيلةً لإطفاء النور؟","answer":"خُصت الأفواه لأن حربهم قائمة على الأقوال المفتراة والطعن والتكذيب، ولتصوير عجزها: أفواه تنفخ في نور لا تطفئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص137، تحت «دلالة تقييد الإطفاء بالأفواه»","url":""}]},{"id":"s9-204","number":204,"surah":9,"verses":[32],"references":[{"surah":9,"verses":[32]}],"verseLabel":"التوبة: 32","question":"كيف جاء الاستثناء في قوله: ﴿ويأبى الله إلا أن يتم نوره﴾ مع أن ظاهر الكلام مثبت؟","answer":"الإباء يتضمن معنى النفي والمنع؛ فالمعنى أن الله لا يرضى في هذا المقام إلا إتمام نوره. لذلك صح الاستثناء، وجاء الفعل ﴿يأبى﴾ أقوى من مجرد نفي الإرادة في تصوير الامتناع القاطع عما يريدونه من الإطفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص138، تحت «براعة التعبير بالإباء دون نفي الإرادة»","url":""}]},{"id":"s9-205","number":205,"surah":9,"verses":[32],"references":[{"surah":9,"verses":[32]}],"verseLabel":"التوبة: 32","question":"لماذا اختير ﴿يتم نوره﴾ لا «يحفظ نوره»؟","answer":"الإتمام أبلغ من مجرد الإبقاء؛ لأنه يتضمن زيادة ظهور النور وانتشاره وعلو شأنه. والمراد هنا إظهار الدين وتأييده، لا أن نور الله كان ناقصًا في نفسه فاحتاج إلى استكمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص140، تحت «دلالة التعبير بالإتمام دون الإبقاء»","url":""}]},{"id":"s9-206","number":206,"surah":9,"verses":[32],"references":[{"surah":9,"verses":[32]}],"verseLabel":"التوبة: 32","question":"لماذا ختم بـ﴿ولو كره الكافرون﴾؟","answer":"الخاتمة تقرر أن كراهة الكافرين لا تغير وعد الله ولا تمنع إتمام نوره، وفيها مقابلة بين إرادتهم العاجزة وإرادته النافذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص143–144، تحت «دلالة الشرط بـ«لو» وأثرها في ربط الكلام؛ معنى الواو ودلالته»","url":""}]},{"id":"s9-207","number":207,"surah":9,"verses":[33],"references":[{"surah":9,"verses":[33]}],"verseLabel":"التوبة: 33","question":"ما سرّ التعبير في قوله تعالى: ﴿هو الذي أرسل رسوله﴾ بعد ذكر محاولة إطفاء النور؟","answer":"بعد تصوير محاولة الإطفاء، بين أن صاحب النور هو الذي أرسل رسوله بالهدى؛ فالإرسال الإلهي ضمان بقاء الرسالة وظهورها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص147، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s9-208","number":208,"surah":9,"verses":[33],"references":[{"surah":9,"verses":[33]}],"verseLabel":"التوبة: 33","question":"لماذا جمع بين ﴿الهدى ودين الحق﴾؟","answer":"الهدى ما جاء به الرسول من علم ودلالة، ودين الحق هو المنهج العملي والاعتقادي الثابت؛ فجمع نور المعرفة ونظام الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص151، تحت «معنى العطف»","url":""}]},{"id":"s9-209","number":209,"surah":9,"verses":[33],"references":[{"surah":9,"verses":[33]}],"verseLabel":"التوبة: 33","question":"ما دلالة التعريف والإفراد في قوله تعالى: ﴿الدين كله﴾؟","answer":"أُفرد الدين وعُرّف باعتبار جنس الملل كلها أو حقيقة الدين المخالف، فشمل كل ما عدا دين الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص155، تحت «دلالة أل في قوله الدين كله»","url":""}]},{"id":"s9-724","number":724,"surah":9,"verses":[33],"references":[{"surah":9,"verses":[33]}],"verseLabel":"التوبة: 33","question":"ما دلالة التوكيد بلفظ ﴿كله﴾؟","answer":"يؤكد لفظ ﴿كله﴾ استغراق كل ما عدا دين الحق في حكم الظهور والغلبة، فلا يترك بعض الجنس خارجًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص155، تحت «دلالة التوكيد وأثره في المعنى»","url":""}]},{"id":"s9-210","number":210,"surah":9,"verses":[33],"references":[{"surah":9,"verses":[33]}],"verseLabel":"التوبة: 33","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿ولو كره المشركون﴾، وقال في الآية السابقة: ﴿ولو كره الكافرون﴾؟","answer":"من وجوه المناسبة أن الكفر يتصل بمعنى الستر والإطفاء، فناسب محاولة إطفاء النور وإتمامه رغم معارضته. أما الشرك فذُكر عند إظهار دين التوحيد، مع استحضار من نازعوا الرسول في إعلانه؛ فجاء كل وصف ملائمًا لسياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص157، تحت «علة ذكر المشركين واختصاص الآية السابقة بذكر الكافرين»","url":""}]},{"id":"s9-211","number":211,"surah":9,"verses":[34],"references":[{"surah":9,"verses":[34]}],"verseLabel":"التوبة: 34","question":"ما موقع نداء المؤمنين قبل التحذير من الأحبار والرهبان؟","answer":"ينقل النداء الكلام من كشف انحراف أهل الكتاب إلى تحذير المؤمنين منه، فيوقظهم قبل بيان استغلال القيادات الدينية.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص160، تحت «موقع جملة النداء مما قبلها»","url":""}]},{"id":"s9-725","number":725,"surah":9,"verses":[34],"references":[{"surah":9,"verses":[34]}],"verseLabel":"التوبة: 34","question":"ما نكتة تخصيص المؤمنين بالخطاب؟","answer":"يستنهض وصف الإيمان مقتضى العقيدة في حماية الدين من الاستغلال، ويميز المخاطبين عن أصحاب الانحراف المذكور.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص162، تحت «نكتة تخصيص المؤمنين بالخطاب»","url":""}]},{"id":"s9-212","number":212,"surah":9,"verses":[34],"references":[{"surah":9,"verses":[34]}],"verseLabel":"التوبة: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿إن كثيرًا من الأحبار والرهبان﴾ ولم يعمم؟","answer":"قال ﴿كثيرًا﴾ إنصافًا ومنعًا لتعميم الذم على الجميع؛ فالفساد وقع من عدد كبير لا من كل حبر وراهب.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص163–164، تحت «علة إسناد الحكم إلى كثير من الأحبار والرهبان دون جميعهم»","url":""}]},{"id":"s9-213","number":213,"surah":9,"verses":[34],"references":[{"surah":9,"verses":[34]}],"verseLabel":"التوبة: 34","question":"لماذا عبّر عن أخذ الأموال بالباطل بقوله: ﴿ليأكلون أموال الناس﴾؟","answer":"عُبر بالأكل عن الأخذ والاستيلاء والانتفاع؛ لأن الأكل من أبرز مقاصد المال، فهو مجاز مرسل على أحد التوجيهات. وفيه أيضًا تصوير لشدة حرصهم وابتلاعهم حقوق الناس، وذكر المصدر وجهًا تمثيليًا يشبه أخذهم الحرام بمن يأكل ما لا يميز نفعه من ضرره.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص165، تحت «بلاغة الإخبار عنهم بلفظ الأكل»","url":""}]},{"id":"s9-214","number":214,"surah":9,"verses":[34],"references":[{"surah":9,"verses":[34]}],"verseLabel":"التوبة: 34","question":"لماذا جمع بين أكل الأموال والصد عن سبيل الله؟","answer":"جمعا لأن فسادهم مزدوج: يستغلون الدين لتحصيل المال لأنفسهم، ثم يمنعون الناس من طريق الله حفاظًا على نفوذهم ومكاسبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص169، تحت «دلالة عطف ويصدون على ما قبلها»","url":""}]},{"id":"s9-215","number":215,"surah":9,"verses":[34],"references":[{"surah":9,"verses":[34]}],"verseLabel":"التوبة: 34","question":"لماذا جمع الذهب والفضة ثم أعاد عليهما ضمير المفرد في ﴿ولا ينفقونها﴾؟","answer":"من توجيهاته أن الضمير يعود إلى الفضة لقربها، ويُفهم حكم الذهب معها؛ أو يعود إلى الأموال والكنوز أو أصناف الذهب والفضة المفهومة من السياق. وعدم تثنيته يدفع توهم أن الوعيد لا يقع إلا على من جمع كِلا النوعين وحبس حقهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص173، تحت «مرجع الضمير في ولا ينفقونها وأثره في المعنى»","url":""}]},{"id":"s9-216","number":216,"surah":9,"verses":[34],"references":[{"surah":9,"verses":[34]}],"verseLabel":"التوبة: 34","question":"لماذا عُبر بـ﴿يكنزون﴾ دون «يجمعون»؟","answer":"الكنز جمع المال وضم بعضه إلى بعض مع إبقائه مدخرًا، فلفظه أدل على صورة الحبس من مطلق الجمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص171، تحت «وجه التعبير بيكنزون دون غيره»","url":""}]},{"id":"s9-726","number":726,"surah":9,"verses":[34],"references":[{"surah":9,"verses":[34]}],"verseLabel":"التوبة: 34","question":"ما دلالة قوله تعالى: ﴿ولا ينفقونها في سبيل الله﴾ على مفهوم المخالفة؟","answer":"تدل الفاصلة على أن الذم متعلق بحبس حق الله وترك الإنفاق الواجب، لا بمجرد الادخار المشروع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص175، تحت «بلاغة جملة الفاصلة في دلالتها على مفهوم المخالفة»","url":""}]},{"id":"s9-217","number":217,"surah":9,"verses":[34],"references":[{"surah":9,"verses":[34]}],"verseLabel":"التوبة: 34","question":"لماذا استعمل ﴿فبشرهم بعذاب أليم﴾ في مقام الوعيد؟","answer":"على الوجه المجازي، هي بشارة تهكمية وُضع فيها خبر العذاب موضع ما يسر، لتأكيد الذم وزيادة الوعيد. فتصير عاقبة الكنوز التي تعلقوا بها ضد ما رجوه منها من النفع والسرور.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص176، تحت «وجه إجراء البشارة على المجاز والحقيقة»","url":""}]},{"id":"s9-218","number":218,"surah":9,"verses":[35],"references":[{"surah":9,"verses":[35]}],"verseLabel":"التوبة: 35","question":"ما دلالة حرف ﴿على﴾ في قوله تعالى: ﴿يوم يحمى عليها﴾؟","answer":"يصور حرف ﴿على﴾ استعلاء الإحماء على الكنوز وشدة حرارتها، فلا يكون المعنى مجرد وجودها في النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص181، تحت «معنى الجار والمجرور ودلالته»","url":""}]},{"id":"s9-727","number":727,"surah":9,"verses":[35],"references":[{"surah":9,"verses":[35]}],"verseLabel":"التوبة: 35","question":"ما دلالة حرف الوعاء ﴿في﴾ في قوله تعالى: ﴿في نار جهنم﴾؟","answer":"يصور حرف ﴿في﴾ استغراق الكنوز في نار جهنم وإحاطة النار بها من كل جانب، فيكمل صورة اشتداد حرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص182، تحت «دلالة حرف الوعاء في»","url":""}]},{"id":"s9-219","number":219,"surah":9,"verses":[35],"references":[{"surah":9,"verses":[35]}],"verseLabel":"التوبة: 35","question":"لماذا خُصت الجباه والجنوب والظهور بالكي؟","answer":"خُصت الجباه والجنوب والظهور لأنها مواضع الإعراض والبخل والتقلب في النعيم؛ أو لاستيعاب جهات البدن أمامًا وجنبًا وخلفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص183، تحت «نكتة إسناد الكي إلى الأعضاء المذكورة دون غيرها»","url":""}]},{"id":"s9-220","number":220,"surah":9,"verses":[35],"references":[{"surah":9,"verses":[35]}],"verseLabel":"التوبة: 35","question":"ما موقع جملة ﴿فتكوى بها﴾ مما قبلها؟","answer":"تتفرع الجملة على إحماء الذهب والفضة: فالكنوز المحماة نفسها تصير أداة كي لأصحابها، جزاءً من جنس ما أحبوه ومنعوا حقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص183، تحت «موقع جملة فتكوى بها مما قبلها»","url":""}]},{"id":"s9-221","number":221,"surah":9,"verses":[35],"references":[{"surah":9,"verses":[35]}],"verseLabel":"التوبة: 35","question":"ما دلالة القول لأصحاب الكنوز: ﴿هذا ما كنزتم لأنفسكم﴾؟","answer":"يواجههم القول بأن ما جمعوه رجاء نفع أنفسهم صار سبب عذابها؛ فالمشار إليه هو الكنز الذي انقلبت عاقبته عليهم، وفي ذلك توبيخ يضاعف ألم الجزاء بالحسرة النفسية.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص186، تحت «موقع جملة هذا ما كنزتم لأنفسكم»","url":""}]},{"id":"s9-728","number":728,"surah":9,"verses":[35],"references":[{"surah":9,"verses":[35]}],"verseLabel":"التوبة: 35","question":"ما بلاغة ذكر المتعلَّق ﴿لأنفسكم﴾ في قوله: ﴿هذا ما كنزتم لأنفسكم﴾؟","answer":"يكشف المتعلَّق أنهم قصدوا بالكنز نفع أنفسهم، ثم جاءت العاقبة بعكس قصدهم فصار وبالًا عليها. واللام تحتمل تعليل قصدهم إلى النفع، وتحتمل معنى العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص187، تحت «بلاغة الإطناب بذكر المتعلق»","url":""}]},{"id":"s9-222","number":222,"surah":9,"verses":[35],"references":[{"surah":9,"verses":[35]}],"verseLabel":"التوبة: 35","question":"ما سرّ التعبير في قوله تعالى: ﴿فذوقوا ما كنتم تكنزون﴾، فجعل المكنوز شيئًا يذاق؟","answer":"استعير الذوق لمباشرة ألم الجزاء، وجُعل المكنوز مذوقًا لأن عاقبة الكنز وعذابه صارت كأنها عين ما يذوقون.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص188، تحت «براعة الاستعارة»","url":""}]},{"id":"s9-223","number":223,"surah":9,"verses":[36],"references":[{"surah":9,"verses":[36]}],"verseLabel":"التوبة: 36","question":"ما دلالة التعبير بلفظ ﴿عِدَّة﴾ دون «عدد» في قوله: ﴿إن عدة الشهور عند الله اثنا عشر شهرًا﴾؟","answer":"جاء لفظ ﴿عِدَّة﴾ في مقام إحصاء الشهور وتثبيت نظامها الشرعي؛ فليس المراد معلومة حسابية مجردة، بل عدد مقرر عند الله لا يتغير بأهواء الناس ولا بعبث النسيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص193، تحت «وجه التعبير بلفظ العدة دون العدد»","url":""}]},{"id":"s9-224","number":224,"surah":9,"verses":[36],"references":[{"surah":9,"verses":[36]}],"verseLabel":"التوبة: 36","question":"ما دلالة توالي القيود في قوله: ﴿في كتاب الله يوم خلق السماوات والأرض﴾؟","answer":"يربط القيد الأول عدد الشهور بكتاب الله وتقديره، ثم يردفه الظرف الزمني ليثبت أن هذا النظام مقرر منذ خلق الكون؛ فلا تملكه أعراف الجاهلية بالتبديل.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص195، تحت «دلالة توالي الجار والمجرور»","url":""}]},{"id":"s9-225","number":225,"surah":9,"verses":[36],"references":[{"surah":9,"verses":[36]}],"verseLabel":"التوبة: 36","question":"ما الأشهر الأربعة الحرم في قوله تعالى: ﴿منها أربعة حرم﴾؟","answer":"ذو القعدة وذو الحجة والمحرم ورجب؛ ثلاثة متتابعة وواحد فرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص192، تحت «المعنى الإجمالي»","url":""}]},{"id":"s9-226","number":226,"surah":9,"verses":[36],"references":[{"surah":9,"verses":[36]}],"verseLabel":"التوبة: 36","question":"لماذا أشار إلى نظام الشهور بقوله: ﴿ذلك الدين القيم﴾؟","answer":"ذلك الحساب والتحريم هو النظام المستقيم الذي لا اعوجاج فيه، والالتزام به من الدين لأنه حكم الله في الزمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص197، تحت «دلالة اسم الإشارة ومعنى مرجعه»","url":""}]},{"id":"s9-227","number":227,"surah":9,"verses":[36],"references":[{"surah":9,"verses":[36]}],"verseLabel":"التوبة: 36","question":"ما دلالة تقييد النهي بقوله: ﴿فلا تظلموا فيهن أنفسكم﴾ مع أن الظلم محرم دائمًا؟","answer":"إذا عاد الضمير إلى الأشهر الحرم كان التقييد لعظم حرمتها وشدة تبعة الظلم فيها، من غير أن يبيح الظلم في غيرها؛ فالتخصيص لزيادة التحذير والتغليظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص197، تحت «دلالة التقييد»","url":""}]},{"id":"s9-228","number":228,"surah":9,"verses":[36],"references":[{"surah":9,"verses":[36]}],"verseLabel":"التوبة: 36","question":"لماذا تكرر لفظ ﴿كافة﴾ في ﴿وقاتلوا المشركين كافة كما يقاتلونكم كافة﴾؟","answer":"يصرح التكرار بأن المماثلة تتعلق بهيئة الاجتماع في القتال أيضًا، لا بمجرد وقوع القتال من الطرفين. وفيه حث على اجتماع المؤمنين وعدم تفرقهم أمام من يجتمعون على قتالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص202، تحت «براعة الإطناب»","url":""}]},{"id":"s9-229","number":229,"surah":9,"verses":[36,123],"references":[{"surah":9,"verses":[36,123]}],"verseLabel":"التوبة: 36؛ التوبة: 123","question":"ما دلالة إطلاق معية الله للمتقين في قوله: ﴿واعلموا أن الله مع المتقين﴾؟","answer":"أُطلقت المعية لتشمل ما يحتاجه المتقون من تثبيت ونصر وتأييد، وتربط ذلك بحفظ حدود الله حتى في القتال؛ فهي وعد جامع لا يضيقه مجال واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص204، تحت «دلالة إطلاق المعية وعدم تعيين مجالها»","url":""}]},{"id":"s9-230","number":230,"surah":9,"verses":[37],"references":[{"surah":9,"verses":[37]}],"verseLabel":"التوبة: 37","question":"لماذا وصف النسيء بأنه ﴿زيادة في الكفر﴾ لا كفر مستقل؟","answer":"النسيء أضيف إلى كفرهم الأصلي؛ فهو زيادة لأنهم لم يكتفوا بالشرك، بل بدلوا تشريع الله وأحلوا وحرموا بحسب المصلحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص214، تحت «وجوه أخرى من كون النسيء زيادة في الكفر»","url":""}]},{"id":"s9-231","number":231,"surah":9,"verses":[37],"references":[{"surah":9,"verses":[37]}],"verseLabel":"التوبة: 37","question":"ما دلالة البناء للمجهول في قراءة ﴿يُضَلّ به الذين كفروا﴾؟","answer":"تركز هذه القراءة على وقوع الضلال بهم وانصرافهم عن الحق، مع عدم التصريح بالمضلِّل في الفعل. ويذكر المصدر مقابلها قراءة ﴿يَضِلّ﴾ التي تبرز وقوع الضلال منهم؛ فتتكامل الدلالتان في كشف حالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص217–218، تحت «تنوع القراءات في يضل وأثره في المعنى»","url":""}]},{"id":"s9-232","number":232,"surah":9,"verses":[37],"references":[{"surah":9,"verses":[37]}],"verseLabel":"التوبة: 37","question":"ما بلاغة الطباق في قوله: ﴿يحلونه عامًا ويحرمونه عامًا﴾؟","answer":"الطباق بين التحليل والتحريم يكشف تناقض صنيعهم في الشهر نفسه، ويصور خضوع حكمه لأهوائهم لا لشرع الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص220، تحت «بلاغة التعبير بالطباق»","url":""}]},{"id":"s9-729","number":729,"surah":9,"verses":[37],"references":[{"surah":9,"verses":[37]}],"verseLabel":"التوبة: 37","question":"ما دلالة تنكير ﴿عامًا﴾ في قوله: ﴿يحلونه عامًا ويحرمونه عامًا﴾؟","answer":"يفيد التنكير أن ذلك يقع في بعض الأعوام، فلا يلزم أنهم كانوا يبدلون الحكم على نسق ثابت في كل عام.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص221، تحت «سر تنكير المفعول فيه عامًا»","url":""}]},{"id":"s9-233","number":233,"surah":9,"verses":[37],"references":[{"surah":9,"verses":[37]}],"verseLabel":"التوبة: 37","question":"كيف أكد قوله: ﴿ليواطئوا عدة ما حرم الله﴾ الذم بما يشبه المدح؟","answer":"يبدو محافظتهم على عدد أربعة أشهر حرم موافقة محمودة في الظاهر، لكنها تزيد ذمهم؛ لأنهم وافقوا العدد وأهدروا حرمة الأشهر المعينة التي حرمها الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص223، تحت «بلاغة تأكيد الذم بما يشبه المدح في المواطأة»","url":""}]},{"id":"s9-234","number":234,"surah":9,"verses":[37],"references":[{"surah":9,"verses":[37]}],"verseLabel":"التوبة: 37","question":"ما دلالة الفاء والفعل ﴿فيحلوا﴾ في قوله: ﴿فيحلوا ما حرم الله﴾؟","answer":"تفيد الفاء أن إحلال ما حرم الله نتيجة مباشرة لتحايلهم على عدة الأشهر؛ فمهما وافقوا العدد ظاهرًا انتهى فعلهم إلى نقض الحرمة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص225، تحت «معنى التعبير بالفاء ودلالة الفعل فيحلوا»","url":""}]},{"id":"s9-235","number":235,"surah":9,"verses":[37],"references":[{"surah":9,"verses":[37]}],"verseLabel":"التوبة: 37","question":"ما سر بناء الفعل للمفعول في قوله: ﴿زين لهم سوء أعمالهم﴾؟","answer":"يصرف البناء للمفعول النظر عن المزيِّن إلى أثر التزيين فيهم؛ فقد انقلبت معاييرهم حتى رأوا العمل السيئ حسنًا واطمأنوا إلى التحايل على الشرع.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص226، تحت «سر التعبير بالبناء للمفعول»","url":""}]},{"id":"s9-236","number":236,"surah":9,"verses":[37],"references":[{"surah":9,"verses":[37]}],"verseLabel":"التوبة: 37","question":"لماذا ختم بـ﴿والله لا يهدي القوم الكافرين﴾؟","answer":"الخاتمة تناسب من زُين له الكفر فأصر عليه؛ فحرمان الهداية جزاء اختيارهم وتبديلهم حكم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص228، تحت «براعة ختم الآية»","url":""}]},{"id":"s9-237","number":237,"surah":9,"verses":[38],"references":[{"surah":9,"verses":[38]}],"verseLabel":"التوبة: 38","question":"ما سرّ توجيه العتاب إلى المؤمنين في قوله تعالى: ﴿ما لكم إذا قيل لكم انفروا... اثاقلتم﴾؟","answer":"الاستفهام ينكر حالهم عند دعوة النفير: أي عذر لكم في التثاقل بعد وضوح الأمر والحاجة؟ وفيه عتاب محرك للهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص233، تحت «بلاغة التعبير بالاستفهام المجازي»","url":""}]},{"id":"s9-238","number":238,"surah":9,"verses":[38],"references":[{"surah":9,"verses":[38]}],"verseLabel":"التوبة: 38","question":"لماذا اختيرت صيغة ﴿اثاقلتم﴾ الثقيلة صوتيًا؟","answer":"ثقل حروف ﴿اثاقلتم﴾ وتتابعها يحاكي بطء الحركة وثقل النفس، فجاء جرسها مصورًا لمعناها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص236، تحت «غرض التعبير بالمجاز»","url":""}]},{"id":"s9-239","number":239,"surah":9,"verses":[38],"references":[{"surah":9,"verses":[38]}],"verseLabel":"التوبة: 38","question":"ما الصورة في قوله: ﴿اثاقلتم إلى الأرض﴾؟","answer":"صوّرهم كأجسام ثقيلة لاصقة بالأرض لا تقوى على الارتفاع؛ وهو تمثيل لتعلقهم بالدنيا وكرههم النفير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص236–237، تحت «غرض التعبير بالمجاز»","url":""}]},{"id":"s9-240","number":240,"surah":9,"verses":[38],"references":[{"surah":9,"verses":[38]}],"verseLabel":"التوبة: 38","question":"ما لطيفة الاستفهام في قوله: ﴿أرضيتم بالحياة الدنيا من الآخرة﴾؟","answer":"الاستفهام إنكاري توبيخي؛ يكشف فساد رضاهم بالدنيا الزائلة عوضًا عن الآخرة، ويحركهم إلى ترك ما صرفهم عن النفير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص238، تحت «لطيفة الاستفهام المجازي»","url":""}]},{"id":"s9-730","number":730,"surah":9,"verses":[38],"references":[{"surah":9,"verses":[38]}],"verseLabel":"التوبة: 38","question":"ما معنى حرف الجر ﴿من﴾ في قوله: ﴿أرضيتم بالحياة الدنيا من الآخرة﴾؟","answer":"تفيد ﴿من﴾ معنى البدل؛ أي أرضيتم بالحياة الدنيا بدل الآخرة، وفي هذا التصوير إبراز لسوء ما اختاروه في هذه المفاضلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص238، تحت «معاني حرف الجر»","url":""}]},{"id":"s9-241","number":241,"surah":9,"verses":[38],"references":[{"surah":9,"verses":[38]}],"verseLabel":"التوبة: 38","question":"ما دلالة تنكير ﴿قليل﴾ في وصف متاع الحياة الدنيا؟","answer":"التنكير للتحقير والتقليل؛ فمتاع الدنيا، مهما بدا، ضئيل سريع الزوال إذا قيس بنعيم الآخرة الباقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص241، تحت «دلالة التنكير»","url":""}]},{"id":"s9-242","number":242,"surah":9,"verses":[39],"references":[{"surah":9,"verses":[39]}],"verseLabel":"التوبة: 39","question":"ما بلاغة بناء الوعيد في قوله: ﴿إلا تنفروا يعذبكم عذابًا أليمًا﴾ على جملة الشرط؟","answer":"يربط الشرط الجزاء بالتخلف ربطًا مباشرًا، فيجعل السامع أمام عاقبة اختياره ويقوي التحذير من ترك النفير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص245، تحت «بلاغة التعبير بجملة الشرط»","url":""}]},{"id":"s9-731","number":731,"surah":9,"verses":[39],"references":[{"surah":9,"verses":[39]}],"verseLabel":"التوبة: 39","question":"ما دلالة الوعيد بقوله: ﴿ويستبدل قومًا غيركم﴾؟","answer":"يهددهم بحرمان شرف نصرة الدين وإسناده إلى قوم يقومون به؛ فالدين لا يتوقف عليهم، وإنما يعود وبال التخلف وخسارته إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص246، تحت «بلاغة التعبير بالاستبدال لقوم آخرين»","url":""}]},{"id":"s9-243","number":243,"surah":9,"verses":[39],"references":[{"surah":9,"verses":[39]}],"verseLabel":"التوبة: 39","question":"ما دلالة تنكير ﴿شيئًا﴾ في قوله: ﴿ولا تضروه شيئًا﴾؟","answer":"التنكير في سياق النفي يعم كل قدر من الضرر، حتى أقله؛ فتخلفهم لا يضر الله ولا يبطل وعده بنصر رسوله، وإنما يضرهم هم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص250، تحت «لطيفة تنكير المفعول المطلق»","url":""}]},{"id":"s9-244","number":244,"surah":9,"verses":[39],"references":[{"surah":9,"verses":[39]}],"verseLabel":"التوبة: 39","question":"لماذا ختم بـ﴿والله على كل شيء قدير﴾؟","answer":"القدرة العامة تعلل تنفيذ الوعيد والاستبدال ونصر الدين بغيرهم؛ فلا يتوقف أمره على جماعة بعينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص250، تحت «سر الختم بإقرار لله بالقدرة»","url":""}]},{"id":"s9-245","number":245,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿إلا تنصروه فقد نصره الله﴾، فجاء جواب الشرط بحدث ماض؟","answer":"النصر الماضي دليل على النصر الذي يقتضيه الشرط: إن لم تنصروه فالله ناصره، فقد نصره في حال أشد من قبل. فذُكر الدليل المحقق وأغنى عن التصريح بالجواب المقدر، لتقوية اليقين بكفاية الله لرسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص257، تحت «فائدة حذف جواب الشرط»","url":""}]},{"id":"s9-246","number":246,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"ما دلالة وصف النبي ﷺ بقوله: ﴿ثاني اثنين﴾ في مشهد الهجرة؟","answer":"يصور حاله حين لم يكن معه إلا صاحب واحد، فهو أحد اثنين لا ثالث لهما. وإبراز قلة الناصر البشري في ذلك الموقف يؤكد أن الله نصره وهو بهذه الحال، فكيف يُتوهم توقف نصره على كثرة الأنصار؟","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص260، تحت «لطيفة قيد المفعول به بالحال»","url":""}]},{"id":"s9-247","number":247,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"لماذا كرر ﴿إذ﴾ ثلاث مرات في قصة الغار؟","answer":"كل ﴿إذ﴾ تستحضر مرحلة من المشهد: الإخراج، والوجود في الغار، وكلامه لصاحبه؛ فتفصل اللقطات وتحييها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص259، تحت «سر تتابع ظرف الزمان ودلالته»","url":""}]},{"id":"s9-248","number":248,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"ما دلالة جمع النبي ﷺ وصاحبه في الضمير ﴿هما﴾ في قوله: ﴿إذ هما في الغار﴾؟","answer":"في الجمع بينهما بضمير واحد تنويه بمنزلة أبي بكر وشرف صحبته للنبي في ذلك الموقف. وهو جمع في الحضور والرفقة، لا تسوية بينهما في الرتبة؛ فالنبي صاحب المقام المقدم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص261، تحت «نكتة الجمع بين النبي والصديق في ضمير واحد»","url":""}]},{"id":"s9-249","number":249,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"كيف وُجه النهي في قوله ﷺ لصاحبه: ﴿لا تحزن﴾ مع أن الحزن قد يقع بغير اختيار؟","answer":"المقصود ألا يجعل للحزن سبيلًا بالاسترسال مع أسبابه وآثاره؛ فالنهي يرشد إلى ما يمكن اختياره مما يزيله. وقد جاء التعليل ﴿إن الله معنا﴾ بما يبعث الثقة والطمأنينة ويذهب أثر القلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص262–263، تحت «غرض التعبير بمقول القول بجملة إنشائية»","url":""}]},{"id":"s9-250","number":250,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"لماذا علل النهي عن الحزن بقوله: ﴿إن الله معنا﴾؟","answer":"المعية الإلهية معية حفظ ونصر وعلم، وهي أقوى سبب لزوال الحزن؛ فمن كان الله معه لا تضره قلة العدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص263، تحت «نكتة تعليل النهي بكونهما بمعية الله تعالى»","url":""}]},{"id":"s9-251","number":251,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"ما بلاغة إسناد إنزال السكينة إلى الله في قوله: ﴿فأنزل الله سكينته عليه﴾؟","answer":"إسناد الإنزال إلى الاسم الجليل وإضافة السكينة إليه يعظمان أثر الطمأنينة والحفظ، ويبينان أن مصدر الثبات في ذلك الموقف هو الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص265، تحت «بلاغة التعبير بالفعل الماضي مسندا إلى الاسم الجليل»","url":""}]},{"id":"s9-732","number":732,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"إلى من يعود الضمير في قوله: ﴿فأنزل الله سكينته عليه﴾، وما دلالته؟","answer":"الجمهور على عوده إلى النبي ﷺ لمراعاة أصل الحديث واتساق ضمائره؛ وقيل إلى أبي بكر لقرب ذكره، وقيل إليهما مع إفراد الضمير لتلازمهما في الموقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص266، تحت «تنوع مرجع الضمير عليه ودلالته»","url":""}]},{"id":"s9-252","number":252,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"ما دلالة عطف قوله: ﴿وأيده بجنود لم تروها﴾ على إنزال السكينة؟","answer":"يجمع العطف صور التأييد الإلهي للرسول ﷺ؛ فالسكينة تثبيت باطن، والجنود مدد يحفظه ويصرف عنه الأذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص266، تحت «دلالة عطف الجملة بالواو»","url":""}]},{"id":"s9-733","number":733,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"ما سر تنكير ﴿جنود﴾ ووصفها بقوله: ﴿لم تروها﴾؟","answer":"يفيد التنكير تعظيم جنود لا يحيط المخاطبون بعددها أو حقيقتها، ويبين وصفها أن تأييد الله قد يجري خفيًا عن الأبصار مع تحقق أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص267، تحت «سر التنكير والوصف بالجملة»","url":""}]},{"id":"s9-253","number":253,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"ما دلالة القصر بتعريف الطرفين في قوله: ﴿وكلمة الله هي العليا﴾؟","answer":"تعريف الطرفين مع ضمير الفصل يقوي اختصاص كلمة الله بالعلو؛ فهي العليا في ذاتها على وجه ثابت، بخلاف كلمة الكفر التي جعلها الله سفلى.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص269، تحت «سر التعبير بأسلوب القصر بتعريف الطرفين»","url":""}]},{"id":"s9-254","number":254,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"ما بلاغة التعبير بالفعل الماضي في قوله: ﴿وجعل كلمة الذين كفروا السفلى﴾؟","answer":"يصور الفعل إحداث خفض كلمة الكفر بعد محاولة ارتفاعها، ويعرض النتيجة واقعة متحققة بفعل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص267، تحت «براعة التعبير بعطف النتيجة وبالفعل الماضي»","url":""}]},{"id":"s9-255","number":255,"surah":9,"verses":[40],"references":[{"surah":9,"verses":[40]}],"verseLabel":"التوبة: 40","question":"لماذا ختم بـ﴿والله عزيز حكيم﴾؟","answer":"﴿عزيز﴾ غالب ينصر رسوله ويخفض الكفر، و﴿حكيم﴾ يدبر ذلك بأسباب ظاهرة وخفية في أوقاتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص270، تحت «براعة التذييل وسر الختم بالعزة والحكم»","url":""}]},{"id":"s9-256","number":256,"surah":9,"verses":[41],"references":[{"surah":9,"verses":[41]}],"verseLabel":"التوبة: 41","question":"ما بلاغة الاستعارة في قوله: ﴿انفروا خفافًا وثقالًا﴾؟","answer":"استعيرت الخفة والثقل لأحوال النشاط والعوائق، فجمع الضدان أحوال المكلفين: شبابًا وشيوخًا، وغنى وفقرًا، ونشاطًا وثقلًا؛ فلا تكون الحال ذريعة للتخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص278، تحت «بلاغة التعبير بالاستعارة»","url":""}]},{"id":"s9-257","number":257,"surah":9,"verses":[41],"references":[{"surah":9,"verses":[41]}],"verseLabel":"التوبة: 41","question":"ما المقصود بـ﴿خفافًا وثقالًا﴾، ولماذا تُرك اللفظ محتملًا؟","answer":"يتسع اللفظ لأحوال متعددة من النشاط والفتور، والشباب والشيخوخة، وقلة المال وكثرته، وقلة العيال وكثرتهم. وهذه المعاني كلها صالحة للمراد، فجمعت العبارة الوجيزة تنوع أحوال المستجيبين للنفير.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص278–279، تحت «بلاغة التعبير بالاستعارة»","url":""}]},{"id":"s9-258","number":258,"surah":9,"verses":[41],"references":[{"surah":9,"verses":[41]}],"verseLabel":"التوبة: 41","question":"ما سرّ تقديم الجهاد بالأموال على الأنفس مرة أخرى؟","answer":"من وجوه التقديم أن المال قوام تجهيز الجيش والإنفاق عليه، فظهرت منزلته في إقامة الجهاد. وذكر المصدر أيضًا أن تقديم بذله يواجه تعلق النفس به وخوفها من ضياعه، فيهيئها للبذل والتضحية.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص280–281، تحت «سر تقديم الأموال على الأنفس»","url":""}]},{"id":"s9-259","number":259,"surah":9,"verses":[41],"references":[{"surah":9,"verses":[41]}],"verseLabel":"التوبة: 41","question":"ما دلالة موقع قوله: ﴿ذلكم خير لكم﴾ بعد الأمر بالجهاد؟","answer":"تأتي الجملة بعد التكليف لتقرر أن امتثاله هو الخير لهم في ثوابه وعاقبته ونصر جماعتهم، وإن شق في الحال؛ فالعبرة بالمآل لا بالراحة العاجلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص282، تحت «موقع قوله ذلكم خير لكم مما قبله ودلالته»","url":""}]},{"id":"s9-260","number":260,"surah":9,"verses":[41],"references":[{"surah":9,"verses":[41]}],"verseLabel":"التوبة: 41","question":"ما سر ختم الآية بقوله: ﴿إن كنتم تعلمون﴾ مع حذف جواب الشرط؟","answer":"حُذف الجواب لدلالة السياق عليه: إن كنتم تعلمون علمًا نافعًا أدركتم خير الجهاد وامتثلتم. وفي الحذف حث على موازنة الخير الباقي بالمشقة العابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص285، تحت «سر ختم الآية بجملة شرط محذوف الجواب»","url":""}]},{"id":"s9-261","number":261,"surah":9,"verses":[42],"references":[{"surah":9,"verses":[42]}],"verseLabel":"التوبة: 42","question":"ما وجه البلاغة في التعبير بأسلوب الشرط لو في قوله تعالى: ﴿لو كان عرضًا قريبًا وسفرًا قاصدًا لاتبعوك﴾؟","answer":"تكشف الجملة معيار المنافقين: لو كانت منفعة سهلة وسفرًا معتدلًا لاتبعوا، لكنهم تخلفوا حين بعدت المسافة وشقت.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص292، تحت «بلاغة التعبير بأسلوب الشرط لو»","url":""}]},{"id":"s9-262","number":262,"surah":9,"verses":[42],"references":[{"surah":9,"verses":[42]}],"verseLabel":"التوبة: 42","question":"ما سر التعبير بخبر ﴿كان﴾ نكرة موصوفة في قوله: ﴿لو كان عرضًا قريبًا﴾؟","answer":"جاء ﴿عرضًا﴾ نكرة ليصدق على أي متاع دنيوي زائل، ووصفه بالقرب يبرز أن الذي يحركهم منفعة سهلة عاجلة لا إخلاص النصرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص293، تحت «سر التعبير بخبر كان نكرة موصوفة»","url":""}]},{"id":"s9-263","number":263,"surah":9,"verses":[42],"references":[{"surah":9,"verses":[42]}],"verseLabel":"التوبة: 42","question":"ما دلالة وصف السفر بقوله: ﴿قاصدًا﴾؟","answer":"القاصد سفر متوسط سهل، لا يبلغ مشقة المسافة البعيدة. فالوصف يكشف تعلق المنافقين بالراحة والدعة، وأن اتباعهم المفترض مشروط بسفر يسهل عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص289–290، 293، تحت «شرح المفردات؛ سر العطف على خبر كان»","url":""}]},{"id":"s9-264","number":264,"surah":9,"verses":[42],"references":[{"surah":9,"verses":[42]}],"verseLabel":"التوبة: 42","question":"ما بلاغة التعبير بالفعل اللازم في قوله: ﴿ولكن بعدت عليهم الشقة﴾؟","answer":"أُسند البعد إلى الشقة نفسها، فصُوّر الطريق كأنه ينأى عنهم؛ وهو تصوير يفضح نفور نفوسهم وضعف هممهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج17، ص296، تحت «بلاغة التعبير بالفعل اللازم بعدت»","url":""}]}]);
